          "pt": "A conexão dos kobolds com os dragões pode se manifestar de maneiras imprevisíveis em um kobold individual. Escolha uma das seguintes opções de legado para o seu kobold:\n\n• Astúcia. Você tem proficiência em uma das seguintes perícias à sua escolha: Arcanismo, Investigação, Medicina, Prestidigitação ou Sobrevivência.\n\n• Desafio. Você tem vantagem em salvaguardas para evitar ou encerrar a condição amedrontado em si mesmo.\n\n• Feitiçaria Dracônica. Você conhece um truque à sua escolha da lista de magias de feiticeiro. Inteligência, Sabedoria ou Carisma é o seu atributo de conjuração para esse truque (escolha quando selecionar esta raça).",
          "en": "Kobolds' connection to dragons can manifest in unpredictable ways in an individual kobold. Choose one of the following legacy options for your kobold:\n\n• Craftiness. You have proficiency in one of the following skills of your choice: Arcana, Investigation, Medicine, Sleight of Hand, or Survival.\n\n• Defiance. You have advantage on saving throws to avoid or end the frightened condition on yourself.\n\n• Draconic Sorcery. You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race)."
