          "pt": "Imediatamente após acertar uma criatura com um ataque corpo a corpo como parte da ação de Ataque em seu turno, você pode usar uma Ação Bônus para tentar empurrar aquele alvo com seus chifres. O alvo não pode ser mais do que um tamanho maior do que você e deve estar a até 1,5 metro de você. A menos que seja bem-sucedido em uma salvaguarda de Força contra uma CD igual a 8 + seu Bônus de Proficiência + seu modificador de Força, você o empurra até 3 metros para longe de você.",
          "en": "Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be no more than one size larger than you and within 5 feet of you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you"
