// === SPELLS (SRD selection) ===
// Format: { id, level, school, classes:[], castingTime, range, components, duration, ritual, concentration, desc }
const SPELLS = [
  // Cantrips
  { id: 'acidSplash',     level: 0, school: 'conjuration', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você arremessa uma bolha de ácido. Escolha uma criatura que você possa ver dentro do alcance, ou escolha duas criaturas que você possa ver dentro do alcance que estejam a até 1,5 metro uma da outra. Um alvo deve ser bem-sucedido em uma salvaguarda de Destreza ou sofrerá 1d6 de dano de ácido.\n\nO dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).", en: "You hurl a bubble of acid. Choose one creature you can see within range, or choose two creatures you can see within range that are within 5 feet of each other. A target must succeed on a Dexterity saving throw or take 1d6 acid damage.\n\nThis spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)." } },
  { id: 'chillTouch',     level: 0, school: 'necromancy', classes: ['sorcerer','warlock','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: '1 round', desc: { pt: "Você cria uma mão esquelética e fantasmagórica no espaço de uma criatura dentro do alcance. Faça um ataque à distância com magia contra a criatura para atacá-la com o frio da sepultura. Se atingir, o alvo sofre 1d8 de dano necrótico e não pode recuperar Pontos de Vida até o início do seu próximo turno. Até lá, a mão fantasmagórica se agarra ao alvo.\n\nSe você atingir um alvo morto-vivo, ele também tem desvantagem em jogadas de ataque contra você até o final do seu próximo turno.\n\nO dano desta magia aumenta em 1d8 quando você alcança o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", en: "You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can't regain hit points until the start of your next turn. Until then, the hand clings to the target.\n\nIf you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)." } },
  { id: 'eldritchBlast',  level: 0, school: 'evocation', classes: ['warlock'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Um feixe de energia crepitante dispara em direção a uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Em um acerto, o alvo sofre 1d10 de dano de energia.\n\nA magia cria mais de um feixe quando você atinge níveis superiores: dois feixes no 5º nível, três feixes no 11º nível e quatro feixes no 17º nível. Você pode direcionar os feixes para o mesmo alvo ou para alvos diferentes. Faça uma jogada de ataque separada para cada feixe.", en: "A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage.\n\nThe spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam." } },
  { id: 'fireBolt',       level: 0, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você arremessa uma fagulha de fogo contra uma criatura ou objeto dentro do alcance. Faça um ataque à distância com magia contra o alvo. Em um acerto, o alvo sofre 1d10 de dano de fogo. Um objeto inflamável atingido por esta magia se incendeia se não estiver sendo vestido ou carregado.\n\nO dano desta magia aumenta em 1d10 quando você atinge o 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).", en: "You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried. \n\nThis spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)." } },
  { id: 'guidance',       level: 0, school: 'divination', classes: ['cleric','druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '1 min, conc', concentration: true, desc: { pt: "Você toca uma criatura voluntária. Uma vez antes de a magia terminar, o alvo pode rolar um d4 e adicionar o número obtido a um teste de atributo à sua escolha. Ele pode rolar o dado antes ou depois de realizar o teste de atributo. A magia então termina.", en: "You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends." } },
  { id: 'light',          level: 0, school: 'evocation', classes: ['bard','cleric','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, M', duration: '1 hour', desc: { pt: "Você toca um objeto que não tenha mais de 3 metros em qualquer dimensão. Até a magia terminar, o objeto emite luz plena em um raio de 6 metros e penumbra por mais 6 metros adicionais. A luz pode ter a cor que você quiser. Cobrir totalmente o objeto com algo opaco bloqueia a luz. A magia termina se você a conjurar novamente ou a dispensar como uma ação.\n\nSe você tiver como alvo um objeto segurado ou vestido por uma criatura hostil, essa criatura deve ser bem-sucedida em um teste de resistência de Destreza para evitar a magia.", en: "You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.\n\nIf you target an object held or worn by a hostile creature, that creature must succeed on a Dexterity saving throw to avoid the spell." } },
  { id: 'mageHand',       level: 0, school: 'conjuration', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: '1 min', desc: { pt: "Uma mão espectral flutuante aparece em um ponto que você escolher dentro do alcance. A mão dura pela duração. A mão desaparece se em algum momento estiver a mais de 9 metros de você ou se você conjurar esta magia novamente.\nAo conjurar a magia, você pode usar a mão para manipular um objeto, abrir uma porta ou recipiente destrancado, guardar ou pegar um item de um recipiente aberto ou derramar o conteúdo de um frasco.\nComo uma ação de Magia em seus turnos posteriores, você pode controlar a mão dessa forma novamente. Como parte dessa ação, você pode mover a mão até 9 metros.\nA mão não pode atacar, ativar itens mágicos ou carregar mais de 5 kg.", en: "A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.\n\nYou can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.\n\nThe hand can't attack, activate magic items, or carry more than 10 pounds." } },
  { id: 'minorIllusion',  level: 0, school: 'illusion', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'S, M', duration: '1 min', desc: { pt: "Você cria um som ou a imagem de um objeto dentro do alcance que dura pela duração. A ilusão também termina se você a dispensar como uma ação ou conjurar esta magia novamente.\n\nSe você criar um som, seu volume pode variar de um sussurro a um grito. Pode ser a sua voz, a voz de outra pessoa, o rugido de um leão, o rufar de tambores ou qualquer outro som que você escolher. O som continua ininterrupto por toda a duração, ou você pode produzir sons distintos em momentos diferentes antes de a magia terminar.\n\nSe você criar a imagem de um objeto — como uma cadeira, pegadas de lama ou um pequeno baú — ela não pode ser maior que um cubo de 1,5 metro. A imagem não pode produzir som, luz, cheiro ou qualquer outro efeito sensorial. A interação física com a imagem revela que ela é uma ilusão, pois objetos passam através dela.\n\nSe uma criatura usar sua ação para examinar o som ou a imagem, ela pode determinar que se trata de uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD de resistência da sua magia. Se uma criatura discernir a ilusão pelo que ela realmente é, a ilusão torna-se tênue para a criatura.", en: "You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.\n\nIf you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nIf you create an image of an object-such as a chair, muddy footprints, or a small chest-it must be no larger than a 5-foot cube. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.\n\nIf a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature." } },
  { id: 'poisonSpray',    level: 0, school: 'conjuration', classes: ['druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: '10 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você estende sua mão em direção a uma criatura que possa ver dentro do alcance e projeta uma baforada de gás nocivo a partir da sua palma. A criatura deve ser bem-sucedida em um teste de resistência de Constituição ou sofrerá 1d12 de dano de veneno.\n\nO dano desta magia aumenta em 1d12 quando você atinge o 5º nível (2d12), 11º nível (3d12) e 17º nível (4d12).", en: "You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a Constitution saving throw or take 1d12 poison damage. \n\nThis spell's damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12)." } },
  { id: 'prestidigitation', level: 0, school: 'transmutation', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '10 ft', components: 'V, S', duration: '1 hour', desc: { pt: "Esta magia é um truque mágico menor que conjuradores novatos usam para praticar. Você cria um dos seguintes efeitos mágicos dentro do alcance:\n\n- Você cria um efeito sensorial instantâneo e inofensivo, como uma chuva de faíscas, uma lufada de vento, notas musicais suaves ou um odor estranho.\n- Você acende ou apaga instantaneamente uma vela, uma tocha ou uma pequena fogueira.\n- Você limpa ou suja instantaneamente um objeto não maior que um cubo de 30 centímetros de lado.\n- Você resfria, aquece ou dá sabor a até um cubo de 30 centímetros de lado de material não vivo por 1 hora.\n- Você faz uma cor, uma pequena marca ou um símbolo aparecer em um objeto ou superfície por 1 hora.\n- Você cria uma bugiganga não mágica ou uma imagem ilusória que caiba na sua mão e que dura até o final do seu próximo turno.\n\nSe conjurar esta magia várias vezes, você pode manter ativos até três de seus efeitos não instantâneos ao mesmo tempo, e pode dispensar qualquer um desses efeitos com uma ação.", en: "This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within Range:\n\n- You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\n- You instantaneously light or snuff out a candle, a torch, or a small campfire.\n- You instantaneously clean or soil an object no larger than 1 cubic foot.\n- You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\n- You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\n- You create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.\n\nIf you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action." } },
  { id: 'rayOfFrost',     level: 0, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Um raio gélido de luz branca-azulada dispara em direção a uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se acertar, ele sofre 1d8 de dano de frio e seu deslocamento é reduzido em 3 metros até o início do seu próximo turno.\n\nO dano da magia aumenta em 1d8 quando você atinge o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", en: "A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)." } },
  { id: 'sacredFlame',    level: 0, school: 'evocation', classes: ['cleric'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Um resplendor semelhante a chamas desce sobre uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de resistência de Destreza ou sofrerá 1d8 de dano radiante. O alvo não recebe nenhum benefício de cobertura para esse teste de resistência.\n\nO dano da magia aumenta em 1d8 quando você atinge o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", en: "Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)." } },
  { id: 'shockingGrasp',  level: 0, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Eletricidade salta da sua mão para desferir um choque em uma criatura que você tente tocar. Faça um ataque corpo a corpo com magia contra o alvo. Você tem vantagem na jogada de ataque se o alvo estiver usando armadura de metal. Se acertar, o alvo sofre 1d8 de dano elétrico e não pode usar reações até o início do próximo turno dele.\n\nO dano da magia aumenta em 1d8 quando você atinge o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", en: "Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can't take reactions until the start of its next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)." } },
  { id: 'spareDying',     level: 0, school: 'necromancy', classes: ['cleric'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Você toca uma criatura viva que tenha 0 Pontos de Vida. A criatura fica estabilizada. Esta magia não tem efeito sobre mortos-vivos ou constructos.", en: "You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs." } },
  { id: 'thaumaturgy',    level: 0, school: 'transmutation', classes: ['cleric'], castingTime: '1 action', range: '30 ft', components: 'V', duration: '1 min', desc: { pt: "Você manifesta um prodígio menor, um sinal de poder sobrenatural, dentro do alcance. Você cria um dos seguintes efeitos mágicos dentro do alcance:\n\n- Sua voz ressoa até três vezes mais alto que o normal por 1 minuto.\n- Você faz chamas tremularem, brilharem mais, enfraquecerem ou mudarem de cor por 1 minuto.\n- Você causa tremores inofensivos no solo por 1 minuto.\n- Você cria um som instantâneo originado de um ponto à sua escolha dentro do alcance, como um estrondo de trovão, o grasnado de um corvo ou sussurros sinistros.\n- Você faz instantaneamente uma porta ou janela destrancada se abrir de supetão ou se fechar com violência.\n- Você altera a aparência de seus olhos por 1 minuto. Se conjurar esta magia várias vezes, você pode manter ativos até três de seus efeitos de 1 minuto simultaneamente, e pode dispensar qualquer um desses efeitos com uma ação.", en: "You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within Range:\n\n- Your voice booms up to three times as loud as normal for 1 minute.\n- You cause flames to flicker, brighten, dim, or change color for 1 minute.\n- You cause harmless tremors in the ground for 1 minute.\n- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\n- You instantaneously cause an unlocked door or window to fly open or slam shut.\n- You alter the appearance of your eyes for 1 minute. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action." } },
  { id: 'viciousMockery', level: 0, school: 'enchantment', classes: ['bard'], castingTime: '1 action', range: '60 ft', components: 'V', duration: 'Instant', desc: { pt: "Você profere uma saraivada de insultos mesclados com encantamentos sutis contra uma criatura que possa ver dentro do alcance. Se o alvo puder ouvi-lo (embora não precise compreendê-lo), ele deve ser bem-sucedido em um teste de resistência de Sabedoria ou sofrerá 1d4 de dano psíquico e terá desvantagem na próxima jogada de ataque que fizer antes do final do próximo turno dele.\n\nO dano desta magia aumenta em 1d4 quando você atinge o 5º nível (2d4), 11º nível (3d4) e 17º nível (4d4).", en: "You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a Wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.\n\nThis spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4)." } },
  { id: 'druidcraft',     level: 0, school: 'transmutation', classes: ['druid'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Sussurrando aos espíritos da natureza, você cria um dos seguintes efeitos dentro do alcance.\nSensor Climático. Você cria um efeito sensorial Miúdo e inofensivo que prevê como será o clima na sua localização nas próximas 24 horas. O efeito pode se manifestar como uma esfera dourada para céu limpo, uma nuvem para chuva, flocos de neve caindo para neve e assim por diante. Esse efeito persiste por 1 rodada.\nFlorescer. Você faz instantaneamente uma flor desabrochar, uma vagem de sementes se abrir ou um broto de folha florescer.\nEfeito Sensorial. Você cria um efeito sensorial inofensivo, como folhas caindo, fadas espectrais dançando, uma brisa suave, o som de um animal ou o leve odor de gambá. O efeito deve caber em um Cubo de 1,5 metro.\nBrincar com Fogo. Você acende ou apaga uma vela, uma tocha ou uma fogueira.", en: "Whispering to the spirits of nature, you create one of the following effects within range:\n\n- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\n- You instantly make a flower blossom, a seed pod open, or a leaf bud bloom.\n- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint odor of skunk. The effect must fit in a 5-foot cube.\n- You instantly light or snuff out a candle, a torch, or a small campfire." } },

  // 1st Level
  { id: 'burningHands',   level: 1, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self (15-ft cone)', components: 'V, S', duration: 'Instant', desc: { pt: "Conforme você mantém suas mãos com os polegares se tocando e os dedos estendidos, uma fina lâmina de chamas brota da ponta dos seus dedos estendidos. Cada criatura em um cone de 4,5 metros deve fazer uma salvaguarda de Destreza. Uma criatura sofre 3d6 de dano de fogo em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida.\n\nO fogo incendeia quaisquer objetos inflamáveis na área que não estejam sendo vestidos ou carregados.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 1º.", en: "As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a Dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire ignites any flammable objects in the area that aren't being worn or carried.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st." } },
  { id: 'charmPerson',    level: 1, school: 'enchantment', classes: ['bard','druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: '1 hour', desc: { pt: "Você tenta enfeitiçar um humanoide que possa ver dentro do alcance. Ele deve fazer uma salvaguarda de Sabedoria, e o faz com vantagem se você ou seus companheiros estiverem lutando contra ele. Se falhar na salvaguarda, ele fica enfeitiçado por você até a magia terminar ou até você ou seus companheiros fazerem qualquer coisa prejudicial a ele. A criatura enfeitiçada considera você um conhecido amigável. Quando a magia termina, a criatura sabe que foi enfeitiçada por você.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 1º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", en: "You attempt to charm a humanoid you can see within range. It must make a Wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them." } },
  { id: 'cureWounds',     level: 1, school: 'evocation', classes: ['bard','cleric','druid','paladin','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Uma criatura que você tocar recupera uma quantidade de Pontos de Vida igual a 1d8 + seu modificador de habilidade de conjuração. Esta magia não tem efeito em mortos-vivos ou constructos.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, a cura aumenta em 1d8 para cada círculo do espaço acima do 1º.", en: "A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st." } },
  { id: 'detectMagic',    level: 1, school: 'divination', classes: ['bard','cleric','druid','paladin','ranger','sorcerer','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 min, conc', ritual: true, concentration: true, desc: { pt: "Pela duração, você percebe a presença de magia a até 9 metros de você. Se perceber magia dessa forma, você pode usar sua ação para ver uma aura tênue ao redor de qualquer criatura ou objeto visível na área que carregue magia, e você descobre a escola de magia dela, se houver.\n\nA magia pode penetrar a maioria das barreiras, mas é bloqueada por 30 centímetros de pedra, 2,5 centímetros de metal comum, uma folha fina de chumbo ou 90 centímetros de madeira ou terra.", en: "For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt." } },
  { id: 'disguiseSelf',   level: 1, school: 'illusion', classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '1 hour', desc: { pt: "Você faz com que você mesmo — incluindo suas roupas, armadura, armas e outros pertences em sua pessoa — pareça diferente até a magia acabar ou até você usar sua ação para dispensá-la. Você pode parecer 30 centímetros mais baixo ou mais alto e pode parecer magro, gordo ou algo intermediário. Você não pode mudar o seu tipo físico corporal, portanto deve adotar uma forma que tenha a mesma disposição básica de membros. Caso contrário, a extensão da ilusão fica a seu critério.\n\nAs alterações causadas por esta magia não resistem a uma inspeção física. Por exemplo, se você usar esta magia para adicionar um chapéu ao seu traje, objetos atravessam o chapéu e qualquer pessoa que o toque não sentirá nada ou sentirá sua cabeça e seu cabelo. Se usar esta magia para parecer mais magro do que é, a mão de alguém que se estender para tocar você esbarrará em você enquanto ainda aparenta estar no meio do ar.\n\nPara discernir que você está disfarçado, uma criatura pode usar uma ação para inspecionar sua aparência e deve ser bem-sucedida em um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia.", en: "You make yourself-including your clothing, armor, weapons, and other belongings on your person- look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can't change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nTo discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC." } },
  { id: 'faerieFire',     level: 1, school: 'evocation', classes: ['bard','druid'], castingTime: '1 action', range: '60 ft', components: 'V', duration: '1 min, conc', concentration: true, desc: { pt: "Cada objeto em um cubo de 6 metros dentro do alcance é contornado por uma luz azul, verde ou violeta (à sua escolha). Qualquer criatura na área quando a magia é conjurada também é contornada pela luz se falhar em um teste de resistência de Destreza. Pela duração, objetos e criaturas afetadas emitem luz penumbrosa em um raio de 3 metros.\n\nQualquer jogada de ataque contra uma criatura ou objeto afetado tem vantagem se o atacante puder vê-lo, e a criatura ou objeto afetado não pode se beneficiar de estar invisível.", en: "Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.\n\nAny attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can't benefit from being invisible." } },
  { id: 'healingWord',    level: 1, school: 'evocation', classes: ['bard','cleric','druid'], castingTime: '1 bonus action', range: '60 ft', components: 'V', duration: 'Instant', desc: { pt: "Uma criatura à sua escolha que você possa ver dentro do alcance recupera pontos de vida iguais a 1d4 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, a cura aumenta em 1d4 para cada círculo do espaço acima do 1º.", en: "A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st." } },
  { id: 'magicMissile',   level: 1, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você cria três dardos brilhantes de energia mágica. Cada dardo atinge uma criatura à sua escolha que você possa ver dentro do alcance. Um dardo causa 1d4 + 1 de dano de energia ao seu alvo. Todos os dardos atingem simultaneamente e você pode direcioná-los para atingir uma criatura ou várias.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, a magia cria um dardo adicional para cada círculo do espaço acima do 1º.", en: "You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st." } },
  { id: 'shield',         level: 1, school: 'abjuration', classes: ['sorcerer','wizard'], castingTime: '1 reaction', range: 'Self', components: 'V, S', duration: '1 round', desc: { pt: "Uma barreira imperceptível de energia mágica o protege. Até o início do seu próximo turno, você recebe +5 de bônus na CA, inclusive contra o ataque que desencadeou a magia, e não sofre dano de Mísseis Mágicos.", en: "An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile." } },
  { id: 'sleep',          level: 1, school: 'enchantment', classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '90 ft', components: 'V, S, M', duration: '1 min', desc: { pt: "Esta magia faz criaturas caírem em um sono mágico. Role 5d8; o total é a quantidade de Pontos de Vida de criaturas que esta magia pode afetar. Criaturas a até 6 metros de um ponto escolhido por você dentro do alcance são afetadas em ordem crescente dos seus Pontos de Vida atuais (ignorando criaturas inconscientes).\n\nComeçando pela criatura com o menor valor de Pontos de Vida atuais, cada criatura afetada por esta magia cai inconsciente até a magia terminar, o adormecido sofrer dano ou alguém usar uma ação para sacudir ou esbofetear o adormecido para acordá-lo. Subtraia os Pontos de Vida de cada criatura do total antes de passar para a criatura com a próxima menor quantidade de Pontos de Vida. Os Pontos de Vida de uma criatura devem ser iguais ou inferiores ao total restante para que ela seja afetada.\n\nMortos-vivos e criaturas imunes a serem enfeitiçadas não são afetados por esta magia.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, role 2d8 adicionais para cada círculo do espaço acima do 1º.", en: "This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\nUndead and creatures immune to being charmed aren't affected by this spell.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st." } },
  { id: 'thunderwave',    level: 1, school: 'evocation', classes: ['bard','druid','sorcerer','wizard'], castingTime: '1 action', range: 'Self (15-ft cube)', components: 'V, S', duration: 'Instant', desc: { pt: "Uma onda de força trovejante irrompe a partir de você. Cada criatura em um cubo de 4,5 metros originando-se de você deve realizar um teste de resistência de Constituição. Em caso de falha no teste, uma criatura sofre 2d8 de dano trovejante e é empurrada 3 metros para longe de você. Em caso de sucesso na salvaguarda, a criatura sofre metade desse dano e não é empurrada.\n\nAlém disso, objetos soltos que estejam completamente dentro da área de efeito são empurrados automaticamente 3 metros para longe de você pelo efeito da magia, e a magia emite um estrondo trovejante audível a até 90 metros.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 1º.", en: "A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a Constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn't pushed.\n\nIn addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell's effect, and the spell emits a thunderous boom audible out to 300 feet.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st." } },
  { id: 'bless',          level: 1, school: 'enchantment', classes: ['cleric','paladin'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Você abençoa até três criaturas à sua escolha dentro do alcance. Sempre que um alvo fizer uma jogada de ataque ou uma salvaguarda antes da magia acabar, o alvo pode rolar um d4 e adicionar o número rolado à jogada de ataque ou salvaguarda.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 1º.", en: "You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st." } },
  { id: 'commandSpell',   level: 1, school: 'enchantment', classes: ['cleric','paladin'], castingTime: '1 action', range: '60 ft', components: 'V', duration: '1 round', desc: { pt: "Você pronuncia uma ordem de uma palavra para uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou seguirá o comando no próximo turno dele. A magia não tem efeito se o alvo for um morto-vivo, se não compreender o seu idioma ou se o seu comando for diretamente prejudicial a ele.\n\nAlguns comandos típicos e seus efeitos são apresentados a seguir. Você pode emitir um comando diferente dos descritos aqui. Se fizer isso, o Mestre determina como o alvo se comporta. Se o alvo não puder cumprir o seu comando, a magia termina.\n\nAproximar. O alvo se move em sua direção pela rota mais curta e direta, terminando seu turno se mover para até 1,5 metro de você.\n\nLargar. O alvo solta o que estiver segurando e então encerra seu turno.\n\nFugir. O alvo passa seu turno se afastando de você pelo meio mais rápido disponível.\n\nProstrar-se. O alvo se joga no chão e fica caído, encerrando seu turno.\n\nParar. O alvo não se move e não realiza ações.\n\nUma criatura voadora permanece no ar, desde que seja capaz de fazê-lo. Se precisar se mover para permanecer no ar, ela voa a distância mínima necessária para continuar no ar.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode afetar uma criatura adicional para cada círculo do espaço acima do 1º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", en: "You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn't understand your language, or if your command is directly harmful to it.\n\nSome typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can't follow your command, the spell ends.\n\nApproach. The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\n\nDrop. The target drops whatever it is holding and then ends its turn.\n\nFlee. The target spends its turn moving away from you by the fastest available means.\n\nGrovel. The target falls prone and then ends its turn.\n\nHalt. The target doesn't move and takes no actions.\n\nA flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them." } },
  { id: 'guidingBolt',    level: 1, school: 'evocation', classes: ['cleric'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: '1 round', desc: { pt: "Um lampejo de luz dispara em direção a uma criatura à sua escolha dentro do alcance. Faça um ataque à distância com magia contra o alvo. Em um acerto, o alvo sofre 4d6 de dano radiante, e a próxima jogada de ataque feita contra este alvo antes do fim do seu próximo turno tem vantagem, graças à luz mística penumbrosa que cintila sobre o alvo até lá.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 1º.", en: "A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st." } },
  { id: 'sanctuary',      level: 1, school: 'abjuration', classes: ['cleric'], castingTime: '1 bonus action', range: '30 ft', components: 'V, S, M', duration: '1 min', desc: { pt: "Você protege uma criatura dentro do alcance contra ataques. Até a magia terminar, qualquer criatura que mire a criatura protegida com um ataque ou magia nociva deve primeiro realizar um teste de resistência de Sabedoria. Em caso de falha no teste, a criatura deve escolher um novo alvo ou perder o ataque ou magia. Esta magia não protege a criatura protegida contra efeitos de área, como a explosão de uma bola de fogo.\n\nSe a criatura protegida fizer um ataque, conjurar uma magia que afete um inimigo ou causar dano a outra criatura, esta magia termina.", en: "You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a Wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball.\n\nIf the warded creature makes an attack, casts a spell that affects an enemy, or deals damage to another creature, this spell ends." } },
  { id: 'huntersMark',    level: 1, school: 'divination', classes: ['ranger'], castingTime: '1 bonus action', range: '90 ft', components: 'V', duration: '1 hour, conc', concentration: true, desc: { pt: "Você escolhe uma criatura que possa ver dentro do alcance e a marca misticamente como sua presa. Até a magia terminar, você causa 1d6 de dano adicional ao alvo sempre que o atingir com um ataque com arma, e você tem vantagem em qualquer teste de Sabedoria (Percepção) ou Sabedoria (Sobrevivência) feito para encontrá-lo. Se o alvo for reduzido a 0 pontos de vida antes desta magia terminar, você pode usar uma ação bônus em um turno subsequente seu para marcar uma nova criatura.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º ou 4º círculo, você pode manter sua concentração na magia por até 8 horas. Quando você usar um espaço de magia de 5º círculo ou superior, você pode manter sua concentração na magia por até 24 horas.", en: "You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours." } },
  { id: 'thunderousSmite', level: 1, school: 'evocation', classes: ['paladin'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 min, conc', concentration: true, desc: { pt: "Na primeira vez que você atingir com um ataque corpo a corpo com arma durante a duração desta magia, sua arma ecoa com um trovão que é audível a até 90 metros de você, e o ataque causa 2d6 de dano trovejante adicional ao alvo. Além disso, se o alvo for uma criatura, ele deve ser bem-sucedido em uma salvaguarda de Força ou será empurrado 3 metros para longe de você e ficará caído.", en: "The first time you hit with a melee weapon attack during this spell’s duration, your weapon rings with thunder that is audible within 300 feet of you, and the attack deals an extra 2d6 thunder damage to the target. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and knocked prone." } },
  { id: 'divineFavor',    level: 1, school: 'evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V, S', duration: '1 min, conc', concentration: true, desc: { pt: "Sua prece fortalece você com radiância divina. Até a magia terminar, seus ataques com arma causam 1d4 de dano radiante extra ao atingir.", en: "Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit." } },
  { id: 'entangle',       level: 1, school: 'conjuration', classes: ['druid'], castingTime: '1 action', range: '90 ft', components: 'V, S', duration: '1 min, conc', concentration: true, desc: { pt: "Ervas daninhas e vinhas agarradoras brotam do chão em um quadrado de 6 metros a partir de um ponto dentro do alcance. Pela duração, essas plantas transformam o chão da área em terreno difícil.\n\nUma criatura na área quando você conjura a magia deve ser bem-sucedida em um teste de resistência de Força ou ficará impedida pelas plantas emaranhadas até a magia terminar. Uma criatura impedida pelas plantas pode usar sua ação para realizar um teste de Força contra a CD de resistência da sua magia. Em um sucesso, ela se liberta.\n\nQuando a magia termina, as plantas conjuradas murcham e desaparecem.", en: "Grasping weeds and vines sprout from the ground in a 20-foot square starting from a point within range. For the duration, these plants turn the ground in the area into difficult terrain.\n\nA creature in the area when you cast the spell must succeed on a Strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.\n\nWhen the spell ends, the conjured plants wilt away." } },
  { id: 'goodberry',      level: 1, school: 'transmutation', classes: ['druid','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Até dez frutos silvestres aparecem na sua mão e são infundidos com magia pela duração. Uma criatura pode usar sua ação para comer um fruto. Comer um fruto restaura 1 ponto de vida e o fruto fornece nutrição suficiente para sustentar uma criatura por um dia.\n\nOs frutos perdem sua potência se não forem consumidos dentro de 24 horas após a conjuração desta magia.", en: "Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for one day. \n\nThe berries lose their potency if they have not been consumed within 24 hours of the casting of this spell." } },
  { id: 'witchBolt',      level: 1, school: 'evocation', classes: ['sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Um feixe crepitante de energia azul dispara em direção a uma criatura dentro do alcance, formando um arco sustentado de relâmpagos entre você e o alvo. Faça um ataque à distância com magia contra essa criatura. Se atingir, o alvo sofre 1d12 de dano elétrico e, em cada um dos seus turnos durante a duração, você pode usar sua ação para causar 1d12 de dano elétrico ao alvo automaticamente. A magia termina se você usar sua ação para fazer qualquer outra coisa. A magia também termina se o alvo estiver fora do alcance da magia ou se tiver cobertura total contra você.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano inicial aumenta em 1d12 para cada círculo do espaço acima do 1º.", en: "A beam of crackling, blue energy lances out toward a creature within range, forming a sustained arc of lightning between you and the target. Make a ranged spell attack against that creature. On a hit, the target takes 1d12 lightning damage, and on each of your turns for the duration, you can use your action to deal 1d12 lightning damage to the target automatically. The spell ends if you use your action to do anything else. The spell also ends if the target is ever outside the spell’s range or if it has total cover from you.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the initial damage increases by 1d12 for each slot level above 1st." } },
  { id: 'armorOfAgathys', level: 1, school: 'abjuration', classes: ['warlock'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', desc: { pt: "Uma força mágica protetora envolve você, manifestando-se como uma geada espectral que cobre você e seu equipamento. Você ganha 5 pontos de vida temporários pela duração. Se uma criatura atingir você com um ataque corpo a corpo enquanto você tiver esses pontos de vida, a criatura sofre 5 de dano de frio.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, tanto os pontos de vida temporários quanto o dano de frio aumentam em 5 para cada círculo do espaço acima do 1º.", en: "A protective magical force surrounds you, manifesting as a spectral frost that covers you and your gear. You gain 5 temporary hit points for the duration. If a creature hits you with a melee attack while you have these hit points, the creature takes 5 cold damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, both the temporary hit points and the cold damage increase by 5 for each slot level above 1st." } },
  { id: 'hex',            level: 1, school: 'enchantment', classes: ['warlock'], castingTime: '1 bonus action', range: '90 ft', components: 'V, S, M', duration: '1 hour, conc', concentration: true, desc: { pt: "Você coloca uma maldição em uma criatura que possa ver dentro do alcance. Até a magia terminar, você causa 1d6 de dano necrótico adicional ao alvo sempre que o atingir com um ataque. Escolha também um atributo ao conjurar a magia. O alvo tem desvantagem em testes de atributo feitos com o atributo escolhido.\n\nSe o alvo for reduzido a 0 pontos de vida antes desta magia terminar, você pode usar uma ação bônus em um turno subsequente seu para amaldiçoar uma nova criatura.\n\nUma magia remover maldição conjurada no alvo encerra esta magia antecipadamente.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º ou 4º círculo, você pode manter sua concentração na magia por até 8 horas. Quando você usar um espaço de magia de 5º círculo ou superior, você pode manter sua concentração na magia por até 24 horas.", en: "You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 necrotic damage to the target whenever you hit it with an attack. Also choose one ability when you cast the spell. The target has disadvantage on ability checks made with the chosen ability.\n\nIf the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to curse a new creature.\n\nA remove curse cast on the target ends this spell early.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours." } },

  // 2nd Level
  { id: 'aid',            level: 2, school: 'abjuration', classes: ['cleric','paladin'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '8 hours', desc: { pt: "Sua magia revigora seus aliados com resistência e determinação. Escolha até três criaturas dentro do alcance. Os Pontos de Vida máximos e os Pontos de Vida atuais de cada alvo aumentam em 5 pela duração.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, os Pontos de Vida de um alvo aumentam em 5 adicionais para cada círculo do espaço acima do 2º.", en: "Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, a target's hit points increase by an additional 5 for each slot level above 2nd." } },
  { id: 'invisibility',   level: 2, school: 'illusion', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour, conc', concentration: true, desc: { pt: "Uma criatura que você toca fica invisível até a magia terminar. Qualquer coisa que o alvo esteja vestindo ou carregando fica invisível enquanto estiver junto ao corpo do alvo. A magia termina para um alvo que realize um ataque ou conjure uma magia.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 2º.", en: "A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for a target that attacks or casts a spell.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd." } },
  { id: 'scorchingRay',   level: 2, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você cria três raios de fogo e os arremessa contra alvos dentro do alcance. Você pode arremessá-los contra um único alvo ou contra vários.\n\nFaça um ataque à distância com magia para cada raio. Se acertar, o alvo sofre 2d6 de dano de fogo.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, você cria um raio adicional para cada círculo do espaço acima do 2º.", en: "You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.\n\nMake a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd." } },
  { id: 'mistyStep',      level: 2, school: 'conjuration', classes: ['sorcerer','warlock','wizard'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Instant', desc: { pt: "Envolto brevemente por uma névoa prateada, você se teletransporta até 9 metros para um espaço desocupado que você possa ver.", en: "Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see." } },
  { id: 'spiritualWeapon',level: 2, school: 'evocation', classes: ['cleric'], castingTime: '1 bonus action', range: '60 ft', components: 'V, S', duration: '1 min', desc: { pt: "Você cria uma arma espectral e flutuante dentro do alcance que dura pela duração ou até você conjurar esta magia novamente. Quando conjura a magia, você pode fazer um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro da arma. Se acertar, o alvo sofre dano de energia igual a 1d8 + seu modificador de atributo de conjuração.\n\nComo uma ação bônus no seu turno, você pode mover a arma em até 6 metros e repetir o ataque contra uma criatura a até 1,5 metro dela.\n\nA arma pode assumir qualquer forma que você escolher. Clérigos de divindades associadas a uma arma em particular (como São Cuthbert é conhecido por sua maça e Thor por seu martelo) fazem com que o efeito desta magia se assemelhe a essa arma.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada dois círculos do espaço acima do 2º.", en: "You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.\n\nAs a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.\n\nThe weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell's effect resemble that weapon.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above 2nd." } },
  { id: 'holdPerson',     level: 2, school: 'enchantment', classes: ['bard','cleric','druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Escolha um humanoide que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou ficará paralisado pela duração. Ao final de cada um dos seus turnos, o alvo pode realizar outro teste de resistência de Sabedoria. Em um sucesso, a magia termina sobre o alvo.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher um humanoide adicional como alvo para cada círculo do espaço acima do 2º. Os humanoides devem estar a até 9 metros uns dos outros quando você os escolher como alvo.", en: "Choose a humanoid that you can see within range. The target must succeed on a Wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another Wisdom saving throw. On a success, the spell ends on the target.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them." } },
  { id: 'spikeGrowth',    level: 2, school: 'transmutation', classes: ['druid','ranger'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: '10 min, conc', concentration: true, desc: { pt: "O chão em uma Esfera com 6 metros de raio centrada em um ponto dentro do alcance brota espinhos e cravos duros. A área se torna Terreno Difícil pela duração. Quando uma criatura entra na área ou se move dentro dela, sofre 2d4 de dano Perfurante a cada 1,5 metro que percorrer.\nA transformação do chão é camuflada para parecer natural. Qualquer criatura que não consiga ver a área quando a magia é conjurada deve realizar a ação Procurar e ser bem-sucedida em um teste de Sabedoria (Percepção ou Sobrevivência) contra a CD de resistência da sua magia para reconhecer o terreno como perigoso antes de entrar nele.", en: "The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.\n\nThe transformation of the ground is camouflaged to look natural. Any creature that can't see the area at the time the spell is cast must make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it." } },

  // 3rd Level
  { id: 'fireball',       level: 3, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Um raio brilhante dispara da ponta do seu dedo até um ponto que você escolher dentro do alcance e então floresce com um estrondo abafado em uma explosão de chamas. Cada criatura em uma esfera com raio de 6 metros centrada naquele ponto deve realizar um teste de resistência de Destreza. Um alvo sofre 8d6 de dano de fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nO fogo se propaga pelas esquinas e curvas. Ele incendeia objetos inflamáveis na área que não estejam sendo vestidos ou carregados.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 3º.", en: "A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot radius sphere centered on that point must make a Dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire spreads around corners. It ignites flammable objects in the area that aren't being worn or carried.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd." } },
  { id: 'counterspell',   level: 3, school: 'abjuration', classes: ['sorcerer','warlock','wizard'], castingTime: '1 reaction', range: '60 ft', components: 'S', duration: 'Instant', desc: { pt: "Você tenta interromper uma criatura no processo de conjurar uma magia. Se a criatura estiver conjurando uma magia de 3º círculo ou inferior, a magia dela falha e não tem efeito. Se ela estiver conjurando uma magia de 4º círculo ou superior, faça um teste de habilidade usando sua habilidade de conjuração. A CD é igual a 10 + o círculo da magia. Em um sucesso, a magia da criatura falha e não tem efeito.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a magia interrompida não tem efeito se o círculo dela for menor ou igual ao círculo do espaço de magia que você usou.", en: "You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a success, the creature's spell fails and has no effect.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used." } },
  { id: 'fly',            level: 3, school: 'transmutation', classes: ['sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '10 min, conc', concentration: true, desc: { pt: "Você toca uma criatura voluntária. O alvo ganha deslocamento de voo de 18 metros pela duração. Quando a magia termina, o alvo cai se ainda estiver no ar, a menos que consiga impedir a queda.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 3º.", en: "You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd." } },
  { id: 'haste',          level: 3, school: 'transmutation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Escolha uma criatura voluntária que você possa ver dentro do alcance. Até a magia terminar, o deslocamento do alvo é dobrado, ele ganha um bônus de +2 na CA, tem vantagem em testes de resistência de Destreza e ganha uma ação adicional em cada um dos seus turnos. Essa ação pode ser usada apenas para realizar as ações de Atacar (apenas um ataque com arma), Disparada, Desengajar, Esconder-se ou Usar um Objeto.\n\nQuando a magia termina, o alvo não pode se mover nem realizar ações até depois do seu próximo turno, conforme uma onda de letargia o acomete.", en: "Choose a willing creature that you can see within range. Until the spell ends, the target's speed is doubled, it gains a +2 bonus to AC, it has advantage on Dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.\n\nWhen the spell ends, the target can't move or take actions until after its next turn, as a wave of lethargy sweeps over it." } },
  { id: 'lightningBolt',  level: 3, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self (100-ft line)', components: 'V, S, M', duration: 'Instant', desc: { pt: "Um relâmpago formando uma linha de 30 metros de comprimento e 1,5 metro de largura dispara a partir de você em uma direção que você escolher. Cada criatura na linha deve realizar um teste de resistência de Destreza. Uma criatura sofre 8d6 de dano elétrico em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nO relâmpago incendeia objetos inflamáveis na área que não estejam sendo vestidos ou carregados.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 3º.", en: "A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.\n\nThe lightning ignites flammable objects in the area that aren't being worn or carried.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd." } },
  { id: 'massHealingWord',level: 3, school: 'evocation', classes: ['cleric'], castingTime: '1 bonus action', range: '60 ft', components: 'V', duration: 'Instant', desc: { pt: "Conforme você brada palavras de restauração, até seis criaturas à sua escolha que você possa ver dentro do alcance recuperam pontos de vida iguais a 1d4 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, a cura aumenta em 1d4 para cada círculo do espaço acima do 3º.", en: "As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd." } },
  { id: 'revivify',       level: 3, school: 'necromancy', classes: ['cleric','paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você toca uma criatura que tenha morrido no último minuto. Essa criatura retorna à vida com 1 Ponto de Vida. Esta magia não pode trazer de volta à vida uma criatura que tenha morrido de velhice, nem pode restaurar quaisquer partes do corpo que estejam faltando.", en: "You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore any missing body parts." } },
  { id: 'spiritGuardians',level: 3, school: 'conjuration', classes: ['cleric'], castingTime: '1 action', range: 'Self (15-ft radius)', components: 'V, S, M', duration: '10 min, conc', concentration: true, desc: { pt: "Você convoca espíritos para protegê-lo. Eles esvoaçam ao seu redor até uma distância de 4,5 metros pela duração. Se você for bom ou neutro, a forma espectral deles parece angelical ou feérica (sua escolha). Se você for mau, eles parecem diabólicos ou demoníacos.\n\nQuando conjura esta magia, você pode designar qualquer quantidade de criaturas que possa ver para não serem afetadas por ela. O deslocamento de uma criatura afetada é reduzido pela metade na área, e quando a criatura entra na área pela primeira vez em um turno ou começa seu turno lá, ela deve realizar um teste de resistência de Sabedoria. Em caso de falha no teste, a criatura sofre 3d8 de dano radiante (se você for bom ou neutro) ou 3d8 de dano necrótico (se você for mau). Em caso de sucesso na salvaguarda, a criatura sofre metade desse dano.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 3º.", en: "You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\n\nWhen you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature's speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a Wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd." } },
  { id: 'callLightning', level: 3, school: 'conjuration', classes: ['druid'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: '10 min, conc', concentration: true, desc: { pt: "Uma nuvem de tempestade surge na forma de um cilindro de 3 metros de altura com 18 metros de raio, centrado em um ponto que você possa ver dentro do alcance diretamente acima de você. A magia falha se você não puder ver um ponto no ar onde a nuvem de tempestade possa surgir (por exemplo, se você estiver em uma sala que não comporte a nuvem).\n\nQuando você conjura a magia, escolha um ponto que você possa ver sob a nuvem. Um relâmpago atinge aquele ponto descendo da nuvem. Cada criatura a até 1,5 metro daquele ponto deve fazer uma salvaguarda de Destreza. Uma criatura sofre 3d10 de dano elétrico em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida. Em cada um dos seus turnos até a magia terminar, você pode usar sua ação para convocar relâmpagos dessa forma novamente, tendo como alvo o mesmo ponto ou um ponto diferente.\n\nSe você estiver ao ar livre sob condições de tempestade quando conjurar esta magia, a magia concede a você controle sobre a tempestade existente em vez de criar uma nova. Sob tais condições, o dano da magia aumenta em 1d10.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 3º.", en: "A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see within range directly above you. The spell fails if you can't see a point in the air where the storm cloud could appear (for example, if you are in a room that can't accommodate the cloud).\n\nWhen you cast the spell, choose a point you can see under the cloud. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a Dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.\n\nIf you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell's damage increases by 1d10.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd." } },
  { id: 'sleetStorm',    level: 3, school: 'conjuration', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Até a magia terminar, chuva congelante e granizo caem em um cilindro de 6 metros de altura com 12 metros de raio centrado em um ponto escolhido por você dentro do alcance. A área fica fortemente obscurecida, e chamas expostas na área são apagadas.\n\nO chão na área fica coberto de gelo escorregadio, tornando-se terreno difícil. Quando uma criatura entra na área da magia pela primeira vez em um turno ou começa seu turno lá, ela deve realizar um teste de resistência de Destreza. Se falhar, fica caída.\n\nSe uma criatura começar o turno dela na área da magia e estiver se concentrando em uma magia, ela deverá obter sucesso em um teste de resistência de Constituição contra a CD de resistência da sua magia ou perderá a concentração.", en: "Until the spell ends, freezing rain and sleet fall in a 20-foot tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.\n\nThe ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a Dexterity saving throw. On a failed save, it falls prone.\n\nIf a creature starts its turn in the spell's area and is concentrating on a spell, the creature must make a successful Constitution saving throw against your spell save DC or lose concentration." } },
  { id: 'dispelMagic',   level: 3, school: 'abjuration', classes: ['bard','cleric','druid','paladin','sorcerer','warlock','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Escolha uma criatura, objeto ou efeito mágico dentro do alcance. Qualquer magia de 3º círculo ou inferior no alvo termina. Para cada magia de 4º círculo ou superior no alvo, faça um teste de habilidade usando sua habilidade de conjuração. A CD é igual a 10 + o círculo da magia. Em um teste bem-sucedido, a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você encerra automaticamente os efeitos de uma magia no alvo se o círculo da magia for menor ou igual ao círculo do espaço de magia utilizado.", en: "Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a successful check, the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell's level is equal to or less than the level of the spell slot you used." } },
  { id: 'animateDead',   level: 3, school: 'necromancy', classes: ['cleric','wizard'], castingTime: '1 minute', range: '10 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Esta magia cria um servo morto-vivo. Escolha uma pilha de ossos ou o cadáver de um humanoide Médio ou Pequeno dentro do alcance. Sua magia infunde o alvo com uma sórdida imitação de vida, erguendo-o como uma criatura morta-viva. O alvo se torna um esqueleto se você escolheu ossos ou um zumbi se escolheu um cadáver (o Mestre tem as estatísticas de jogo da criatura).\n\nEm cada um dos seus turnos, você pode usar uma ação bônus para comandar mentalmente qualquer criatura que você criou com esta magia se a criatura estiver a até 18 metros de você (se você controlar múltiplas criaturas, pode comandar qualquer uma ou todas elas ao mesmo tempo, emitindo o mesmo comando para cada uma). Você decide qual ação a criatura realizará e para onde ela se moverá durante o próximo turno dela, ou você pode emitir um comando geral, como guardar uma câmara ou corredor específico. Se você não emitir nenhum comando, a criatura apenas se defende contra criaturas hostis. Uma vez dada uma ordem, a criatura continua a segui-la até que sua tarefa seja concluída.\n\nA criatura fica sob o seu controle por 24 horas, após o que para de obedecer a qualquer comando dado por você. Para manter o controle da criatura por mais 24 horas, você deve conjurar esta magia na criatura novamente antes que o período atual de 24 horas termine. Esse uso da magia reafirma seu controle sobre até quatro criaturas que você tenha animado com esta magia, em vez de animar uma nova.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você anima ou reafirma o controle sobre duas criaturas mortas-vivas adicionais para cada círculo do espaço acima do 3º. Cada uma das criaturas deve vir de um cadáver ou pilha de ossos diferente.", en: "This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature's game statistics).\n\nOn each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones." } },

  // 4th Level
  { id: 'banishment',    level: 4, school: 'abjuration', classes: ['cleric','paladin','sorcerer','warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Você tenta enviar uma criatura que você possa ver dentro do alcance para outro plano de existência. O alvo deve ser bem-sucedido em uma salvaguarda de Carisma ou será banido.\n\nSe o alvo for nativo do plano de existência em que você está, você bane o alvo para um demiplano inofensivo. Enquanto estiver lá, o alvo fica incapacitado. O alvo permanece lá até a magia acabar, momento em que o alvo reaparece no espaço que deixou ou no espaço desocupado mais próximo se aquele espaço estiver ocupado.\n\nSe o alvo for nativo de um plano de existência diferente daquele em que você está, o alvo é banido com um estalo suave, retornando ao seu plano de origem. Se a magia terminar antes de passar 1 minuto, o alvo reaparece no espaço que deixou ou no espaço desocupado mais próximo se aquele espaço estiver ocupado. Caso contrário, o alvo não retorna.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 4º.", en: "You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a Charisma saving throw or be banished.\n\nIf the target is native to the plane of existence you're on, you banish the target to a harmless demiplane. While there, the target is incapacitated. The target remains there until the spell ends, at which point the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\n\nIf the target is native to a different plane of existence than the one you're on, the target is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied. Otherwise, the target doesn't return.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th." } },
  { id: 'dimensionDoor', level: 4, school: 'conjuration', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '500 ft', components: 'V', duration: 'Instant', desc: { pt: "Você se teletransporta do seu local atual para qualquer outro ponto dentro do alcance. Você surge exatamente no ponto desejado. Pode ser um lugar que você possa ver, um que possa visualizar ou um que você possa descrever indicando distância e direção, como \"60 metros em linha reta para baixo\" ou \"para cima em direção ao noroeste em um ângulo de 45 graus, 90 metros\".\n\nVocê pode levar objetos com você, desde que o peso deles não exceda o que você pode carregar. Você também pode levar uma criatura voluntária do seu tamanho ou menor que esteja carregando equipamento até a capacidade de carga dela. A criatura deve estar a até 1,5 metro de você quando você conjurar esta magia.\n\nSe você for surgir em um local já ocupado por um objeto ou criatura, você e qualquer criatura viajando com você sofrem 4d6 de dano de energia cada, e a magia falha em teletransportar vocês.", en: "You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \"200 feet straight downward\" or \"upward to the northwest at a 45-degree angle, 300 feet.\"\n\nYou can bring along objects as long as their weight doesn't exceed what you can carry. You can also bring one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell.\n\nIf you would arrive in a place already occupied by an object or a creature, you and any creature traveling with you each take 4d6 force damage, and the spell fails to teleport you." } },
  { id: 'fireShield',    level: 4, school: 'evocation', classes: ['wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '10 min', desc: { pt: "Chamas finas e diáfanas envolvem seu corpo pela duração, emitindo luz plena em um raio de 3 metros e penumbra por mais 3 metros adicionais. Você pode encerrar a magia prematuramente usando uma ação para dispensá-la.\n\nAs chamas fornecem a você um escudo quente ou um escudo frio, conforme você escolher. O escudo quente concede a você resistência a dano de frio, e o escudo frio concede a você resistência a dano de fogo.\n\nAlém disso, sempre que uma criatura a até 1,5 metro de você o atingir com um ataque corpo a corpo, o escudo irrompe em chamas. O atacante sofre 2d8 de dano de fogo com o escudo quente, ou 2d8 de dano de frio com o escudo frio.", en: "Thin and wispy flames wreathe your body for the duration, shedding bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell early by using an action to dismiss it.\n\nThe flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you resistance to cold damage, and the chill shield grants you resistance to fire damage.\n\nIn addition, whenever a creature within 5 feet of you hits you with a melee attack, the shield erupts with flame. The attacker takes 2d8 fire damage from a warm shield, or 2d8 cold damage from a cold shield." } },
  { id: 'greaterInvisibility', level: 4, school: 'illusion', classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '1 min, conc', concentration: true, desc: { pt: "Você ou uma criatura que você tocar fica invisível até a magia terminar. Qualquer coisa que o alvo esteja vestindo ou carregando fica invisível enquanto estiver junto ao corpo do alvo.", en: "You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person." } },
  { id: 'iceStorm',      level: 4, school: 'evocation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '300 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Uma saraivada de granizo duro como pedra atinge com violência o chão em um cilindro de 6 metros de raio e 12 metros de altura centrado em um ponto dentro do alcance. Cada criatura no cilindro deve realizar um teste de resistência de Destreza. Uma criatura sofre 2d8 de dano contundente e 4d6 de dano de frio em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nAs pedras de granizo transformam a área de efeito da tempestade em terreno difícil até o final do seu próximo turno.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 5º círculo ou superior, o dano contundente aumenta em 1d8 para cada círculo do espaço acima do 4º.", en: "A hail of rock-hard ice pounds to the ground in a 20-foot radius, 40-foot high cylinder centered on a point within range. Each creature in the cylinder must make a Dexterity saving throw. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one.\n\nHailstones turn the storm's area of effect into difficult terrain until the end of your next turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the bludgeoning damage increases by 1d8 for each slot level above 4th." } },
  { id: 'polymorph',     level: 4, school: 'transmutation', classes: ['bard','druid','sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: '1 hour, conc', concentration: true, desc: { pt: "Esta magia transforma uma criatura que você possa ver dentro do alcance em uma nova forma. Uma criatura relutante deve realizar um teste de resistência de Sabedoria para evitar o efeito. A magia não afeta metamorfos nem criaturas com 0 Pontos de Vida.\n\nA transformação dura pela duração da magia, ou até o alvo cair a 0 Pontos de Vida ou morrer. A nova forma pode ser qualquer fera cujo nível de desafio seja igual ou inferior ao do alvo (ou ao nível do alvo, se ele não possuir um nível de desafio). As estatísticas de jogo do alvo, incluindo atributos mentais, são substituídas pelas estatísticas da fera escolhida. Ele preserva seu alinhamento e personalidade.\n\nO alvo assume os Pontos de Vida de sua nova forma. Quando reverte à sua forma normal, a criatura retorna à quantidade de Pontos de Vida que possuía antes de se transformar. Se reverter como resultado de cair a 0 Pontos de Vida, qualquer dano excedente é transferido para a sua forma normal. Desde que o dano excedente não reduza a forma normal da criatura a 0 Pontos de Vida, ela não fica inconsciente.\n\nA criatura é limitada nas ações que pode realizar pela natureza de sua nova forma, e não pode falar, conjurar magias ou realizar qualquer outra ação que exija mãos ou fala.\n\nO equipamento do alvo funde-se à nova forma. A criatura não pode ativar, usar, empunhar ou de outra forma se beneficiar de qualquer um de seus equipamentos.", en: "This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a Wisdom saving throw to avoid the effect. The spell has no effect on a shapechanger or a creature with 0 hit points.\n\nThe transformation lasts for the duration, or until the target drops to 0 hit points or dies. The new form can be any beast whose challenge rating is equal to or less than the target's (or the target's level, if it doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the chosen beast. It retains its alignment and personality.\n\nThe target assumes the hit points of its new form. When it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\n\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech.\n\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment." } },
  { id: 'wallOfFire',    level: 4, school: 'evocation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Você cria uma muralha de fogo sobre uma superfície sólida dentro do alcance. Você pode fazer a muralha ter até 18 metros de comprimento, 6 metros de altura e 30 centímetros de espessura, ou uma muralha em anel com até 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura. A muralha é opaca e dura pela duração.\n\nQuando a muralha surge, cada criatura dentro da área dela deve realizar um teste de resistência de Destreza. Se falhar na salvaguarda, a criatura sofre 5d8 de dano de fogo, ou metade desse dano em caso de sucesso.\n\nUm dos lados da muralha, selecionado por você ao conjurar esta magia, causa 5d8 de dano de fogo a cada criatura que terminar o turno a até 3 metros daquele lado ou dentro da muralha. Uma criatura sofre o mesmo dano quando entra na muralha pela primeira vez em um turno ou termina o turno lá. O outro lado da muralha não causa dano.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 4º.", en: "You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 5d8 fire damage, or half as much damage on a successful save.\n\nOne side of the wall, selected by you when you cast this spell, deals 5d8 fire damage to each creature that ends its turn within 10 feet of that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th." } },
  { id: 'guardianOfFaith', level: 4, school: 'conjuration', classes: ['cleric'], castingTime: '1 action', range: '30 ft', components: 'V', duration: '8 hours', desc: { pt: "Um grande guardião espectral aparece e paira pela duração em um espaço desocupado à sua escolha que você possa ver dentro do alcance. O guardião ocupa esse espaço e é indistinto, exceto por uma espada reluzente e um escudo brasonado com o símbolo da sua divindade.\n\nQualquer criatura hostil a você que se mover para um espaço a até 3 metros do guardião pela primeira vez em um turno deve ser bem-sucedida em um teste de resistência de Destreza. A criatura sofre 20 de dano radiante em uma falha na salvaguarda, ou metade desse dano em um sucesso. O guardião desaparece quando tiver causado um total de 60 de dano.", en: "A large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity.\n\nAny creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a Dexterity saving throw. The creature takes 20 radiant damage on a failed save, or half as much damage on a successful one. The guardian vanishes when it has delat a total of 60 damage." } },

  // 5th Level
  { id: 'cloudkill',     level: 5, school: 'conjuration', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: '10 min, conc', concentration: true, desc: { pt: "Você cria uma esfera com 6 metros de raio de névoa venenosa verde-amarelada centrada em um ponto à sua escolha dentro do alcance. A névoa contorna esquinas e cantos. Ela dura pela duração ou até que um vento forte disperse a névoa, encerrando a magia. A área dela fica fortemente obscurecida.\n\nQuando uma criatura entrar na área da magia pela primeira vez em um turno ou começar seu turno nela, essa criatura deve fazer uma salvaguarda de Constituição. A criatura sofre 5d8 de dano de veneno em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida. As criaturas são afetadas mesmo se prenderem a respiração ou se não precisarem respirar.\n\nA névoa se afasta 3 metros de você no início de cada um dos seus turnos, rolando pela superfície do solo. Os vapores, sendo mais pesados que o ar, afundam para o nível mais baixo do terreno, inclusive escoando por aberturas.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.", en: "You create a 20-foot radius sphere of poisonous, yellow-green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, that creature must make a Constitution saving throw. The creature takes 5d8 poison damage on a failed save, or half as much damage on a successful one. Creatures are affected even if they hold their breath or don't need to breathe.\n\nThe fog moves 10 feet away from you at the start of each of your turns, rolling along the surface of the ground. The vapors, being heavier than air, sink to the lowest level of the land, even pouring down openings.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th." } },
  { id: 'coneOfCold',    level: 5, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self (60-ft cone)', components: 'V, S, M', duration: 'Instant', desc: { pt: "Uma rajada de ar gélido irrompe das suas mãos. Cada criatura em um cone de 18 metros deve fazer uma salvaguarda de Constituição. Uma criatura sofre 8d8 de dano de frio em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida.\n\nUma criatura morta por esta magia se torna uma estátua congelada até descongelar.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.", en: "A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a Constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.\n\nA creature killed by this spell becomes a frozen statue until it thaws.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th." } },
  { id: 'flameStrike',   level: 5, school: 'evocation', classes: ['cleric'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Uma coluna vertical de fogo divino ruge descendo dos céus em um local que você especificar. Cada criatura em um cilindro de 3 metros de raio e 12 metros de altura centrado em um ponto dentro do alcance deve realizar um teste de resistência de Destreza. Uma criatura sofre 4d6 de dano de fogo e 4d6 de dano radiante em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 6º círculo ou superior, o dano de fogo ou o dano radiante (à sua escolha) aumenta em 1d6 para cada círculo do espaço acima do 5º.", en: "A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot radius, 40-foot high cylinder centered on a point within range must make a Dexterity saving throw. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the fire damage or the radiant damage (your choice) increases by 1d6 for each slot level above 5th." } },
  { id: 'holdMonster',   level: 5, school: 'enchantment', classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '90 ft', components: 'V, S, M', duration: '1 min, conc', concentration: true, desc: { pt: "Escolha uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou ficará paralisado pela duração. Esta magia não tem efeito sobre mortos-vivos. Ao final de cada um dos seus turnos, o alvo pode realizar outro teste de resistência de Sabedoria. Em um sucesso, a magia termina sobre o alvo.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 6º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 5º. As criaturas devem estar a até 9 metros umas das outras quando você as escolher como alvo.", en: "Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or be paralyzed for the duration. This spell has no effect on undead. At the end of each of its turns, the target can make another Wisdom saving throw. On a success, the spell ends on the target.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can target one additional creature for each slot level above 5th. The creatures must be within 30 feet of each other when you target them." } },
  { id: 'massCureWounds',level: 5, school: 'evocation', classes: ['bard','cleric','druid'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Uma onda de energia curativa emana de um ponto à sua escolha dentro do alcance. Escolha até seis criaturas em uma esfera com raio de 9 metros centrada naquele ponto. Cada alvo recupera pontos de vida iguais a 3d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 6º círculo ou superior, a cura aumenta em 1d8 para cada círculo do espaço acima do 5º.", en: "A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the healing increases by 1d8 for each slot level above 5th." } },
  { id: 'raiseDead',     level: 5, school: 'necromancy', classes: ['bard','cleric','paladin'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você traz de volta à vida uma criatura morta que tocar, desde que ela não esteja morta há mais de 10 dias. Se a alma da criatura estiver disposta e livre para retornar ao corpo, a criatura retorna à vida com 1 Ponto de Vida.\n\nEsta magia também neutraliza quaisquer venenos e cura doenças não mágicas que afetavam a criatura no momento de sua morte. Esta magia não remove, contudo, doenças mágicas, maldições ou efeitos semelhantes; se estes não forem removidos antes da conjuração da magia, passarão a fazer efeito quando a criatura retornar à vida. A magia não pode trazer uma criatura morta-viva de volta à vida.\n\nEsta magia fecha todas as feridas mortais, mas não restaura partes do corpo que estejam faltando. Se a criatura não tiver partes do corpo ou órgãos vitais para a sua sobrevivência — a cabeça, por exemplo —, a magia falha automaticamente.\n\nRetornar dos mortos é uma provação difícil. O alvo sofre uma penalidade de -4 em todas as jogadas de ataque, testes de resistência e testes de atributo. Cada vez que o alvo completa um Descanso Longo, a penalidade é reduzida em 1 até desaparecer completamente.", en: "You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature's soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 hit point.\n\nThis spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn't, however, remove magical diseases, curses, or similar effects; if these aren't first removed prior to casting the spell, they take effect when the creature returns to life. The spell can't return an undead creature to life.\n\nThis spell closes all mortal wounds, but it doesn't restore missing body parts. If the creature is lacking body parts or organs integral for its survival-its head, for instance-the spell automatically fails.\n\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears." } },
  { id: 'wallOfStone',   level: 5, school: 'evocation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: '10 min, conc', concentration: true, desc: { pt: "Uma muralha não mágica de pedra sólida surge em um ponto de sua escolha dentro do alcance. A muralha tem 15 centímetros de espessura e é composta por dez painéis de 3 metros por 3 metros. Cada painel deve ser contíguo a pelo menos um outro painel. Alternativamente, você pode criar painéis de 3 metros por 6 metros com apenas 7,5 centímetros de espessura.\n\nSe a muralha atravessar o espaço ocupado por uma criatura ao surgir, a criatura é empurrada para um dos lados da muralha (à sua escolha). Se uma criatura for ficar cercada em todos os lados pela muralha (ou pela muralha e outra superfície sólida), essa criatura pode realizar um teste de resistência de Destreza. Em caso de sucesso, ela pode usar sua reação para se mover em até o seu deslocamento de forma a não ficar mais cercada pela muralha.\n\nA muralha pode ter qualquer formato que desejar, embora não possa ocupar o mesmo espaço que uma criatura ou objeto. A muralha não precisa ser vertical nem repousar sobre uma fundação firme. Ela deve, no entanto, fundir-se e ser solidamente apoiada por rocha existente. Assim, você pode usar esta magia para criar uma ponte sobre um abismo ou criar uma rampa.\n\nSe você criar um vão com mais de 6 metros de extensão, deverá reduzir o tamanho de cada painel pela metade para criar suportes. Você pode moldar toscamente a muralha para criar ameias, parapeitos e assim por diante.\n\nA muralha é um objeto feito de pedra que pode ser danificado e, assim, rompido. Cada painel tem CA 15 e 30 Pontos de Vida por polegada (2,5 cm) de espessura. Reduzir um painel a 0 Pontos de Vida o destrói e pode fazer com que painéis conectados desabem, a critério do Mestre.\n\nSe mantiver a concentração nesta magia por toda a sua duração, a muralha se torna permanente e não pode ser dissipada. Caso contrário, a muralha desaparece quando a magia termina.", en: "A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick.\n\nIf the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a Dexterity saving throw. On a success, it can use its reaction to move up to its speed so that it is no longer enclosed by the wall.\n\nThe wall can have any shape you desire, though it can't occupy the same space as a creature or object. The wall doesn't need to be vertical or rest on any firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.\n\nIf you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create crenellations, battlements, and so on.\n\nThe wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 hit points per inch of thickness. Reducing a panel to 0 hit points destroys it and might cause connected panels to collapse at the GM's discretion.\n\nIf you maintain your concentration on this spell for its whole duration, the wall becomes permanent and can't be dispelled. Otherwise, the wall disappears when the spell ends." } },
  { id: 'greaterRestoration', level: 5, school: 'abjuration', classes: ['bard','cleric','druid'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você imbui uma criatura que tocar com energia positiva para desfazer um efeito debilitante. Você pode reduzir o nível de exaustão do alvo em um grau, ou encerrar um dos seguintes efeitos no alvo:\n\n- Um efeito que tenha deixado o alvo enfeitiçado ou petrificado\n- Uma maldição, incluindo a sintonização do alvo com um item mágico amaldiçoado\n- Qualquer redução em um dos valores de atributo do alvo\n- Um efeito que esteja reduzindo o máximo de pontos de vida do alvo", en: "You imbue a creature you touch with positive energy to undo a debilitating effect. You can reduce the target's exhaustion level by one, or end one of the following effects on the target:\n\n- One effect that charmed or petrified the target\n- One curse, including the target's attunement to a cursed magic item\n- Any reduction to one of the target's ability scores\n- One effect reducing the target's hit point maximum" } },

  // 6th-9th Level (selection)
  { id: 'chainLightning',level: 6, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você cria um relâmpago que salta em direção a um alvo à sua escolha que você possa ver dentro do alcance. Três relâmpagos então saltam daquele alvo para até três outros alvos, cada um dos quais deve estar a até 9 metros do primeiro alvo. Um alvo pode ser uma criatura ou um objeto e pode ser alvo de apenas um dos relâmpagos.\n\nUm alvo deve fazer uma salvaguarda de Destreza. O alvo sofre 10d8 de dano elétrico em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, um relâmpago adicional salta do primeiro alvo para outro alvo para cada círculo do espaço acima do 6º.", en: "You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\n\nA target must make a Dexterity saving throw. The target takes 10d8 lightning damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, one additional bolt leaps from the first target to another target for each slot level above 6th." } },
  { id: 'healSpell',     level: 6, school: 'evocation', classes: ['cleric','druid'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Escolha uma criatura que você possa ver dentro do alcance. Uma onda de energia positiva percorre a criatura, fazendo-a recuperar 70 pontos de vida. Esta magia também encerra cegueira, surdez e quaisquer doenças que estejam afetando o alvo. Esta magia não tem efeito em constructos ou mortos-vivos.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, a quantidade de cura aumenta em 10 para cada círculo do espaço acima do 6º.", en: "Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 hit points. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on constructs or undead.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the amount of healing increases by 10 for each slot level above 6th." } },
  { id: 'fingerOfDeath', level: 7, school: 'necromancy', classes: ['sorcerer','warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você envia energia negativa fluindo através de uma criatura que você possa ver dentro do alcance, causando nela uma dor dilacerante. O alvo deve realizar um teste de resistência de Constituição. Ele sofre 7d8 + 30 de dano necrótico em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nUm humanoide morto por esta magia ergue-se no início do seu próximo turno como um zumbi que fica permanentemente sob o seu comando, seguindo suas ordens verbais com o melhor de suas capacidades.", en: "You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a Constitution saving throw. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a successful one.\n\nA humanoid killed by this spell rises at the start of your next turn as a zombie that is permanently under your command, following your verbal orders to the best of its ability." } },
  { id: 'fireStorm',     level: 7, school: 'evocation', classes: ['cleric','druid','sorcerer'], castingTime: '1 action', range: '150 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Uma tempestade composta por cortinas de chamas rugidoras aparece em um local que você escolher dentro do alcance. A área da tempestade consiste em até dez cubos de 3 metros, que você pode organizar como desejar. Cada cubo deve ter pelo menos uma face adjacente à face de outro cubo. Cada criatura na área deve realizar um teste de resistência de Destreza. Ela sofre 7d10 de dano de fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nO fogo causa dano a objetos na área e incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados. Se você quiser, a vegetação na área não é afetada por esta magia.", en: "A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10-foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a Dexterity saving throw. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried. If you choose, plant life in the area is unaffected by this spell." } },
  { id: 'sunburst',      level: 8, school: 'evocation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Uma luz solar brilhante irrompe em uma Esfera com 18 metros de raio centrada em um ponto que você escolher dentro do alcance. Cada criatura na Esfera faz um teste de resistência de Constituição. Em uma falha, a criatura sofre 12d6 de dano Radiante e fica na condição Cego por 1 minuto. Em um sucesso, ela sofre apenas metade desse dano.\nUma criatura Cega por esta magia faz outro teste de resistência de Constituição ao final de cada um de seus turnos, encerrando o efeito sobre si mesma em caso de sucesso.\nEsta magia dissipa a Escuridão em sua área que tenha sido criada por qualquer magia.", en: "Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a Constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nA creature blinded by this spell makes another Constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded.\n\nThis spell dispels any darkness in its area that was created by a spell." } },
  { id: 'meteorSwarm',   level: 9, school: 'evocation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '1 mile', components: 'V, S', duration: 'Instant', desc: { pt: "Orbes de fogo ardentes despencam no chão em quatro pontos diferentes que você possa ver dentro do alcance. Cada criatura em uma Esfera com 12 metros de raio centrada em cada um desses pontos realiza um teste de resistência de Destreza. Uma criatura sofre 20d6 de dano Ígneo e 20d6 de dano Contundente se falhar ou metade desse dano se for bem-sucedida. Uma criatura na área de mais de uma Esfera flamejante é afetada apenas uma vez.\nUm objeto não mágico que não esteja sendo vestido nem carregado também sofre o dano se estiver na área da magia, e o objeto começa a queimar se for inflamável.", en: "Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot radius sphere centered on each point you choose must make a Dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once.\n\nThe spell damages objects in the area and ignites flammable objects that aren't being worn or carried." } },
  { id: 'wishSpell',     level: 9, school: 'conjuration', classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self', components: 'V', duration: 'Instant', desc: { pt: "Desejo é a magia mais poderosa que uma criatura mortal pode conjurar. Simplesmente falando em voz alta, você pode alterar os próprios alicerces da realidade de acordo com suas vontades.\n\nO uso básico desta magia é duplicar qualquer outra magia de 8º círculo ou inferior. Você não precisa cumprir nenhum requisito dessa magia, incluindo componentes caros. A magia simplesmente entra em efeito.\n\nAlternativamente, você pode criar um dos seguintes efeitos à sua escolha:\n\nVocê cria um objeto de até 25.000 po em valor que não seja um item mágico. O objeto não pode ter mais de 90 metros em qualquer dimensão e surge em um espaço desocupado que você possa ver no chão.\n\nVocê permite que até vinte criaturas que você possa ver recuperem todos os pontos de vida e encerra nelas todos os efeitos descritos na magia restauração maior.\n\nVocê concede a até dez criaturas que você possa ver resistência a um tipo de dano à sua escolha.\n\nVocê concede a até dez criaturas que você possa ver imunidade a uma única magia ou outro efeito mágico por 8 horas. Por exemplo, você poderia tornar a si mesmo e a todos os seus companheiros imunes ao ataque de drenar vida de um lich.\n\nVocê desfaz um único acontecimento recente, forçando a rolagem novamente de qualquer jogada feita durante a última rodada (incluindo seu último turno). A realidade se remodela para acomodar o novo resultado. Por exemplo, uma magia desejo poderia desfazer uma salvaguarda bem-sucedida de um adversário, o acerto crítico de um inimigo ou uma salvaguarda com falha de um amigo. Você pode forçar a nova rolagem a ser feita com vantagem ou desvantagem, e você pode escolher usar a nova jogada ou a original.\n\nVocê pode ser capaz de alcançar algo além do escopo dos exemplos acima. Declare seu desejo ao Mestre o mais precisamente possível. O Mestre tem ampla liberdade para decidir o que ocorre em tal instância; quanto maior o desejo, maior a probabilidade de algo dar errado. Esta magia pode simplesmente falhar, o efeito desejado pode ser alcançado apenas parcialmente ou você pode sofrer alguma consequência imprevista como resultado de como você formulou o desejo. Por exemplo, desejar que um vilão estivesse morto pode arremessar você para frente no tempo até uma época em que aquele vilão não esteja mais vivo, removendo você efetivamente do jogo. Da mesma forma, desejar um item mágico lendário ou artefato pode transportar você instantaneamente para a presença do atual proprietário do item.\n\nO estresse de conjurar esta magia para produzir qualquer efeito além de duplicar outra magia enfraquece você. Depois de suportar esse estresse, cada vez que você conjurar uma magia até terminar um descanso longo, você sofre 1d10 de dano necrótico por círculo daquela magia. Este dano não pode ser reduzido nem prevenido de nenhuma forma. Além disso, sua Força cai para 3, caso já não seja 3 ou menor, por 2d4 dias. Para cada um desses dias em que você descansar e não fizer mais do que atividades leves, seu tempo de recuperação restante diminui em 2 dias. Por fim, há 33 por cento de chance de você se tornar incapaz de conjurar Desejo novamente se sofrer esse estresse.", en: "Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires.\n\nThe basic use of this spell is to duplicate any other spell of 8th level or lower. You don’t need to meet any requirements in that spell, including costly components. The spell simply takes effect.\n\nAlternatively, you can create one of the following effects of your choice:\n\nYou create one object of up to 25,000 gp in value that isn’t a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space you can see on the ground.\n\nYou allow up to twenty creatures that you can see to regain all hit points, and you end all effects on them described in the Greater Restoration spell.\n\nYou grant up to ten creatures that you can see resistance to a damage type you choose.\n\nYou grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours. For instance, you could make yourself and all your companions immune to a lich’s life drain attack.\n\nYou undo a single recent event by forcing a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a Wish spell could undo an opponent’s successful save, a foe’s critical hit, or a friend’s failed save. You can force the reroll to be made with advantage or disadvantage, and you can choose whether to use the reroll or the original roll.\n\nYou might be able to achieve something beyond the scope of the above examples. State your wish to the DM as precisely as possible. The DM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might only be partly achieved, or you might suffer some unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a legendary magic item or artifact might instantly transport you to the presence of the item’s current owner.\n\nThe stress of casting this spell to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a long rest, you take 1d10 necrotic damage per level of that spell. This damage can’t be reduced or prevented in any way. In addition, you Strength drops to 3 if it isn’t 3 or lower already, for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast Wish* ever again if you suffer this stress." } },

  // === CANTRIPS ADICIONAIS ===
  { id: 'bladeWard',     level: 0, school: 'abjuration',   classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '1 round', desc: { pt: "Você estende a mão e traça um símbolo de proteção no ar. Até o fim do seu próximo turno, você tem resistência contra dano contundente, perfurante e cortante causado por ataques com armas.", en: "You extend your hand and trace a sigil of warding in the air. Until the end of your next turn, you have resistance against bludgeoning, piercing, and slashing damage dealt by weapon attacks." } },
  { id: 'dancingLights', level: 0, school: 'evocation',    classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você cria até quatro luzes do tamanho de tochas dentro do alcance, fazendo-as parecer tochas, lanternas ou esferas brilhantes que pairam no ar pela duração. Você também pode combinar as quatro luzes em uma forma brilhante vagamente humanoide de tamanho Médio. Qualquer que seja a forma escolhida, cada luz emite luz penumbrosa em um raio de 3 metros.\n\nComo uma ação bônus em seu turno, você pode mover as luzes até 18 metros para um novo ponto dentro do alcance. Uma luz deve estar a até 6 metros de outra luz criada por esta magia, e uma luz se apaga se ultrapassar o alcance da magia.", en: "You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.\n\nAs a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell's range." } },
  { id: 'friends',       level: 0, school: 'enchantment',  classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Self', components: 'S, M', duration: 'Conc. 1 min', desc: { pt: "Pela duração, você tem vantagem em todos os testes de Carisma direcionados a uma criatura à sua escolha que não seja hostil a você. Quando a magia termina, a criatura percebe que você usou magia para influenciar o humor dela e se torna hostil a você. Uma criatura propensa à violência pode atacar você. Outra criatura pode buscar retaliação de outras maneiras (a critério do Mestre), dependendo da natureza de sua interação com ela.", en: "For the duration, you have advantage on all Charisma checks directed at one creature of your choice that isn’t hostile toward you. When the spell ends, the creature realizes that you have used magic to influence its mood and becomes hostile toward you. A creature prone to violence might attack you. Another creature might seek retribution in other ways (at the DM’s discretion), depending on the nature of your interaction with it." } },
  { id: 'mending',       level: 0, school: 'transmutation', classes: ['bard','cleric','druid','wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Esta magia repara uma única quebra ou rasgo num objeto que você tocar, como um elo de corrente partido, as duas metades de uma chave quebrada, um manto rasgado ou um odre que vaza. Desde que a quebra ou o rasgo não tenha mais de 30 centímetros em nenhuma dimensão, você o conserta, sem deixar vestígio do dano anterior.\nEsta magia pode reparar fisicamente um item mágico, mas não pode restaurar a magia de tal objeto.", en: "This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage.\n\nThis spell can physically repair a magic item or construct, but the spell can't restore magic to such an object." } },
  { id: 'message',       level: 0, school: 'transmutation', classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: '1 round', desc: { pt: "Você aponta o dedo em direção a uma criatura dentro do alcance e sussurra uma mensagem. O alvo (e apenas o alvo) ouve a mensagem e pode responder em um sussurro que apenas você pode ouvir.\n\nVocê pode conjurar esta magia através de objetos sólidos se for familiarizado com o alvo e souber que ele está além da barreira. Silêncio mágico, 30 centímetros de pedra, 2,5 centímetros de metal comum, uma folha fina de chumbo ou 90 centímetros de madeira bloqueiam a magia. A magia não precisa seguir uma linha reta e pode viajar livremente contornando cantos ou através de aberturas.", en: "You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\n\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn't have to follow a straight line and can travel freely around corners or through openings." } },
  { id: 'produceFlame',  level: 0, school: 'conjuration',  classes: ['druid'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 min', desc: { pt: "Uma chama tremeluzente surge na sua mão. A chama permanece ali pela duração e não causa dano nem a você nem ao seu equipamento. A chama emite luz plena em um raio de 3 metros e penumbra por mais 3 metros adicionais. A magia termina se você a dispensar como uma ação ou se conjurá-la novamente.\n\nVocê também pode atacar com a chama, embora fazer isso encerre a magia. Quando conjura esta magia, ou como uma ação em um turno posterior, você pode arremessar a chama contra uma criatura a até 9 metros de você. Faça um ataque à distância com magia. Se acertar, o alvo sofre 1d8 de dano de fogo.\n\nO dano desta magia aumenta em 1d8 quando você atinge o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", en: "A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.\n\nYou can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)." } },
  { id: 'resistance',    level: 0, school: 'abjuration',   classes: ['cleric','druid'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você toca uma criatura voluntária. Uma vez antes de a magia terminar, o alvo pode rolar um d4 e adicionar o número rolado a um teste de resistência de sua escolha. Ele pode rolar o dado antes ou depois de realizar o teste de resistência. A magia então termina.", en: "You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends." } },
  { id: 'shillelagh',    level: 0, school: 'transmutation', classes: ['druid'], castingTime: '1 bonus action', range: 'Self', components: 'V, S, M', duration: '1 min', desc: { pt: "A madeira de uma clava ou bordão que você esteja segurando é imbuída com o poder da natureza. Pela duração, você pode usar seu atributo de conjuração em vez de Força para as jogadas de ataque e de dano de ataques corpo a corpo realizados com essa arma, e o dado de dano da arma se torna um d8. A arma também se torna mágica, caso já não seja. A magia termina se você a conjurar novamente ou se soltar a arma.", en: "The wood of a club or quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a d8. The weapon also becomes magical, if it isn't already. The spell ends if you cast it again or if you let go of the weapon." } },
  { id: 'thornWhip',     level: 0, school: 'transmutation', classes: ['druid'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você cria um chicote longo, semelhante a uma videira e coberto de espinhos, que fustiga sob o seu comando em direção a uma criatura dentro do alcance. Faça um ataque corpo a corpo com magia contra o alvo. Se o ataque atingir, a criatura sofre 1d6 de dano perfurante e, se a criatura for Grande ou menor, você a puxa até 3 metros para mais perto de você.\n\nO dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).", en: "You create a long, vine-like whip covered in thorns that lashes out at your command toward a creature in range. Make a melee spell attack against the target. If the attack hits, the creature takes 1d6 piercing damage, and if the creature is Large or smaller, you pull the creature up to 10 feet closer to you.\n\nThis spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)." } },
  { id: 'trueStrike',    level: 0, school: 'divination',   classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'S', duration: 'Conc. 1 round', desc: { pt: "Você estende sua mão e aponta um dedo para um alvo dentro do alcance. Sua magia concede a você uma breve intuição sobre as defesas do alvo. No seu próximo turno, você tem vantagem na sua primeira jogada de ataque contra o alvo, desde que esta magia não tenha terminado.", en: "You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn't ended." } },

  // === LEVEL 1 ADICIONAIS ===
  { id: 'alarm',                  level: 1, school: 'abjuration',   classes: ['ranger','wizard'], castingTime: '1 minute', range: '30 ft', components: 'V, S, M', duration: '8 hours', ritual: true, desc: { pt: "Você cria um alarme contra intrusões indesejadas. Escolha uma porta, uma janela ou uma área dentro do alcance que não seja maior que um cubo de 6 metros. Até a magia terminar, um alarme alerta você sempre que uma criatura Miúda ou maior tocar ou entrar na área protegida. Quando você conjura a magia, pode designar criaturas que não acionarão o alarme. Você também escolhe se o alarme é mental ou audível.\n\nUm alarme mental alerta você com um zumbido na sua mente se você estiver a até 1,5 quilômetro da área protegida. Esse aviso acorda você caso esteja dormindo.\n\nUm alarme audível produz o som de uma sineta de mão por 10 segundos audível a até 18 metros.", en: "You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is mental or audible.\n\nA mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.\n\nAn audible alarm produces the sound of a hand bell for 10 seconds within 60 feet." } },
  { id: 'animalFriendship',       level: 1, school: 'enchantment',  classes: ['bard','druid','ranger'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '24 hours', desc: { pt: "Esta magia permite convencer uma besta de que você não pretende lhe fazer mal. Escolha uma besta que você possa ver dentro do alcance. Ela deve ver e ouvir você. Se a Inteligência da besta for 4 ou superior, a magia falha. Caso contrário, a besta deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará enfeitiçada por você pela duração da magia. Se você ou um dos seus companheiros causar dano ao alvo, a magia se encerra.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode afetar uma besta adicional para cada círculo do espaço acima do 1º.", en: "This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast's Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a Wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spells ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional beast t level above 1st." } },
  { id: 'bane',                   level: 1, school: 'enchantment',  classes: ['bard','cleric'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Até três criaturas à sua escolha que você possa ver dentro do alcance devem fazer salvaguardas de Carisma. Sempre que um alvo que falhar nesta salvaguarda fizer uma jogada de ataque ou uma salvaguarda antes da magia acabar, o alvo deve rolar um d4 e subtrair o número rolado da jogada de ataque ou salvaguarda.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 1º.", en: "Up to three creatures of your choice that you can see within range must make Charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st." } },
  { id: 'colorSpray',             level: 1, school: 'illusion',     classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self (15-ft cone)', components: 'V, S, M', duration: '1 round', desc: { pt: "Um arranjo deslumbrante de luzes coloridas e piscantes brota da sua mão. Role 6d10; o total é a quantidade de Pontos de Vida de criaturas que esta magia pode afetar. Criaturas em um cone de 4,5 metros originado a partir de você são afetadas em ordem crescente de seus Pontos de Vida atuais (ignorando criaturas inconscientes e criaturas que não possam ver).\n\nComeçando pela criatura que tiver a menor quantidade de Pontos de Vida atuais, cada criatura afetada por esta magia fica cega até o final do seu próximo turno. Subtraia os Pontos de Vida de cada criatura do total antes de passar para a criatura com a próxima menor quantidade de Pontos de Vida. Os Pontos de Vida de uma criatura devem ser iguais ou menores que o total restante para que ela seja afetada.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, role 2d10 adicionais para cada círculo do espaço acima do 1º.", en: "A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can't see).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the end of your next turn. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st." } },
  { id: 'comprehendLanguages',    level: 1, school: 'divination',   classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', ritual: true, desc: { pt: "Pela duração, você compreende o significado literal de qualquer idioma falado que ouvir. Você também compreende qualquer idioma escrito que vir, mas deve estar tocando a superfície na qual as palavras estão escritas. Leva cerca de 1 minuto para ler uma página de texto.\n\nEsta magia não decodifica mensagens secretas em um texto ou glifo, como um símbolo arcano, que não faça parte de um idioma escrito.", en: "For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.\n\nThis spell doesn't decode secret messages in a text or a glyph, such as an arcane sigil, that isn't part of a written language." } },
  { id: 'createDestroyWater',     level: 1, school: 'transmutation', classes: ['cleric','druid'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você cria ou destrói água.\n\nCriar Água. Você cria até 40 litros de água limpa dentro do alcance em um recipiente aberto. Como alternativa, a água cai como chuva em um cubo de 9 metros dentro do alcance, extinguindo chamas expostas na área.\n\nDestruir Água. Você destrói até 40 litros de água em um recipiente aberto dentro do alcance. Como alternativa, você destrói névoa em um cubo de 9 metros dentro do alcance.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você cria ou destrói 40 litros adicionais de água, ou o tamanho do cubo aumenta em 1,5 metro, para cada círculo do espaço acima do 1º.", en: "You either create or destroy water.\n\nCreate Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range, extinguishing exposed flames in the area.\n\nDestroy Water. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st." } },
  { id: 'detectEvilAndGood',      level: 1, school: 'divination',   classes: ['cleric','paladin'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Conc. 10 min', desc: { pt: "Pela duração, você sabe se há uma aberração, celestial, elemental, fada, ínfero ou morto-vivo a até 9 metros de você, bem como onde a criatura está localizada. Da mesma forma, você sabe se há um local ou objeto a até 9 metros de você que tenha sido consagrado ou dessagrado magicamente.\n\nA magia pode penetrar a maioria das barreiras, mas é bloqueada por 30 centímetros de pedra, 2,5 centímetros de metal comum, uma folha fina de chumbo ou 90 centímetros de madeira ou terra.", en: "For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt." } },
  { id: 'detectPoisonAndDisease', level: 1, school: 'divination',   classes: ['cleric','druid','paladin','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Conc. 10 min', ritual: true, desc: { pt: "Pela duração, você pode sentir a presença e a localização de venenos, criaturas venenosas e doenças a até 9 metros de você. Você também identifica a espécie de veneno, criatura venenosa ou doença em cada caso.\n\nA magia pode penetrar a maioria das barreiras, mas é bloqueada por 30 centímetros de pedra, 2,5 centímetros de metal comum, uma folha fina de chumbo ou 90 centímetros de madeira ou terra.", en: "For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt." } },
  { id: 'expediteRetreat',        level: 1, school: 'transmutation', classes: ['sorcerer','warlock','wizard'], castingTime: '1 bonus action', range: 'Self', components: 'V, S', duration: 'Conc. 10 min', desc: { pt: "Esta magia permite que você se mova em um ritmo incrível. Quando você conjura esta magia, e depois como uma ação bônus em cada um dos seus turnos até a magia terminar, você pode realizar a ação de Disparada.", en: "This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action." } },
  { id: 'falseLife',              level: 1, school: 'necromancy',   classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', desc: { pt: "Fortalecendo-se com um simulacro necromântico de vida, você ganha 1d4 + 4 pontos de vida temporários pela duração.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, você ganha 5 pontos de vida temporários adicionais para cada círculo do espaço acima do 1º.", en: "Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st." } },
  { id: 'featherFall',            level: 1, school: 'transmutation', classes: ['bard','sorcerer','wizard'], castingTime: '1 reaction', range: '60 ft', components: 'V, M', duration: '1 min', desc: { pt: "Escolha até cinco criaturas em queda dentro do alcance. A velocidade de descida de uma criatura em queda é reduzida para 18 metros por rodada até a magia terminar. Se a criatura pousar antes de a magia terminar, ela não sofre dano da queda, e a magia termina para essa criatura.", en: "Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature." } },
  { id: 'findFamiliar',           level: 1, school: 'conjuration',  classes: ['wizard'], castingTime: '1 hour', range: '10 ft', components: 'V, S, M', duration: 'Instant', ritual: true, desc: { pt: "Você obtém os serviços de um familiar, um espírito que assume a forma de um animal à sua escolha: morcego, gato, caranguejo, sapo (rã), falcão, lagarto, polvo, coruja, serpente venenosa, peixe (quiper), rato, corvo, cavalo-marinho, aranha ou doninha. Surgindo em um espaço desocupado dentro do alcance, o familiar possui as estatísticas da forma escolhida, embora seja um celestial, fada ou corruptor (à sua escolha) em vez de uma besta.\n\nSeu familiar age independentemente de você, mas sempre obedece aos seus comandos. Em combate, ele rola sua própria iniciativa e age em seu próprio turno. Um familiar não pode atacar, mas pode realizar outras ações normalmente.\n\nQuando o familiar tem seus pontos de vida reduzidos a 0, ele desaparece, não deixando para trás nenhuma forma física. Ele ressurge após você conjurar esta magia novamente.\n\nEnquanto o familiar estiver a até 30 metros de você, você pode se comunicar com ele telepaticamente. Além disso, como uma ação, você pode enxergar através dos olhos do seu familiar e ouvir o que ele ouve até o início do seu próximo turno, recebendo os benefícios de quaisquer sentidos especiais que o familiar possua. Durante esse período, você fica surdo e cego em relação aos seus próprios sentidos.\n\nComo uma ação, você pode dispensar temporariamente seu familiar. Ele desaparece em uma dimensão de bolso onde aguarda sua convocação. Alternativamente, você pode dispensá-lo para sempre. Como uma ação enquanto ele estiver temporariamente dispensado, você pode fazê-lo reaparecer em qualquer espaço desocupado a até 9 metros de você.\n\nVocê não pode ter mais de um familiar por vez. Se conjurar esta magia enquanto já possuir um familiar, em vez disso você faz com que ele adote uma nova forma. Escolha uma das formas da lista acima. Seu familiar se transforma na criatura escolhida.\n\nPor fim, quando você conjura uma magia com alcance de toque, seu familiar pode descarregar a magia como se ele a tivesse conjurado. Seu familiar deve estar a até 30 metros de você e deve usar a reação dele para descarregar a magia quando você a conjura. Se a magia exigir uma jogada de ataque, você usa seu modificador de ataque para a jogada.", en: "You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.\n\nYour familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can't attack, but it can take other actions as normal.\n\nWhen the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again. \n\nWhile your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.\n\nAs an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.\n\nYou can't have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.\n\nFinally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your attack modifier for the roll." } },
  { id: 'fogCloud',               level: 1, school: 'conjuration',  classes: ['druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Você cria uma esfera de névoa com raio de 6 metros centrada em um ponto dentro do alcance. A esfera se espalha dobrando esquinas e curvas e sua área fica sob escuridão densa (fortemente obscurecida). Ela dura pela duração ou até que um vento de velocidade moderada ou superior (pelo menos 16 quilômetros por hora) a disperse.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, o raio da névoa aumenta em 6 metros para cada círculo do espaço acima do 1º.", en: "You create a 20-foot radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st." } },
  { id: 'grease',                 level: 1, school: 'conjuration',  classes: ['wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: '1 min', desc: { pt: "Gordura escorregadia cobre o chão em um quadrado de 3 metros centrado em um ponto dentro do alcance e o transforma em terreno difícil pela duração.\n\nQuando a graxa surge, cada criatura de pé na área deve ser bem-sucedida em um teste de resistência de Destreza ou cairá no chão (caída). Uma criatura que entrar na área ou terminar seu turno nela também deve ser bem-sucedida em um teste de resistência de Destreza ou cairá no chão.", en: "Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.\n\nWhen the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a Dexterity saving throw or fall prone." } },
  { id: 'heroism',                level: 1, school: 'enchantment',  classes: ['bard','paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Uma criatura voluntária que você toca é imbuída de bravura. Até a magia terminar, a criatura fica imune à condição amedrontado e ganha pontos de vida temporários iguais ao seu modificador de atributo de conjuração no início de cada um dos turnos dela. Quando a magia termina, o alvo perde quaisquer pontos de vida temporários restantes concedidos por esta magia.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 1º.", en: "A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st." } },
  { id: 'hideousLaughter',        level: 1, school: 'enchantment',  classes: ['bard','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Uma criatura à sua escolha que você possa ver dentro do alcance passa a ver tudo como comicamente engraçado e cai em crises incontroláveis de riso se esta magia a afetar. O alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou cairá no chão (caído), ficando incapacitado e incapaz de se levantar pela duração. Uma criatura com valor de Inteligência 4 ou menor não é afetada.\n\nAo final de cada um dos seus turnos, e a cada vez que sofrer dano, o alvo pode realizar outro teste de resistência de Sabedoria. O alvo tem vantagem na salvaguarda se ela for desencadeada por dano. Em um sucesso, a magia termina.", en: "A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a Wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn't affected.\n\nAt the end of each of its turns, and each time it takes damage, the target can make another Wisdom saving throw. The target has advantage on the saving throw if it's triggered by damage. On a success, the spell ends." } },
  { id: 'identifySpell',          level: 1, school: 'divination',   classes: ['bard','wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: 'Instant', ritual: true, desc: { pt: "Você toca um objeto durante toda a conjuração da magia. Se o objeto for um item mágico ou algum outro objeto mágico, você descobre suas propriedades e como usá-las, se ele exige Sintonização e quantas cargas possui, se houver. Você descobre se alguma magia em andamento está afetando o item e quais são. Se o item foi criado por uma magia, você descobre o nome dessa magia.\nSe, em vez disso, você tocar uma criatura durante toda a conjuração, descobre quais magias em andamento, se houver, a estão afetando no momento.", en: "You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.\n\nIf you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it." } },
  { id: 'inflictWounds',          level: 1, school: 'necromancy',   classes: ['cleric'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Faça um ataque corpo a corpo com magia contra uma criatura que você possa alcançar. Em um acerto, o alvo sofre 3d10 de dano necrótico.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 1º.", en: "Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st." } },
  { id: 'jump',                   level: 1, school: 'transmutation', classes: ['druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 min', desc: { pt: "Você toca uma criatura. A distância de salto da criatura é triplicada até a magia terminar.", en: "You touch a creature. The creature's jump distance is tripled until the spell ends." } },
  { id: 'longstrider',            level: 1, school: 'transmutation', classes: ['bard','druid','ranger','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', desc: { pt: "Você toca uma criatura. O deslocamento do alvo aumenta em 3 metros até a magia terminar.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 1º.", en: "You touch a creature. The target's speed increases by 10 feet until the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st." } },
  { id: 'mageArmor',              level: 1, school: 'abjuration',   classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', desc: { pt: "Você toca uma criatura voluntária que não esteja usando armadura. Até a magia terminar, a CA base do alvo passa a ser 13 mais o seu modificador de Destreza. A magia termina antecipadamente se o alvo vestir uma armadura.", en: "You touch a willing creature who isn't wearing armor, and a protective magical force surrounds it until the spell ends. The target's base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action." } },
  { id: 'protectionFromEvilGood', level: 1, school: 'abjuration',   classes: ['cleric','druid','paladin','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Até a magia terminar, uma criatura voluntária que você tocar fica protegida contra certos tipos de criaturas: aberrações, celestiais, elementais, fadas, corruptores e mortos-vivos.\n\nA proteção concede diversos benefícios. Criaturas desses tipos têm desvantagem em jogadas de ataque contra o alvo. O alvo também não pode ser enfeitiçado, amedrontado ou possuído por elas. Se o alvo já estiver enfeitiçado, amedrontado ou possuído por tal criatura, o alvo tem vantagem em qualquer nova salvaguarda contra o efeito relevante.", en: "Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.\n\nThe protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can’t be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect." } },
  { id: 'purifyFoodAndDrink',     level: 1, school: 'transmutation', classes: ['cleric','druid','paladin'], castingTime: '1 action', range: '10 ft', components: 'V, S', duration: 'Instant', ritual: true, desc: { pt: "Toda comida e bebida não mágicas contidas em uma esfera de 1,5 metro de raio centrada em um ponto de sua escolha dentro do alcance são purificadas e livres de veneno e doenças.", en: "All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease." } },
  { id: 'rayOfSickness',          level: 1, school: 'necromancy',   classes: ['sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Um raio de energia esverdeada e nauseante dispara em direção a uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 2d8 de dano de veneno e deve fazer uma salvaguarda de Constituição. Se falhar na salvaguarda, ele também fica envenenado até o final do seu próximo turno.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 1º.", en: "A ray of sickening greenish energy lashes out toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 2d8 poison damage and must make a Constitution saving throw. On a failed save, it is also poisoned until the end of your next turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st." } },
  { id: 'shieldOfFaith',          level: 1, school: 'abjuration',   classes: ['cleric','paladin'], castingTime: '1 bonus action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Um campo cintilante envolve uma criatura à sua escolha dentro do alcance, concedendo-lhe +2 de bônus na CA pela duração.", en: "A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration." } },
  { id: 'silentImage',            level: 1, school: 'illusion',     classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você cria a imagem de um objeto, de uma criatura ou de algum outro fenômeno visível que não seja maior que um Cubo de 4,5 metros. A imagem aparece em um ponto dentro do alcance e dura pela duração. A imagem é puramente visual; não é acompanhada de som, cheiro ou outros efeitos sensoriais.\nComo uma ação de Magia, você pode fazer a imagem se mover para qualquer ponto dentro do alcance. Enquanto a imagem muda de local, você pode alterar sua aparência para que seus movimentos pareçam naturais. Por exemplo, se você criar a imagem de uma criatura e movê-la, pode alterar a imagem para que ela pareça estar andando.\nA interação física com a imagem revela que ela é uma ilusão, já que as coisas podem atravessá-la. Uma criatura que realizar a ação Estudar para examinar a imagem pode determinar que ela é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD de resistência da sua magia. Se uma criatura discernir a ilusão pelo que ela é, a criatura pode ver através da imagem.", en: "You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects.\n\nYou can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image." } },
  { id: 'speakWithAnimals',       level: 1, school: 'divination',   classes: ['bard','druid','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 min', ritual: true, desc: { pt: "Você adquire a capacidade de compreender e se comunicar verbalmente com feras pela duração. O conhecimento e a percepção de muitas feras são limitados pela sua inteligência, mas no mínimo as feras podem lhe fornecer informações sobre locais próximos e monstros, incluindo qualquer coisa que possam perceber ou tenham percebido nas últimas vinte e quatro horas. Você pode conseguir persuadir uma fera a prestar um pequeno favor a você, a critério do Mestre.", en: "You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM's discretion." } },
  { id: 'wrathfulSmite',          level: 1, school: 'evocation',    classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Conc. 1 min', desc: { pt: "Na próxima vez que você atingir com um ataque corpo a corpo com arma durante a duração desta magia, seu ataque causa 1d6 de dano psíquico adicional. Além disso, se o alvo for uma criatura, ele deve fazer uma salvaguarda de Sabedoria ou ficará amedrontado por você até a magia terminar. Com uma ação, a criatura pode fazer um teste de Sabedoria contra a CD de salvaguarda da sua magia para recuperar sua determinação e encerrar esta magia.", en: "The next time you hit with a melee weapon attack during this spell’s duration, your attack deals an extra 1d6 psychic damage. Additionally, if the target is a creature, it must make a Wisdom saving throw or be frightened of you until the spell ends. As an action, the creature can make a Wisdom check against your spell save DC to steel its resolve and end this spell." } },

  // === LEVEL 2 ADICIONAIS ===
  { id: 'animalMessenger',        level: 2, school: 'enchantment',  classes: ['bard','druid','ranger'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '24 hours', ritual: true, desc: { pt: "Por meio desta magia, você usa um animal para entregar uma mensagem. Escolha uma besta Miúda que você possa ver dentro do alcance, como um esquilo, um gaio-azul ou um morcego. Você especifica um local, que deve ter visitado, e um destinatário que corresponda a uma descrição geral, como \"um homem ou mulher vestido com o uniforme da guarda da cidade\" ou \"um anão ruivo usando um chapéu pontudo\". Você também pronuncia uma mensagem de até vinte e cinco palavras. A besta alvo viaja pela duração da magia em direção ao local especificado, cobrindo cerca de 75 quilômetros a cada 24 horas para um mensageiro voador, ou 37,5 quilômetros para outros animais.\n\nQuando o mensageiro chega, ele entrega sua mensagem à criatura descrita, replicando o som da sua voz. O mensageiro fala apenas com uma criatura que corresponda à descrição fornecida. Se o mensageiro não alcançar seu destino antes da magia terminar, a mensagem é perdida e a besta faz o caminho de volta até onde você conjurou esta magia.\n\nEm Níveis Superiores. Se você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, a duração da magia aumenta em 48 horas para cada círculo do espaço acima do 2º.", en: "By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \"a man or woman dressed in the uniform of the town guard\" or \"a red-haired dwarf wearing a pointed hat.\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.\n\nWhen the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn't reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell.\n\nAt Higher Levels. If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd." } },
  { id: 'barkskin',               level: 2, school: 'transmutation', classes: ['druid','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Você toca uma criatura voluntária. Até a magia acabar, a pele do alvo adquire uma aparência áspera, semelhante a casca de árvore, e a CA do alvo não pode ser menor que 16, independentemente do tipo de armadura que ele estiver vestindo.", en: "You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing." } },
  { id: 'blindnessDeafness',      level: 2, school: 'necromancy',   classes: ['bard','cleric','sorcerer','wizard'], castingTime: '1 action', range: '30 ft', components: 'V', duration: '1 min', desc: { pt: "Você pode cegar ou ensurdecer um adversário. Escolha uma criatura que você possa ver dentro do alcance para fazer uma salvaguarda de Constituição. Se falhar, o alvo fica cego ou surdo (à sua escolha) pela duração. No final de cada um dos turnos dele, o alvo pode fazer uma salvaguarda de Constituição. Em caso de sucesso, a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 2º.", en: "You can blind or deafen a foe. Choose one creature that you can see within range to make a Constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a Constitution saving throw. On a success, the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd." } },
  { id: 'brandingSmite',          level: 2, school: 'evocation',    classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Conc. 1 min', desc: { pt: "Na próxima vez que você atingir uma criatura com um ataque com arma antes desta magia terminar, a arma brilha com radiância astral enquanto você golpeia. O ataque causa 2d6 de dano radiante extra ao alvo, que se torna visível se estiver invisível, e o alvo emite luz penumbrosa em um raio de 1,5 metro e não pode ficar invisível até a magia terminar.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano extra aumenta em 1d6 para cada círculo do espaço acima do 2º.", en: "The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends. \n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd." } },
  { id: 'cloudOfDaggers',         level: 2, school: 'conjuration',  classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você enche o ar com adagas giratórias em um cubo de 1,5 metro de lado, centrado em um ponto à sua escolha dentro do alcance. Uma criatura sofre 4d4 de dano cortante quando entra na área da magia pela primeira vez em um turno ou quando começa o turno dela lá.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 2d4 para cada círculo do espaço acima do 2º.", en: "You fill the air with spinning daggers in a cube 5 feet on each side, centered on a point you choose within range. A creature takes 4d4 slashing damage when it enters the spell’s area for the first time on a turn or starts its turn there.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d4 for each slot level above 2nd." } },
  { id: 'darkvision',             level: 2, school: 'transmutation', classes: ['druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', desc: { pt: "Você toca uma criatura voluntária para conceder a ela a habilidade de ver no escuro. Pela duração, essa criatura possui visão no escuro até um alcance de 18 metros.", en: "You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet." } },
  { id: 'enhanceAbility',         level: 2, school: 'transmutation', classes: ['bard','cleric','druid','sorcerer'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Você toca uma criatura e concede a ela um aprimoramento mágico. Escolha um dos seguintes efeitos; o alvo recebe esse efeito até a magia terminar.\n\nResistência do Urso. O alvo tem vantagem em testes de Constituição. Ele também ganha 2d6 pontos de vida temporários, que são perdidos quando a magia termina.\n\nForça do Touro. O alvo tem vantagem em testes de Força e sua capacidade de carga é dobrada.\n\nGraça do Gato. O alvo tem vantagem em testes de Destreza. Ele também não sofre dano por cair de uma altura de 6 metros ou menos se não estiver incapacitado.\n\nEsplendor da Águia. O alvo tem vantagem em testes de Carisma.\n\nAstúcia da Raposa. O alvo tem vantagem em testes de Inteligência.\n\nSabedoria da Coruja. O alvo tem vantagem em testes de Sabedoria.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 2º.", en: "You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.\n\nBear's Endurance. The target has advantage on Constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.\n\nBull's Strength. The target has advantage on Strength checks, and his or her carrying capacity doubles.\n\nCat's Grace. The target has advantage on Dexterity checks. It also doesn't take damage from falling 20 feet or less if it isn't incapacitated.\n\nEagle's Splendor. The target has advantage on Charisma checks.\n\nFox's Cunning. The target has advantage on Intelligence checks.\n\nOwl's Wisdom. The target has advantage on Wisdom checks.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd." } },
  { id: 'findSteed',              level: 2, school: 'conjuration',  classes: ['paladin'], castingTime: '10 minutes', range: '30 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Você invoca um espírito que assume a forma de uma montaria extraordinariamente inteligente, forte e leal, criando um vínculo duradouro com ela. Surgindo em um espaço desocupado dentro do alcance, a montaria assume uma forma que você escolher: um cavalo de guerra, um pônei, um camelo, um alce ou um mastim. (Seu Mestre pode permitir que outros animais sejam invocados como montarias.) A montaria possui as estatísticas da forma escolhida, embora seja um celestial, fada ou corruptor (à sua escolha) em vez de seu tipo normal. Além disso, se a sua montaria tiver Inteligência 5 ou menor, a Inteligência dela se torna 6 e ela adquire a capacidade de compreender um idioma à sua escolha que você fale.\n\nSua montaria serve a você como montaria, tanto em combate quanto fora dele, e você possui um vínculo instintivo com ela que lhe permite lutar como uma unidade perfeita. Enquanto estiver montado na sua montaria, você pode fazer com que qualquer magia que conjurar tendo apenas você como alvo também tenha a sua montaria como alvo.\n\nQuando a montaria é reduzida a 0 pontos de vida, ela desaparece, não deixando nenhuma forma física. Você também pode dispensar sua montaria a qualquer momento como uma ação, fazendo com que ela desapareça. Em qualquer um dos casos, conjurar esta magia novamente invoca a mesma montaria, restaurada ao seu máximo de pontos de vida.\n\nEnquanto a sua montaria estiver a até 1,5 quilômetro de você, vocês podem se comunicar telepaticamente.\n\nVocê não pode ter mais de uma montaria vinculada por esta magia ao mesmo tempo. Como uma ação, você pode libertar a montaria de seu vínculo a qualquer momento, fazendo-a desaparecer.", en: "You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose: a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\n\nYour steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.\n\nWhen the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.\n\nWhile your steed is within 1 mile of you, you can communicate with each other telepathically.\n\nYou can't have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear." } },
  { id: 'findTraps',              level: 2, school: 'divination',   classes: ['cleric','druid','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Instant', desc: { pt: "Você sente a presença de qualquer armadilha dentro do alcance que esteja dentro da sua linha de visão. Uma armadilha, para o propósito desta magia, inclui qualquer coisa que cause um efeito repentino ou inesperado que você considere prejudicial ou indesejável, o qual foi especificamente pretendido como tal por seu criador. Assim, a magia detectaria uma área afetada pela magia alarme, um glifo de vigilância ou uma armadilha mecânica de fosso, mas não revelaria uma fraqueza natural no piso, um teto instável ou um sumidouro oculto.\n\nEsta magia meramente revela que uma armadilha está presente.\n\nVocê não descobre a localização exata de cada armadilha, mas compreende a natureza geral do perigo apresentado pela armadilha que você sentiu.", en: "You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the alarm spell, a glyph of warding, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\n\nThis spell merely reveals that a trap is present.\n\nYou don't learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense." } },
  { id: 'flameBlade',             level: 2, school: 'evocation',    classes: ['druid','sorcerer'], castingTime: '1 bonus action', range: 'Self', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você evoca uma lâmina ardente em sua mão livre. A lâmina é similar em tamanho e forma a uma cimitarra e dura pela duração da magia. Se soltar a lâmina, ela desaparece, mas você pode evocá-la novamente como uma ação bônus.\n\nVocê pode usar sua ação para fazer um ataque corpo a corpo com magia usando a lâmina ardente. Em um acerto, o alvo sofre 3d6 de dano de fogo.\n\nA lâmina flamejante emite luz plena em um raio de 3 metros e penumbra por mais 3 metros adicionais.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 para cada dois círculos do espaço acima do 2º.", en: "You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.\n\nYou can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.\n\nThe flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd." } },
  { id: 'flamingSphere',          level: 2, school: 'conjuration',  classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Uma esfera de fogo com 1,5 metro de diâmetro aparece em um espaço desocupado à sua escolha dentro do alcance e permanece pela duração. Qualquer criatura que terminar seu turno a até 1,5 metro da esfera deve realizar um teste de resistência de Destreza. A criatura sofre 2d6 de dano de fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nComo uma ação bônus, você pode mover a esfera por até 9 metros. Se você abalroar a esfera contra uma criatura, essa criatura deve realizar o teste de resistência contra o dano da esfera e a esfera para de se mover neste turno.\n\nQuando você move a esfera, pode direcioná-la por cima de barreiras de até 1,5 metro de altura e fazê-la saltar por fossos de até 3 metros de largura. A esfera incendeia objetos inflamáveis que não estejam sendo vestidos ou carregados e emite luz plena em um raio de 6 metros e penumbra por mais 6 metros adicionais.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 2º.", en: "A 5-foot diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a Dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\n\nAs a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere's damage, and the sphere stops moving this turn.\n\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd." } },
  { id: 'gentleRepose',           level: 2, school: 'necromancy',   classes: ['cleric','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '10 days', ritual: true, desc: { pt: "Você toca um cadáver ou outros restos mortais. Pela duração, o alvo fica protegido contra a decomposição e não pode se tornar um Morto-Vivo.\nA magia também estende efetivamente o limite de tempo para trazer o alvo de volta dos mortos, já que os dias passados sob a influência desta magia não contam para o limite de tempo de magias como Reviver os Mortos.", en: "You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead.\n\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as raise dead." } },
  { id: 'gustOfWind',             level: 2, school: 'evocation',    classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: 'Self (60-ft line)', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Uma Linha de vento forte com 18 metros de comprimento e 3 metros de largura sopra a partir de você em uma direção à sua escolha pela duração. Cada criatura na Linha deve ser bem-sucedida em um teste de resistência de Força ou será empurrada 4,5 metros para longe de você em uma direção que acompanhe a Linha. Uma criatura que terminar seu turno na Linha deve realizar o mesmo teste.\nQualquer criatura na Linha deve gastar 60 centímetros de movimento para cada 30 centímetros que se mover ao se aproximar de você.\nA lufada dispersa gases ou vapores e apaga velas e chamas desprotegidas semelhantes na área. Ela faz chamas protegidas, como as de lanternas, tremularem violentamente e tem 50 por cento de chance de apagá-las.\nComo uma Ação Bônus em seus turnos posteriores, você pode mudar a direção em que a Linha sopra a partir de você.", en: "A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell's duration. Each creature that starts its turn in the line must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the line.\n\nAny creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\n\nThe gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\n\nAs a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you." } },
  { id: 'heatMetal',              level: 2, school: 'transmutation', classes: ['bard','druid'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Escolha um objeto manufaturado de metal, como uma arma de metal ou um traje de armadura de metal média ou pesada, que você possa ver dentro do alcance. Você faz o objeto brilhar incandescente em brasa. Qualquer criatura em contato físico com o objeto sofre 2d8 de dano de fogo quando você conjura a magia. Até a magia terminar, você pode usar uma ação bônus em cada um dos seus turnos subsequentes para causar esse dano novamente.\n\nSe uma criatura estiver segurando ou vestindo o objeto e sofrer o dano dele, a criatura deve ser bem-sucedida em um teste de resistência de Constituição ou largará o objeto se puder. Se não largar o objeto, ela terá desvantagem em jogadas de ataque e testes de atributo até o início do seu próximo turno.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.", en: "Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.\n\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn't drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd." } },
  { id: 'lesserRestoration',      level: 2, school: 'abjuration',   classes: ['bard','cleric','druid','paladin','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Você toca uma criatura e encerra uma condição nela: Cego, Surdo, Paralisado ou Envenenado.", en: "You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned." } },
  { id: 'levitate',               level: 2, school: 'transmutation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Uma criatura ou objeto solto à sua escolha que você possa ver dentro do alcance sobe verticalmente até 6 metros e permanece suspenso ali pela duração. A magia pode levitar um objeto que pese até 250 kg. Uma criatura relutante que seja bem-sucedida em um teste de resistência de Constituição não é afetada.\nO alvo só pode se mover empurrando ou puxando um objeto fixo ou superfície ao seu alcance (como uma parede ou um teto), o que lhe permite se mover como se estivesse escalando. Você pode alterar a altitude do alvo em até 6 metros em qualquer direção no seu turno. Se você for o alvo, pode subir ou descer como parte do seu movimento. Caso contrário, você pode realizar uma ação de Magia para mover o alvo, que deve permanecer dentro do alcance da magia.\nQuando a magia termina, o alvo flutua suavemente até o chão se ainda estiver no ar.", en: "One creature or loose object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected.\n\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell's range.\n\nWhen the spell ends, the target floats gently to the ground if it is still aloft." } },
  { id: 'locateAnimalsPlants',    level: 2, school: 'divination',   classes: ['bard','druid','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Inst.', ritual: true, desc: { pt: "Descreva ou nomeie uma espécie específica de besta ou planta. Concentrando-se na voz da natureza ao seu redor, você descobre a direção e a distância até a criatura ou planta mais próxima dessa espécie a até 7,5 quilômetros, se houver alguma presente.", en: "Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present." } },
  { id: 'locateObject',           level: 2, school: 'divination',   classes: ['bard','cleric','druid','paladin','ranger','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Descreva ou nomeie um objeto que lhe seja familiar. Você percebe a direção da localização do objeto se ele estiver a até 300 metros de você. Se o objeto estiver em movimento, você sabe a direção do seu movimento.\nA magia pode localizar um objeto específico conhecido por você se você o tiver visto de perto — a até 9 metros — pelo menos uma vez. Alternativamente, a magia pode localizar o objeto mais próximo de um tipo específico, como um certo tipo de vestimenta, joia, móvel, ferramenta ou arma.\nEsta magia não consegue localizar um objeto se qualquer espessura de chumbo bloquear o caminho direto entre você e o objeto.", en: "Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\n\nThe spell can locate a specific object known to you, as long as you have seen it up close-within 30 feet-at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\n\nThis spell can't locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object." } },
  { id: 'magicWeapon',            level: 2, school: 'transmutation', classes: ['paladin','wizard'], castingTime: '1 bonus action', range: 'Touch', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Você toca uma arma não mágica. Até a magia terminar, aquela arma se torna uma arma mágica com um bônus de +1 nas jogadas de ataque e jogadas de dano.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 4º círculo ou superior, o bônus aumenta para +2. Quando você usa um espaço de magia de 6º círculo ou superior, o bônus aumenta para +3.", en: "You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3." } },
  { id: 'moonbeam',               level: 2, school: 'evocation',    classes: ['druid'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Um feixe prateado de luz pálida brilha em um cilindro de 1,5 metro de raio e 12 metros de altura, centrado em um ponto dentro do alcance. Até a magia terminar, penumbra preenche o cilindro.\n\nQuando uma criatura entra na área da magia pela primeira vez em um turno ou começa seu turno lá, ela é envolvida por chamas fantasmagóricas que causam dor lancinante, devendo realizar um teste de resistência de Constituição. Ela sofre 2d10 de dano radiante se falhar no teste, ou metade desse dano se obtiver sucesso.\n\nUm metamorfo realiza esse teste de resistência com desvantagem. Se falhar, ele também reverte instantaneamente à sua forma original e não pode assumir uma forma diferente até sair da luz da magia.\n\nEm cada um dos seus turnos após conjurar esta magia, você pode usar uma ação para mover o feixe em até 18 metros em qualquer direção.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 2º.", en: "A silvery beam of pale light shines down in a 5-foot radius, 40-foot high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a Constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.\n\nA shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can't assume a different form until it leaves the spell's light.\n\nOn each of your turns after you cast this spell, you can use an action to move the beam up to 60 feet in any direction.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d10 for each slot level above 2nd." } },
  { id: 'passWithoutTrace',       level: 2, school: 'abjuration',   classes: ['druid','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Um véu de sombras e silêncio irradia de você, ocultando você e seus companheiros de detecção. Pela duração, cada criatura que você escolher a até 9 metros de você (incluindo você) recebe um bônus de +10 em testes de Destreza (Furtividade) e não pode ser rastreada exceto por meios mágicos. Uma criatura que receba esse bônus não deixa pegadas ou outros vestígios de sua passagem.", en: "A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can't be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage." } },
  { id: 'prayerOfHealing',        level: 2, school: 'evocation',    classes: ['cleric'], castingTime: '10 minutes', range: '30 ft', components: 'V', duration: 'Instant', desc: { pt: "Até seis criaturas de sua escolha que você possa ver dentro do alcance recuperam, cada uma, uma quantidade de Pontos de Vida igual a 2d8 + seu modificador de atributo de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, a cura aumenta em 1d8 para cada círculo do espaço acima do 2º.", en: "Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd." } },
  { id: 'protectionFromPoison',   level: 2, school: 'abjuration',   classes: ['cleric','druid','paladin','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '1 hour', desc: { pt: "Você toca uma criatura. Se ela estiver envenenada, você neutraliza o veneno. Se mais de um veneno afligir o alvo, você neutraliza um veneno que você saiba estar presente ou neutraliza um aleatoriamente.\n\nPela duração, o alvo tem vantagem em testes de resistência para evitar a condição envenenado e recebe resistência a dano de veneno.", en: "You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.\n\nFor the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage." } },
  { id: 'rayOfEnfeeblement',      level: 2, school: 'necromancy',   classes: ['warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Um raio negro de energia enervante brota do seu dedo em direção a uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se acertar, o alvo causa apenas metade do dano com ataques armados que usem Força até a magia terminar.\n\nAo final de cada um dos turnos do alvo, ele pode realizar um teste de resistência de Constituição contra a magia. Em caso de sucesso, a magia termina.", en: "A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.\n\nAt the end of each of the target's turns, it can make a Constitution saving throw against the spell. On a success, the spell ends." } },
  { id: 'seeInvisibility',        level: 2, school: 'divination',   classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', desc: { pt: "Pela duração, você vê criaturas e objetos que tenham a condição Invisível como se fossem visíveis, e pode ver o Plano Etéreo. Criaturas e objetos lá parecem fantasmagóricos.", en: "For the duration, you see invisible creatures and objects as if they were visible, and you can see into the Ethereal Plane. Ethereal creatures and objects appear ghostly and translucent." } },
  { id: 'shatter',                level: 2, school: 'evocation',    classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Um estrondo ressoante e repentino, dolorosamente intenso, irrompe de um ponto de sua escolha dentro do alcance. Cada criatura em uma esfera de 3 metros de raio centrada naquele ponto deve realizar um teste de resistência de Constituição. Uma criatura sofre 3d8 de dano trovejante em caso de falha no teste, ou metade desse dano em caso de sucesso. Uma criatura feita de material inorgânico, como pedra, cristal ou metal, tem desvantagem nesse teste de resistência.\n\nUm objeto não mágico que não esteja sendo vestido ou carregado também sofre o dano se estiver na área da magia.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.", en: "A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.\n\nA nonmagical object that isn't being worn or carried also takes the damage if it's in the spell's area.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd." } },
  { id: 'silence',                level: 2, school: 'illusion',     classes: ['bard','cleric','ranger'], castingTime: '1 action', range: '120 ft', components: 'V, S', duration: 'Conc. 10 min', ritual: true, desc: { pt: "Pela duração, nenhum som pode ser criado dentro de uma Esfera com 6 metros de raio centrada em um ponto à sua escolha dentro do alcance, nem atravessá-la. Qualquer criatura ou objeto totalmente dentro da Esfera tem Imunidade a dano Trovejante, e as criaturas têm a condição Surdo enquanto estiverem totalmente dentro dela. Conjurar uma magia que inclua um componente Verbal é impossível ali.", en: "For the duration, no sound can be created within or pass through a 20-foot radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it. Casting a spell that includes a verbal component is impossible there." } },
  { id: 'suggestion',             level: 2, school: 'enchantment',  classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, M', duration: 'Conc. 8 hours', desc: { pt: "Você sugere um curso de atividade (limitado a uma ou duas frases) e influencia magicamente uma criatura que possa ver dentro do alcance e que possa ouvi-lo e compreendê-lo. Criaturas que não possam ser enfeitiçadas são imunes a este efeito. A sugestão deve ser redigida de modo a fazer o curso de ação soar razoável. Pedir à criatura para se apunhalar, arremessar-se sobre uma lança, imolar-se ou praticar qualquer outro ato comprovadamente prejudicial encerra a magia.\n\nO alvo deve realizar um teste de resistência de Sabedoria. Em caso de falha no teste, ele segue o curso de ação descrito o melhor que puder. O curso de ação sugerido pode prosseguir por toda a duração. Se a atividade sugerida puder ser concluída em um tempo menor, a magia termina quando o alvo concluir o que foi solicitado.\n\nVocê também pode especificar condições que ativarão uma atividade especial durante a duração. Por exemplo, você pode sugerir que uma cavaleira entregue seu cavalo de batalha ao primeiro mendigo que encontrar. Se a condição não for atendida antes de a magia expirar, a atividade não será realizada.\n\nSe você ou qualquer um dos seus companheiros causar dano ao alvo, a magia termina.", en: "You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.\n\nThe target must make a Wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn't met before the spell expires, the activity isn't performed.\n\nIf you or any of your companions damage the target, the spell ends." } },
  { id: 'zoneOfTruth',            level: 2, school: 'enchantment',  classes: ['cleric','paladin'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: '10 min', desc: { pt: "Você cria uma zona mágica contra o engano em uma esfera de 4,5 metros de raio centrada em um ponto de sua escolha dentro do alcance. Até a magia terminar, uma criatura que entrar na área da magia pela primeira vez em um turno ou começar o turno lá deve realizar um teste de resistência de Carisma. Em caso de falha no teste, uma criatura não pode dizer uma mentira deliberada enquanto estiver dentro do raio. Você sabe se cada criatura obteve sucesso ou falhou no teste de resistência.\n\nUma criatura afetada tem consciência da magia e, portanto, pode evitar responder a perguntas às quais normalmente responderia com uma mentira. Essa criatura pode ser evasiva em suas respostas, desde que permaneça dentro dos limites da verdade.", en: "You create a magical zone that guards against deception in a 15-foot radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.\n\nAn affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can be evasive in its answers as long as it remains within the boundaries of the truth." } },

  // === LEVEL 3 ADICIONAIS ===
  { id: 'beaconOfHope',           level: 3, school: 'abjuration',   classes: ['cleric'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Esta magia concede esperança e vitalidade. Escolha qualquer número de criaturas dentro do alcance. Pela duração, cada alvo tem vantagem em salvaguardas de Sabedoria e salvaguardas contra a morte, e recupera a quantidade máxima de Pontos de Vida possível de qualquer cura.", en: "This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on Wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing." } },
  { id: 'bestowCurse',            level: 3, school: 'necromancy',   classes: ['bard','cleric','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você toca uma criatura, e essa criatura deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará amaldiçoada pela duração da magia. Quando você conjura esta magia, escolha a natureza da maldição entre as seguintes opções:\n\n- Escolha um valor de habilidade. Enquanto amaldiçoado, o alvo tem desvantagem em testes de habilidade e salvaguardas feitas com aquele valor de habilidade.\n- Enquanto amaldiçoado, o alvo tem desvantagem em jogadas de ataque contra você.\n- Enquanto amaldiçoado, o alvo deve fazer uma salvaguarda de Sabedoria no início de cada um dos turnos dele. Se falhar, gasta a ação naquele turno sem fazer nada.\n- Enquanto o alvo estiver amaldiçoado, seus ataques e magias causam 1d8 de dano necrótico extra ao alvo.\n\nA magia remover maldição encerra este efeito. A critério do Mestre, você pode escolher um efeito de maldição alternativo, mas ele não deve ser mais poderoso do que os descritos acima. O Mestre tem a palavra final sobre o efeito de tal maldição.\n\nEm Níveis Superiores. Se você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a duração é concentração, até 10 minutos. Se você usar um espaço de magia de 5º círculo ou superior, a duração é de 8 horas. Se você usar um espaço de magia de 7º círculo ou superior, a duração é de 24 horas. Se você usar um espaço de magia de 9º círculo, a magia dura até ser dissipada. Usar um espaço de magia de 5º círculo ou superior concede uma duração que não exige concentração.", en: "You touch a creature, and that creature must succeed on a Wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:\n\n- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.\n- While cursed, the target has disadvantage on attack rolls against you.\n- While cursed, the target must make a Wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.\n- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.\n\nA remove curse spell ends this effect. At the GM's option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse's effect.\n\nAt Higher Levels. If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn't require concentration." } },
  { id: 'clairvoyance',           level: 3, school: 'divination',   classes: ['bard','cleric','sorcerer','wizard'], castingTime: '10 min', range: '1 mile', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você cria um sensor Invisível dentro do alcance, em um local que lhe seja familiar (um lugar que você já visitou ou viu antes) ou em um local óbvio que não lhe seja familiar (como atrás de uma porta, depois de uma esquina ou em um bosque de árvores). O sensor intangível e invulnerável permanece no lugar pela duração.\nAo conjurar a magia, escolha visão ou audição. Você pode usar o sentido escolhido por meio do sensor como se estivesse no espaço dele. Como uma Ação Bônus, você pode alternar entre visão e audição.\nUma criatura que veja o sensor (como uma criatura beneficiada por Ver o Invisível ou Visão Verdadeira) vê uma esfera luminosa do tamanho do seu punho.", en: "You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with.\n\nWhen you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.\n\nA creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist." } },
  { id: 'conjureAnimals',         level: 3, school: 'conjuration',  classes: ['druid','ranger'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Você conjura espíritos feéricos que assumem a forma de bestas e surgem em espaços desocupados que você possa ver dentro do alcance. Escolha uma das seguintes opções para o que aparece:\n\n- Uma besta de nível de desafio 2 ou inferior\n- Duas bestas de nível de desafio 1 ou inferior\n- Quatro bestas de nível de desafio 1/2 ou inferior\n- Oito bestas de nível de desafio 1/4 ou inferior\n\nCada besta também é considerada uma fada e desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nAs criaturas conjuradas são amistosas a você e aos seus companheiros. Role iniciativa para as criaturas conjuradas como um grupo, que possui seus próprios turnos. Elas obedecem a quaisquer comandos verbais que você emitir para elas (nenhuma ação exigida de você). Se você não emitir nenhum comando para elas, elas se defendem de criaturas hostis, mas caso contrário não realizam ações.\n\nO Mestre tem as estatísticas das criaturas.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima, e mais criaturas aparecem: o dobro com um espaço de 5º círculo, o triplo com um espaço de 7º círculo e quatro vezes mais com um espaço de 9º círculo.", en: "You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One beast of challenge rating 2 or lower\n- Two beasts of challenge rating 1 or lower\n- Four beasts of challenge rating 1/2 or lower\n- Eight beasts of challenge rating 1/4 or lower\n\nEach beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.\n\nAt Higher Levels. When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level slot, and four times as many with a 9th-level slot." } },
  { id: 'daylight',               level: 3, school: 'evocation',    classes: ['cleric','druid','paladin','ranger','sorcerer'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: '1 hour', desc: { pt: "Uma esfera de luz com 18 metros de raio se espalha a partir de um ponto à sua escolha dentro do alcance. A esfera emite luz brilhante e irradia luz penumbrosa por 18 metros adicionais.\n\nSe você escolheu um ponto em um objeto que esteja segurando ou em um que não esteja sendo vestido ou carregado, a luz brilha a partir do objeto e se move com ele. Cobrir completamente o objeto afetado com um objeto opaco, como uma tigela ou um elmo, bloqueia a luz.\n\nSe qualquer parte da área desta magia se sobrepuser a uma área de escuridão criada por uma magia de 3º círculo ou inferior, a magia que criou a escuridão é dissipada.", en: "A 60-foot radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.\n\nIf you chose a point on an object you are holding or one that isn't being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.\n\nIf any of this spell's area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled." } },
  { id: 'feignDeath',             level: 3, school: 'necromancy',   classes: ['bard','cleric','druid','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', ritual: true, desc: { pt: "Você toca em uma criatura voluntária e a coloca em um estado cataléptico que é indistinguível da morte.\n\nPela duração da magia, ou até você usar uma ação para tocar o alvo e dissipar a magia, o alvo aparenta estar morto para qualquer inspeção externa e para magias usadas para determinar o estado do alvo. O alvo fica cego e incapacitado, e seu deslocamento cai para 0. O alvo tem resistência a todo tipo de dano, exceto dano psíquico. Se o alvo estiver doente ou envenenado quando você conjurar a magia, ou contrair uma doença ou veneno sob o efeito da magia, a doença e o veneno não têm efeito até a magia terminar.", en: "You touch a willing creature and put it into a cataleptic state that is indistinguishable from death.\n\nFor the spell’s duration, or until you use an action to touch the target and dismiss the spell, the target appears dead to all outward inspection and to spells used to determine the target’s status. The target is blinded and incapacitated, and its speed drops to 0. The target has resistance to all damage except psychic damage. If the target is diseased or poisoned when you cast the spell, or becomes diseased or poisoned while under the spell’s effect, the disease and poison have no effect until the spell ends." } },
  { id: 'hypnoticPattern',        level: 3, school: 'illusion',     classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '120 ft', components: 'S, M', duration: 'Conc. 1 min', desc: { pt: "Você cria um padrão ondulante de cores entrelaçadas pelo ar dentro de um cubo de 9 metros dentro do alcance. O padrão aparece por um instante e desaparece. Cada criatura na área que vir o padrão deve realizar um teste de resistência de Sabedoria. Em uma falha na salvaguarda, a criatura fica enfeitiçada pela duração. Enquanto estiver enfeitiçada por esta magia, a criatura fica incapacitada e tem deslocamento 0.\n\nA magia termina para uma criatura afetada se ela sofrer qualquer dano ou se outra pessoa usar uma ação para sacudir a criatura tirando-a do seu torpor.", en: "You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a Wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.\n\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor." } },
  { id: 'majorImage',             level: 3, school: 'illusion',     classes: ['bard','sorcerer','warlock','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você cria a imagem de um objeto, criatura ou algum outro fenômeno visível que não tenha mais de um cubo de 6 metros. A imagem aparece em um ponto que você possa ver dentro do alcance e perdura pela duração. Ela parece completamente real, incluindo sons, odores e temperatura apropriados para a coisa retratada. Você não pode criar calor ou frio suficientes para causar dano, um som alto o suficiente para causar dano trovejante ou ensurdecer uma criatura, ou um odor que cause náuseas a uma criatura (como o fedor de um troglodita).\n\nEnquanto estiver dentro do alcance da ilusão, você pode usar sua ação para fazer a imagem se mover para qualquer outro ponto dentro do alcance. Conforme a imagem muda de lugar, você pode alterar sua aparência para que seus movimentos pareçam naturais para a imagem. Por exemplo, se você criar a imagem de uma criatura e movê-la, pode alterar a imagem para que pareça estar caminhando. De forma semelhante, você pode fazer com que a ilusão emita sons diferentes em momentos diferentes, inclusive fazendo-a manter uma conversa, por exemplo.\n\nA interação física com a imagem revela que ela é uma ilusão, pois objetos passam através dela. Uma criatura que use sua ação para examinar a imagem pode determinar que ela é uma ilusão com um teste bem-sucedido de Inteligência (Investigação) contra a CD de resistência da sua magia. Se uma criatura discernir a ilusão pelo que ela realmente é, a criatura pode ver através da imagem e suas outras qualidades sensoriais tornam-se tênues para a criatura.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 6º círculo ou superior, a magia dura até ser dissipada, sem exigir sua concentração.", en: "You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte's stench).\n\nAs long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration." } },
  { id: 'meldIntoStone',          level: 3, school: 'transmutation', classes: ['cleric','druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '8 hours', ritual: true, desc: { pt: "Você entra em um objeto ou superfície de pedra grande o bastante para conter totalmente o seu corpo, fundindo a si mesmo e a todo o equipamento que carrega com a pedra pela duração. Usando seu deslocamento, você entra na pedra em um ponto que possa tocar. Nada da sua presença permanece visível ou detectável por sentidos não mágicos.\n\nEnquanto estiver fundido com a pedra, você não pode ver o que acontece do lado de fora, e quaisquer testes de Sabedoria (Percepção) que fizer para ouvir sons externos são feitos com desvantagem. Você permanece ciente da passagem do tempo e pode conjurar magias sobre si mesmo enquanto estiver fundido à pedra. Você pode usar seu deslocamento para sair da pedra no mesmo ponto em que entrou, o que encerra a magia. De outro modo, você não pode se mover.\n\nDano físico menor à pedra não machuca você, mas sua destruição parcial ou uma mudança em sua forma (na medida em que você não caiba mais dentro dela) expulsa você e lhe causa 6d6 de dano contundente. A destruição completa da pedra (ou sua transmutação em uma substância diferente) expulsa você e lhe causa 50 de dano contundente. Se for expelido, você cai no chão (caído) em um espaço desocupado mais próximo de onde entrou pela primeira vez.", en: "You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\n\nWhile merged with the stone, you can't see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can't move.\n\nMinor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered." } },
  { id: 'nondetection',           level: 3, school: 'abjuration',   classes: ['bard','ranger','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', desc: { pt: "Pela duração, você oculta um alvo que tocar de magias de Adivinhação. O alvo pode ser uma criatura voluntária, ou pode ser um local ou um objeto com no máximo 3 metros em qualquer dimensão. O alvo não pode ser alvo de nenhuma magia de Adivinhação nem ser percebido por meio de sensores mágicos de vidência.", en: "For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors." } },
  { id: 'plantGrowth',            level: 3, school: 'transmutation', classes: ['bard','druid','ranger'], castingTime: '1 action ou 8h', range: '150 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Esta magia canaliza vitalidade para plantas em uma área específica. Há dois usos possíveis para a magia, concedendo benefícios imediatos ou de longo prazo.\n\nSe conjurar esta magia usando 1 ação, escolha um ponto dentro do alcance. Todas as plantas normais em um raio de 30 metros centrado naquele ponto tornam-se espessas e crescem excessivamente. Uma criatura se movendo pela área deve gastar 4 metros de movimento para cada 1 metro que se mover.\n\nVocê pode excluir da área da magia uma ou mais áreas de qualquer tamanho para que não sejam afetadas.\n\nSe conjurar esta magia ao longo de 8 horas, você enriquece a terra. Todas as plantas em um raio de 750 metros centrado em um ponto dentro do alcance tornam-se enriquecidas por 1 ano. As plantas produzem o dobro da quantidade normal de alimento quando colhidas.", en: "This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.\n\nIf you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.\n\nYou can exclude one or more areas of any size within the spell's area from being affected.\n\nIf you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested." } },
  { id: 'protectionFromEnergy',   level: 3, school: 'abjuration',   classes: ['cleric','druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Pela duração, a criatura voluntária que você tocar tem Resistência a um tipo de dano à sua escolha: Ácido, Gélido, Ígneo, Elétrico ou Trovejante.", en: "For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder." } },
  { id: 'removeCurse',            level: 3, school: 'abjuration',   classes: ['cleric','paladin','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instant', desc: { pt: "Ao seu toque, todas as maldições que afetam uma criatura ou objeto terminam. Se o objeto for um item mágico amaldiçoado, sua maldição permanece, mas a magia rompe a Sintonização de seu dono com o objeto para que ele possa ser removido ou descartado.", en: "At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's attunement to the object so it can be removed or discarded." } },
  { id: 'sendingSpell',           level: 3, school: 'evocation',    classes: ['bard','cleric','wizard'], castingTime: '1 action', range: 'Unlimited', components: 'V, S, M', duration: '1 round', desc: { pt: "Você envia uma mensagem curta de vinte e cinco palavras ou menos a uma criatura com a qual tenha familiaridade. A criatura ouve a mensagem em sua mente, reconhece você como o remetente se o conhecer e pode responder de maneira semelhante imediatamente. A magia permite que criaturas com valor de Inteligência de pelo menos 1 compreendam o significado de sua mensagem.\n\nVocê pode enviar a mensagem através de qualquer distância e até mesmo para outros planos de existência, mas se o alvo estiver em um plano diferente do seu, há 5 por cento de chance de a mensagem não chegar.", en: "You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.\n\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn’t arrive." } },
  { id: 'slowSpell',              level: 3, school: 'transmutation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você altera o tempo ao redor de até seis criaturas à sua escolha em um cubo de 12 metros dentro do alcance. Cada alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou será afetado por esta magia pela duração.\n\nO deslocamento de um alvo afetado é reduzido pela metade, ele sofre uma penalidade de -2 na CA e em salvaguardas de Destreza, e não pode usar reações. No turno dele, ele pode usar uma ação ou uma ação bônus, não ambas. Independentemente das habilidades ou itens mágicos da criatura, ela não pode fazer mais de um ataque corpo a corpo ou à distância durante o turno dela.\n\nSe a criatura tentar conjurar uma magia com tempo de conjuração de 1 ação, role um d20. Em um 11 ou superior, a magia não entra em efeito até o próximo turno da criatura, e a criatura deve usar sua ação naquele turno para completar a magia. Se não puder, a magia é desperdiçada.\n\nUma criatura afetada por esta magia faz outra salvaguarda de Sabedoria no final de cada um dos turnos dela. Se obtiver sucesso na salvaguarda, o efeito se encerra para ela.", en: "You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a wisdom saving throw or be affected by this spell for the duration.\n\nAn affected target’s speed is halved, it takes a -2 penalty to AC and Dexterity saving throws, and it can’t use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature’s abilities or magic items, it can’t make more than one melee or ranged attack during its turn.\n\nIf the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn’t take effect until the creature’s next turn, and the creature must use its action on that turn to complete the spell. If it can’t, the spell is wasted.\n\nA creature affected by this spell makes another Wisdom saving throw at the end of each of its turns. On a successful save, the effect ends for it." } },
  { id: 'speakWithDead',          level: 3, school: 'necromancy',   classes: ['bard','cleric'], castingTime: '1 action', range: '10 ft', components: 'V, S, M', duration: '10 min', desc: { pt: "Você concede uma aparência de vida a um cadáver à sua escolha dentro do alcance, permitindo que ele responda às perguntas que você fizer. O cadáver deve ter uma boca, e esta magia falha se a criatura falecida era um Morto-Vivo quando morreu. A magia também falha se o cadáver tiver sido alvo desta magia nos últimos 10 dias.\nAté a magia terminar, você pode fazer até cinco perguntas ao cadáver. O cadáver sabe apenas o que sabia em vida, incluindo os idiomas que conhecia. As respostas costumam ser breves, enigmáticas ou repetitivas, e o cadáver não tem nenhuma obrigação de oferecer uma resposta verdadeira se você for hostil a ele ou se ele o reconhecer como um inimigo. Esta magia não devolve a alma da criatura ao corpo, apenas seu espírito animador. Assim, o cadáver não pode aprender novas informações, não compreende nada do que aconteceu desde sua morte e não pode especular sobre eventos futuros.", en: "You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can't be undead. The spell fails if the corpse was the target of this spell within the last 10 days.\n\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events." } },
  { id: 'speakWithPlants',        level: 3, school: 'transmutation', classes: ['bard','druid','ranger'], castingTime: '1 action', range: 'Self (30-ft radius)', components: 'V, S', duration: '10 min', desc: { pt: "Você imbui plantas a até 9 metros de você com senciência e capacidade de movimento limitadas, concedendo-lhes a habilidade de se comunicar com você e seguir seus comandos simples. Você pode interrogar as plantas sobre eventos na área da magia nas últimas vinte e quatro horas, obtendo informações sobre criaturas que passaram, clima e outras circunstâncias.\n\nVocê também pode transformar terreno difícil causado por crescimento de plantas (como matagais e vegetação rasteira) em terreno comum pela duração. Ou pode transformar terreno comum onde plantas estejam presentes em terreno difícil pela duração, fazendo com que videiras e galhos atrapalhem perseguidores, por exemplo.\n\nPlantas podem ser capazes de realizar outras tarefas em seu favor, a critério do Mestre. A magia não permite que plantas se desenraizem e se desloquem de um lugar para outro, mas elas podem mover livremente galhos, gavinhas e caules.\n\nSe uma criatura do tipo planta estiver na área, você poderá se comunicar com ela como se compartilhassem um idioma comum, mas não adquire nenhuma habilidade mágica de influenciá-la.\n\nEsta magia pode fazer com que as plantas criadas pela magia constrição libertem uma criatura impedida.", en: "You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\n\nYou can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.\n\nPlants might be able to perform other tasks on your behalf, at the GM's discretion. The spell doesn't enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.\n\nIf a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.\n\nThis spell can cause the plants created by the entangle spell to release a restrained creature." } },
  { id: 'stinkingCloud',          level: 3, school: 'conjuration',  classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '90 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você cria uma esfera de 6 metros de raio de gás amarelo e nauseante centrada em um ponto dentro do alcance. A nuvem se espalha dobrando esquinas, e sua área fica fortemente obscurecida. A nuvem paira no ar pela duração.\n\nCada criatura totalmente dentro da nuvem no início do turno dela deve realizar um teste de resistência de Constituição contra veneno. Em caso de falha no teste, a criatura passa sua ação naquele turno engasgando e cambaleando. Criaturas que não precisam respirar ou que sejam imunes a veneno obtêm sucesso automático nesse teste de resistência.\n\nUm vento moderado (pelo menos 15 quilômetros por hora) dispersa a nuvem após 4 rodadas. Um vento forte (pelo menos 30 quilômetros por hora) dispersa a nuvem após 1 rodada.", en: "You create a 20-foot radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.\n\nEach creature that is completely within the cloud at the start of its turn must make a Constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don't need to breathe or are immune to poison automatically succeed on this saving throw.\n\nA moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round." } },
  { id: 'waterBreathing',         level: 3, school: 'transmutation', classes: ['druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '24 hours', ritual: true, desc: { pt: "Esta magia concede a até dez criaturas voluntárias à sua escolha dentro do alcance a capacidade de respirar debaixo d'água até a magia terminar. As criaturas afetadas também mantêm seu modo normal de respiração.", en: "This spell grants up to ten willing creatures you can see within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration." } },
  { id: 'waterWalk',              level: 3, school: 'transmutation', classes: ['cleric','druid','ranger','sorcerer'], castingTime: '1 action', range: '30 ft', components: 'V, S, M', duration: '1 hour', ritual: true, desc: { pt: "Esta magia concede a habilidade de se mover sobre qualquer superfície líquida — como água, ácido, lama, neve, areia movediça ou lava — como se fosse chão sólido e inofensivo (criaturas atravessando lava incandescente ainda podem sofrer dano pelo calor). Até dez criaturas voluntárias que você possa ver dentro do alcance adquirem essa habilidade pela duração.\n\nSe você mirar em uma criatura submersa em um líquido, a magia carrega o alvo até a superfície do líquido a uma taxa de 18 metros por rodada.", en: "This spell grants the ability to move across any liquid surface-such as water, acid, mud, snow, quicksand, or lava-as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.\n\nIf you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round." } },
  { id: 'windWall',               level: 3, school: 'evocation',    classes: ['druid','ranger'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Uma muralha de vento forte ergue-se do chão em um ponto que você escolher dentro do alcance. Você pode fazer a muralha ter até 15 metros de comprimento, 4,5 metros de altura e 30 centímetros de espessura. Você pode moldar a muralha de qualquer maneira que escolher, desde que forme um trajeto contínuo ao longo do solo. A muralha dura pela duração.\n\nQuando a muralha surge, cada criatura dentro da área dela deve realizar um teste de resistência de Força. Uma criatura sofre 3d8 de dano contundente em caso de falha no teste, ou metade desse dano em caso de sucesso.\n\nO vento forte mantém névoa, fumaça e outros gases afastados. Criaturas voadoras ou objetos de tamanho Pequeno ou menor não podem atravessar a muralha. Materiais leves e soltos levados para dentro da muralha voam para cima. Flechas, virotes e outros projéteis comuns lançados contra alvos atrás da muralha são desviados para cima e erram automaticamente. (Pedregulhos arremessados por gigantes ou armas de cerco, e projéteis semelhantes, não são afetados.) Criaturas em forma gasosa não podem atravessar a muralha.", en: "A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a Strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can't pass through it." } },

  // === LEVEL 4 ADICIONAIS ===
  { id: 'blight',                 level: 4, school: 'necromancy',   classes: ['druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Instant', desc: { pt: "Energia necromântica banha uma criatura à sua escolha que você possa ver dentro do alcance, drenando umidade e vitalidade dela. O alvo deve fazer uma salvaguarda de Constituição. O alvo sofre 8d8 de dano necrótico em uma salvaguarda fracassada, ou metade desse dano em uma bem-sucedida. Esta magia não tem efeito sobre mortos-vivos ou constructos.\n\nSe você escolher uma criatura planta ou uma planta mágica como alvo, ela faz a salvaguarda com desvantagem e a magia causa dano máximo a ela.\n\nSe você escolher como alvo uma planta não mágica que não seja uma criatura, como uma árvore ou arbusto, ela não faz salvaguarda; ela simplesmente murcha e morre.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 4º.", en: "Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a Constitution saving throw. The target takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. This spell has no effect on undead or constructs.\n\nIf you target a plant creature or a magical plant, it makes the saving throw with disadvantage, and the spell deals maximum damage to it.\n\nIf you target a nonmagical plant that isn't a creature, such as a tree or shrub, it doesn't make a saving throw; it simply withers and dies.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th." } },
  { id: 'confusion',              level: 4, school: 'enchantment',  classes: ['bard','druid','sorcerer','wizard'], castingTime: '1 action', range: '90 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Esta magia assalta e distorce a mente das criaturas, gerando delírios e provocando ações descontroladas. Cada criatura em uma esfera com 3 metros de raio centrada em um ponto à sua escolha dentro do alcance deve ser bem-sucedida em uma salvaguarda de Sabedoria quando você conjurar esta magia ou será afetada por ela.\n\nUm alvo afetado não pode realizar reações e deve rolar um d10 no início de cada um dos seus turnos para determinar seu comportamento naquele turno.\n\nTabela: Comportamento da Confusão\n\n| d10 | Comportamento |\n|---|---|\n| 1 | A criatura usa todo o seu deslocamento para se mover em uma direção aleatória. Para determinar a direção, role um d8 e atribua uma direção a cada face do dado. A criatura não realiza uma ação neste turno. |\n| 2-6 | A criatura não se move nem realiza ações neste turno. |\n| 7-8 | A criatura usa sua ação para fazer um ataque corpo a corpo contra uma criatura determinada aleatoriamente dentro do seu alcance. Se não houver criatura dentro do seu alcance, ela não faz nada neste turno. |\n| 9-10 | A criatura pode agir e se mover normalmente. |\n| | |\n\nNo final de cada um dos turnos dele, um alvo afetado pode fazer uma salvaguarda de Sabedoria. Se for bem-sucedido, este efeito termina para aquele alvo.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o raio da esfera aumenta em 1,5 metro para cada círculo do espaço acima do 4º.", en: "This spell assaults and twists creatures' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.\n\nAn affected target can't take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.\n\nTable- Confusion Behavior\n\n| d10 | Behavior                                                                                            |\n|------|-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| 1  | The creature uses all its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face. The creature doesn't take an action this turn. |\n| 2-6 | The creature doesn't move or take actions this turn.                                                                      |\n| 7-8 | The creature uses its action to make a melee attack against a randomly determined creature within its reach. If there is no creature within its reach, the creature does nothing this turn.   |\n| 9-10 | The creature can act and move normally.                                                                             |\n|   |                                                                                                 |\n\nAt the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th." } },
  { id: 'conjureMinorElementals', level: 4, school: 'conjuration',  classes: ['druid','wizard'], castingTime: '1 min', range: '90 ft', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Você conjura elementais que surgem em espaços desocupados que você possa ver dentro do alcance. Você escolhe uma das seguintes opções para o que aparece:\n\n- Um elemental de nível de desafio 2 ou inferior\n- Dois elementais de nível de desafio 1 ou inferior\n- Quatro elementais de nível de desafio 1/2 ou inferior\n- Oito elementais de nível de desafio 1/4 ou inferior\n\nUm elemental conjurado por esta magia desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nAs criaturas conjuradas são amigáveis a você e aos seus companheiros. Role iniciativa para as criaturas conjuradas como um grupo, que possui seus próprios turnos. Elas obedecem a quaisquer comandos verbais que você emitir para elas (nenhuma ação exigida de você). Se você não emitir comandos para elas, elas se defendem de criaturas hostis, mas de outro modo não realizam ações.\n\nO Mestre tem as estatísticas das criaturas.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima, e mais criaturas aparecem: o dobro com um espaço de 6º círculo e o triplo com um espaço de 8º círculo.", en: "You summon elementals that appear in unoccupied spaces that you can see within range. You choose one the following options for what appears:\n\n- One elemental of challenge rating 2 or lower\n- Two elementals of challenge rating 1 or lower\n- Four elementals of challenge rating 1/2 or lower\n- Eight elementals of challenge rating 1/4 or lower\n\nAn elemental summoned by this spell disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.\n\nAt Higher Levels. When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot." } },
  { id: 'conjureWoodlandBeings',  level: 4, school: 'conjuration',  classes: ['druid','ranger'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Você conjura criaturas feéricas que surgem em espaços desocupados que você possa ver dentro do alcance. Escolha uma das seguintes opções para o que aparece:\n\n- Uma criatura feérica de nível de desafio 2 ou inferior\n- Duas criaturas feéricas de nível de desafio 1 ou inferior\n- Quatro criaturas feéricas de nível de desafio 1/2 ou inferior\n- Oito criaturas feéricas de nível de desafio 1/4 ou inferior\n\nUma criatura conjurada desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nAs criaturas conjuradas são amigáveis a você e aos seus companheiros. Role iniciativa para as criaturas conjuradas como um grupo, que possui seus próprios turnos. Elas obedecem a quaisquer comandos verbais que você emitir para elas (nenhuma ação exigida de você). Se você não emitir nenhum comando para elas, elas se defendem de criaturas hostis, mas de outro modo não realizam ações.\n\nO Mestre tem as estatísticas das criaturas.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando certos espaços de magia superiores, você escolhe uma das opções de invocação acima, e mais criaturas aparecem: o dobro com um espaço de 6º círculo e o triplo com um espaço de 8º círculo.", en: "You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One fey creature of challenge rating 2 or lower\n- Two fey creatures of challenge rating 1 or lower\n- Four fey creatures of challenge rating 1/2 or lower\n- Eight fey creatures of challenge rating 1/4 or lower\n\nA summoned creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which have their own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.\n\nAt Higher Levels. When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot." } },
  { id: 'controlWater',           level: 4, school: 'transmutation', classes: ['cleric','druid','wizard'], castingTime: '1 action', range: '300 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Até a magia terminar, você controla qualquer água livre dentro de uma área à sua escolha que seja um cubo de até 30 metros de lado. Você pode escolher qualquer um dos seguintes efeitos quando conjurar esta magia. Como uma ação em seu turno, você pode repetir o mesmo efeito ou escolher um diferente.\n\nInundar. Você faz com que o nível da água de toda a água parada na área suba em até 6 metros. Se a área incluir uma margem, a água da enchente transborda para a terra seca.\n\nSe você escolher uma área em um grande corpo d'água, você cria, em vez disso, uma onda de 6 metros de altura que se desloca de um lado da área para o outro e então quebra. Quaisquer veículos Enormes ou menores no caminho da onda são carregados com ela até o outro lado. Quaisquer veículos Enormes ou menores atingidos pela onda têm 25 por cento de chance de virar.\n\nO nível da água permanece elevado até a magia terminar ou você escolher um efeito diferente. Se este efeito produziu uma onda, a onda se repete no início do seu próximo turno enquanto o efeito de inundação durar.\n\nSeparar Água. Você faz a água na área se afastar e criar uma trincheira. A trincheira se estende através da área da magia, e a água separada forma uma parede em ambos os lados. A trincheira permanece até a magia terminar ou você escolher um efeito diferente. A água então preenche lentamente a trincheira ao longo da rodada seguinte até que o nível normal de água seja restaurado.\n\nRedirecionar Fluxo. Você faz com que a água corrente na área se mova em uma direção à sua escolha, mesmo que a água tenha que fluir sobre obstáculos, subir paredes ou em outras direções improváveis. A água na área se move conforme você a direciona, mas quando sai além da área da magia, ela retoma seu fluxo com base nas condições do terreno. A água continua a se mover na direção que você escolheu até a magia terminar ou você escolher um efeito diferente.\n\nRedemoinho. Este efeito requer um corpo d'água de pelo menos 15 metros quadrados e 7,5 metros de profundidade. Você faz um redemoinho se formar no centro da área. O redemoinho forma um vórtice com 1,5 metro de largura na base, até 15 metros de largura no topo e 7,5 metros de altura. Qualquer criatura ou objeto na água e a até 7,5 metros do vórtice é puxado 3 metros em direção a ele. Uma criatura pode nadar para longe do vórtice realizando um teste de Força (Atletismo) contra a CD de salvaguarda da sua magia.\n\nQuando uma criatura entrar no vórtice pela primeira vez em um turno ou começar seu turno nele, ela deve fazer uma salvaguarda de Força. Em uma salvaguarda fracassada, a criatura sofre 2d8 de dano contundente e fica presa no vórtice até a magia terminar. Em uma salvaguarda bem-sucedida, a criatura sofre metade do dano e não fica presa no vórtice. Uma criatura presa no vórtice pode usar sua ação para tentar nadar para longe do vórtice conforme descrito acima, mas tem desvantagem no teste de Força (Atletismo) para fazê-lo.\n\nNa primeira vez em cada turno que um objeto entrar no vórtice, o objeto sofre 2d8 de dano contundente; este dano ocorre a cada rodada em que ele permanecer no vórtice.", en: "Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one.\n\nFlood. You cause the water level of all standing water in the area to rise by as much as 20 feet. If the area includes a shore, the flooding water spills over onto dry land.\n\nIf you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes down. Any Huge or smaller vehicles in the wave's path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\n\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\n\nPart Water. You cause water in the area to move apart and create a trench. The trench extends across the spell's area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\n\nRedirect Flow. You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell's area, it resumes its flow based on the terrain conditions. The water continues to move in the direction you chose until the spell ends or you choose a different effect.\n\nWhirlpool. This effect requires a body of water at least 50 feet square and 25 feet deep. You cause a whirlpool to form in the center of the area. The whirlpool forms a vortex that is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature or object in the water and within 25 feet of the vortex is pulled 10 feet toward it. A creature can swim away from the vortex by making a Strength (Athletics) check against your spell save DC.\n\nWhen a creature enters the vortex for the first time on a turn or starts its turn there, it must make a Strength saving throw. On a failed save, the creature takes 2d8 bludgeoning damage and is caught in the vortex until the spell ends. On a successful save, the creature takes half damage, and isn't caught in the vortex. A creature caught in the vortex can use its action to try to swim away from the vortex as described above, but has disadvantage on the Strength (Athletics) check to do so.\n\nThe first time each turn that an object enters the vortex, the object takes 2d8 bludgeoning damage; this damage occurs each round it remains in the vortex." } },
  { id: 'deathWard',              level: 4, school: 'abjuration',   classes: ['cleric','paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '8 hours', desc: { pt: "Você toca uma criatura e concede a ela uma medida de proteção contra a morte.\n\nNa primeira vez em que o alvo for cair a 0 Pontos de Vida como resultado de sofrer dano, o alvo cai, em vez disso, a 1 Ponto de Vida, e a magia termina.\n\nSe a magia ainda estiver ativa quando o alvo for submetido a um efeito que o mataria instantaneamente sem causar dano, esse efeito é anulado contra o alvo, e a magia termina.", en: "You touch a creature and grant it a measure of protection from death.\n\nThe first time the target would drop to 0 hit points as a result of taking damage, the target instead drops to 1 hit point, and the spell ends.\n\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends." } },
  { id: 'dominateBeast',          level: 4, school: 'enchantment',  classes: ['druid','ranger','sorcerer'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você tenta seduzir e dominar uma besta que você possa ver dentro do alcance. Ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará enfeitiçada por você pela duração. Se você ou criaturas que sejam amistosas com você estiverem lutando contra ela, ela tem vantagem na salvaguarda.\n\nEnquanto a besta estiver enfeitiçada, você mantém um elo telepático com ela desde que ambos estejam no mesmo plano de existência. Você pode usar esse elo telepático para emitir comandos para a criatura enquanto você estiver consciente (nenhuma ação exigida), os quais ela faz o melhor para obedecer. Você pode especificar um curso de ação simples e geral, como \"Ataque aquela criatura\", \"Corra até ali\" ou \"Busque aquele objeto\". Se a criatura completar a ordem e não receber mais orientações suas, ela defende e preserva a si mesma da melhor forma que puder.\n\nVocê pode usar sua ação para assumir controle total e preciso do alvo. Até o final do seu próximo turno, a criatura realiza apenas as ações que você escolher, e não faz nada que você não permita. Durante esse período, você também pode fazer com que a criatura use uma reação, mas isso requer que você use sua própria reação também.\n\nCada vez que o alvo sofrer dano, ele faz uma nova salvaguarda de Sabedoria contra a magia. Se a salvaguarda for bem-sucedida, a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia com um espaço de magia de 5º círculo, a duração é concentração, até 10 minutos. Quando você usar um espaço de magia de 6º círculo, a duração é concentração, até 1 hora. Quando você usar um espaço de magia de 7º círculo ou superior, a duração é concentração, até 8 horas.", en: "You attempt to beguile a beast that you can see within range. It must succeed on a Wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the beast is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new Wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.\n\nAt Higher Levels. When you cast this spell with a 5th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 6th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 7th level or higher, the duration is concentration, up to 8 hours." } },
  { id: 'freedomOfMovement',      level: 4, school: 'abjuration',   classes: ['bard','cleric','druid','ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', desc: { pt: "Você toca uma criatura voluntária. Pela duração, o movimento do alvo não é afetado por terreno difícil, e magias e outros efeitos mágicos não podem reduzir o deslocamento do alvo nem fazer com que o alvo fique paralisado ou impedido.\n\nO alvo também pode gastar 1,5 metro de deslocamento para escapar automaticamente de restrições não mágicas, como algemas ou uma criatura que o tenha agarrado. Por fim, estar submerso não impõe penalidades ao movimento ou aos ataques do alvo.", en: "You touch a willing creature. For the duration, the target's movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target's speed nor cause the target to be paralyzed or restrained.\n\nThe target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled. Finally, being underwater imposes no penalties on the target's movement or attacks." } },
  { id: 'giantInsect',            level: 4, school: 'transmutation', classes: ['druid'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Conc. 10 min', desc: { pt: "Você transforma até dez centopeias, três aranhas, cinco vespas ou um escorpião dentro do alcance em versões gigantes de suas formas naturais pela duração. Uma centopeia se torna uma centopeia gigante, uma aranha se torna uma aranha gigante, uma vespa se torna uma vespa gigante e um escorpião se torna um escorpião gigante.\n\nCada criatura obedece aos seus comandos verbais e, em combate, elas agem no seu turno a cada rodada. O Mestre possui as estatísticas para essas criaturas e resolve suas ações e deslocamento.\n\nUma criatura permanece em seu tamanho gigante pela duração, até ser reduzida a 0 pontos de vida ou até você usar uma ação para dispensar o efeito sobre ela.\n\nO Mestre pode permitir que você escolha alvos diferentes. Por exemplo, se você transformar uma abelha, a versão gigante dela pode ter as mesmas estatísticas de uma vespa gigante.", en: "You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion.\n\nEach creature obeys your verbal commands, and in combat, they act on your turn each round. The GM has the statistics for these creatures and resolves their actions and movement.\n\nA creature remains in its giant size for the duration, until it drops to 0 hit points, or until you use an action to dismiss the effect on it.\n\nThe GM might allow you to choose different targets. For example, if you transform a bee, its giant version might have the same statistics as a giant wasp." } },
  { id: 'graspingVine',           level: 4, school: 'conjuration',  classes: ['druid','ranger'], castingTime: '1 bonus action', range: '30 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você conjura uma videira que brota do chão em um espaço desocupado à sua escolha que você possa ver dentro do alcance. Quando você conjura esta magia, você pode direcionar a videira para fustigar uma criatura a até 9 metros dela que você possa ver. Essa criatura deve ser bem-sucedida em uma salvaguarda de Destreza ou será puxada 6 metros diretamente em direção à videira.\n\nAté a magia terminar, você pode direcionar a videira para fustigar a mesma criatura ou outra criatura como uma ação bônus em cada um dos seus turnos.", en: "You conjure a vine that sprouts from the ground in an unoccupied space of your choice that you can see within range. When you cast this spell, you can direct the vine to lash out at a creature within 30 feet of it that you can see. That creature must succeed on a Dexterity saving throw or be pulled 20 feet directly toward the vine.\n\nUntil the spell ends, you can direct the vine to lash out at the same creature or another one as a bonus action on each of your turns." } },
  { id: 'hallucinatoryTerrain',   level: 4, school: 'illusion',     classes: ['bard','druid','warlock','wizard'], castingTime: '10 min', range: '300 ft', components: 'V, S, M', duration: '24 hours', desc: { pt: "Você faz com que o terreno natural em um Cubo de 45 metros dentro do alcance pareça, soe e cheire como outro tipo de terreno natural. Assim, campos abertos ou uma estrada podem parecer um pântano, uma colina, uma fenda ou algum outro terreno difícil ou intransponível. Um lago pode parecer uma campina gramada, um precipício pode parecer uma encosta suave, e uma ravina cheia de pedras pode parecer uma estrada larga e lisa. Estruturas construídas, equipamentos e criaturas dentro da área não são alterados.\nAs características táteis do terreno não mudam, então criaturas que entrem na área provavelmente perceberão a ilusão. Se a diferença não for óbvia ao toque, uma criatura que examine a ilusão pode realizar a ação Estudar para fazer um teste de Inteligência (Investigação) contra a CD de resistência da sua magia para desacreditá-la. Se uma criatura discernir que o terreno é ilusório, ela vê uma imagem vaga sobreposta ao terreno real.", en: "You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren't changed in appearance.\n\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn't obvious by touch, a creature carefully examining the illusion can attempt an Intelligence (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is, sees it as a vague image superimposed on the terrain." } },
  { id: 'locateCreature',         level: 4, school: 'divination',   classes: ['bard','cleric','druid','paladin','ranger','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Descreva ou nomeie uma criatura que lhe seja familiar. Você sente a direção da localização da criatura, desde que ela esteja a até 300 metros de você. Se a criatura estiver se movendo, você sabe a direção de seu movimento.\n\nA magia pode localizar uma criatura específica conhecida por você ou a criatura mais próxima de um tipo específico (como um humano ou um unicórnio), desde que você já tenha visto tal criatura de perto — a até 9 metros — pelo menos uma vez. Se a criatura que você descreveu ou nomeou estiver em uma forma diferente, como estando sob os efeitos de uma magia metamorfose, esta magia não a localiza.\n\nEsta magia não pode localizar uma criatura se água corrente de pelo menos 3 metros de largura bloquear o caminho direto entre você e ela.", en: "Describe or name a creature that is familiar to you. You sense the direction to the creature's location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.\n\nThe spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn), so long as you have seen such a creature up close-within 30 feet-at least once. If the creature you described or named is in a different form, such as being under the effects of a polymorph spell, this spell doesn't locate the creature.\n\nThis spell can't locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature." } },
  { id: 'stoneShape',             level: 4, school: 'transmutation', classes: ['cleric','druid','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você toca um objeto de pedra de tamanho Médio ou menor ou uma seção de pedra com até 1,5 metro em qualquer dimensão e o molda em qualquer formato que atenda ao seu propósito. Assim, por exemplo, você pode moldar uma rocha grande em uma arma, ídolo ou cofre, ou abrir uma pequena passagem através de uma parede, contanto que a parede tenha menos de 1,5 metro de espessura. Você também pode moldar uma porta de pedra ou seu batente para selar a porta. O objeto criado pode ter até duas dobradiças e uma tranca, mas detalhes mecânicos mais refinados não são possíveis.", en: "You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn't possible." } },
  { id: 'stoneskin',              level: 4, school: 'abjuration',   classes: ['druid','ranger','sorcerer','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Esta magia torna a carne de uma criatura voluntária que você tocar tão dura quanto a pedra. Até a magia terminar, o alvo tem resistência a dano contundente, perfurante e cortante de armas não mágicas.", en: "This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage." } },

  // === LEVEL 5 ADICIONAIS ===
  { id: 'antilifeShell',          level: 5, school: 'abjuration',   classes: ['druid'], castingTime: '1 action', range: 'Self (10-ft radius)', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Uma barreira cintilante se estende a partir de você em um raio de 3 metros e se move com você, permanecendo centrada em você e mantendo afastadas criaturas exceto mortos-vivos e constructos. A barreira dura pela duração.\n\nA barreira impede que uma criatura afetada atravesse ou alcance através dela. Uma criatura afetada pode conjurar magias ou fazer ataques com armas à distância ou com alcance através da barreira.\n\nSe você se mover de forma que uma criatura afetada seja forçada a atravessar a barreira, a magia termina.", en: "A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration.\n\nThe barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier.\n\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends." } },
  { id: 'awaken',                 level: 5, school: 'transmutation', classes: ['bard','druid'], castingTime: '8 hours', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Após passar o tempo de conjuração traçando caminhos mágicos dentro de uma pedra preciosa, você toca uma besta ou planta Enorme ou menor. O alvo não deve ter valor de Inteligência ou deve ter Inteligência 3 ou menor. O alvo ganha uma Inteligência de 10. O alvo também ganha a habilidade de falar um idioma que você conheça. Se o alvo for uma planta, ele ganha a habilidade de mover seus membros, raízes, vinhas, trepadeiras e assim por diante, e ganha sentidos semelhantes aos de um humano. O Mestre escolhe as estatísticas apropriadas para a planta desperta, como as estatísticas do arbusto desperto ou da árvore desperta.\n\nA besta ou planta desperta fica enfeitiçada por você por 30 dias ou até que você ou seus companheiros façam qualquer coisa prejudicial a ela. Quando a condição enfeitiçado terminar, a criatura desperta escolhe se permanece amistosa com você, com base em como você a tratou enquanto esteve enfeitiçada.", en: "After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10. The target also gains the ability to speak one language you know. If the target is a plant, it gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human's. Your GM chooses statistics appropriate for the awakened plant, such as the statistics for the awakened shrub or the awakened tree.\n\nThe awakened beast or plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you, based on how you treated it while it was charmed." } },
  { id: 'communeWithNature',      level: 5, school: 'divination',   classes: ['druid','ranger'], castingTime: '1 min', range: 'Self', components: 'V, S', duration: 'Instant', ritual: true, desc: { pt: "Você brevemente se torna um com a natureza e ganha conhecimento sobre o território circundante. Ao ar livre, a magia concede a você conhecimento da terra dentro de 4,5 quilômetros de você. Em cavernas e outros ambientes subterrâneos naturais, o raio é limitado a 90 metros. A magia não funciona onde a natureza foi substituída por construções, como em masmorras e cidades.\n\nVocê adquire instantaneamente conhecimento de até três fatos à sua escolha sobre qualquer um dos seguintes assuntos no que se refere à área:\n\n- terreno e corpos d'água\n- plantas, minerais, animais ou povos predominantes\n- celestiais, fadas, ínferos, elementais ou mortos-vivos poderosos\n- influência de outros planos de existência\n- edifícios e construções\n\nPor exemplo, você poderia determinar a localização de mortos-vivos poderosos na área, a localização das principais fontes de água potável segura e a localização de quaisquer cidades próximas.", en: "You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn't function where nature has been replaced by construction, such as in dungeons and towns.\n\nYou instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area:\n\n- terrain and bodies of water\n- prevalent plants, minerals, animals, or peoples\n- powerful celestials, fey, fiends, elementals, or undead\n- influence from other planes of existence\n- buildings\n\nFor example, you could determine the location of powerful undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns." } },
  { id: 'conjureElemental',       level: 5, school: 'conjuration',  classes: ['druid','wizard'], castingTime: '1 min', range: '90 ft', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Você convoca um servo elemental. Escolha uma área de ar, terra, fogo ou água que preencha um cubo de 3 metros dentro do alcance. Um elemental de nível de desafio 5 ou inferior apropriado para a área que você escolheu surge em um espaço desocupado a até 3 metros dela. Por exemplo, um elemental do fogo surge de uma fogueira e um elemental da terra se ergue do solo. O elemental desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nO elemental é amigável a você e aos seus companheiros pela duração. Role iniciativa para o elemental, que possui seus próprios turnos. Ele obedece a quaisquer comandos verbais que você emitir para ele (nenhuma ação exigida de você). Se você não emitir nenhum comando para o elemental, ele se defende de criaturas hostis, mas de outro modo não realiza ações.\n\nSe a sua concentração for quebrada, o elemental não desaparece. Em vez disso, você perde o controle do elemental, ele se torna hostil em relação a você e aos seus companheiros e pode atacar. Um elemental descontrolado não pode ser dispensado por você e desaparece 1 hora após ter sido conjurado.\n\nO Mestre tem as estatísticas do elemental.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o nível de desafio aumenta em 1 para cada círculo do espaço acima do 5º.", en: "You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.\n\nThe elemental is friendly to you and your companions for the duration. Roll initiative for the elemental, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the elemental, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the elemental doesn't disappear. Instead, you lose control of the elemental, it becomes hostile toward you and your companions, and it might attack. An uncontrolled elemental can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the elemental's statistics.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th." } },
  { id: 'contagion',              level: 5, school: 'necromancy',   classes: ['cleric','druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '7 days', desc: { pt: "Seu toque inflige doenças. Faça um ataque corpo a corpo com magia contra uma criatura dentro do seu alcance. Se atingir, o alvo fica envenenado.\n\nNo final de cada um dos turnos do alvo envenenado, ele deve fazer uma salvaguarda de Constituição. Se o alvo for bem-sucedido em três dessas salvaguardas, ele não fica mais envenenado e a magia termina. Se o alvo falhar em três dessas salvaguardas, ele não fica mais envenenado, mas escolha uma das doenças abaixo. O alvo fica sujeito à doença escolhida pela duração da magia.\n\nUma vez que esta magia induz uma doença natural em seu alvo, qualquer efeito que remova uma doença ou de outro modo amenize os efeitos de uma doença se aplica a ela.\n\nDoença Cegante. Uma dor violenta toma conta da mente da criatura e seus olhos se tornam branco-leitosos. A criatura tem desvantagem em testes de Sabedoria e salvaguardas de Sabedoria e fica cega.\n\nFebre da Sujeira. Uma febre violenta varre o corpo da criatura. A criatura tem desvantagem em testes de Força, salvaguardas de Força e jogadas de ataque que usem Força.\n\nPodridão da Carne. A carne da criatura se decompõe. A criatura tem desvantagem em testes de Carisma e vulnerabilidade a todos os tipos de dano.\n\nFebre Cerebral. A mente da criatura fica febril. A criatura tem desvantagem em testes de Inteligência e salvaguardas de Inteligência, e a criatura se comporta como se estivesse sob os efeitos da magia confusão durante o combate.\n\nConvulsões. A criatura é tomada por tremores incontroláveis. A criatura tem desvantagem em testes de Destreza, salvaguardas de Destreza e jogadas de ataque que usem Destreza.\n\nDestino Viscoso. A criatura começa a sangrar incontrolavelmente. A criatura tem desvantagem em testes de Constituição e salvaguardas de Constituição. Além disso, sempre que a criatura sofrer dano, ela fica atordoada até o final do próximo turno dela.", en: "Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, the target is poisoned.\n\nAt the end of each of the poisoned target's turns, the target must make a Constitution saving throw. If the target succeeds on three of these saves, it is no longer poisoned, and the spell ends. If the target fails three of these saves, the target is no longer poisoned, but choose one of the diseases below. The target is subjected to the chosen disease for the spell's duration.\n\nSince this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease's effects apply to it.\n\nBlinding Sickness. Pain grips the creature's mind, and its eyes turn milky white. The creature has disadvantage on Wisdom checks and Wisdom saving throws and is blinded.\n\nFilth Fever. A raging fever sweeps through the creature's body. The creature has disadvantage on Strength checks, Strength saving throws, and attack rolls that use Strength.\n\nFlesh Rot. The creature's flesh decays. The creature has disadvantage on Charisma checks and vulnerability to all damage.\n\nMindfire. The creature's mind becomes feverish. The creature has disadvantage on Intelligence checks and Intelligence saving throws, and the creature behaves as if under the effects of the confusion spell during combat.\n\nSeizure. The creature is overcome with shaking. The creature has disadvantage on Dexterity checks, Dexterity saving throws, and attack rolls that use Dexterity.\n\nSlimy Doom. The creature begins to bleed uncontrollably. The creature has disadvantage on Constitution checks and Constitution saving throws. In addition, whenever the creature takes damage, it is stunned until the end of its next turn." } },
  { id: 'dominatePerson',         level: 5, school: 'enchantment',  classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você tenta seduzir e dominar um humanoide que você possa ver dentro do alcance. Ele deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará enfeitiçado por você pela duração. Se você ou criaturas que sejam amistosas com você estiverem lutando contra ele, ele tem vantagem na salvaguarda.\n\nEnquanto o alvo estiver enfeitiçado, você mantém um elo telepático com ele desde que ambos estejam no mesmo plano de existência. Você pode usar esse elo telepático para emitir comandos para a criatura enquanto você estiver consciente (nenhuma ação exigida), os quais ela faz o melhor para obedecer. Você pode especificar um curso de ação simples e geral, como \"Ataque aquela criatura\", \"Corra até ali\" ou \"Busque aquele objeto\". Se a criatura completar a ordem e não receber mais orientações suas, ela defende e preserva a si mesma da melhor forma que puder.\n\nVocê pode usar sua ação para assumir controle total e preciso do alvo. Até o final do seu próximo turno, a criatura realiza apenas as ações que você escolher, e não faz nada que você não permita. Durante esse período, você também pode fazer com que a criatura use uma reação, mas isso requer que você use sua própria reação também.\n\nCada vez que o alvo sofrer dano, ele faz uma nova salvaguarda de Sabedoria contra a magia. Se a salvaguarda for bem-sucedida, a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo, a duração é concentração, até 10 minutos. Quando você usar um espaço de magia de 7º círculo, a duração é concentração, até 1 hora. Quando você usar um espaço de magia de 8º círculo ou superior, a duração é concentração, até 8 horas.", en: "You attempt to beguile a humanoid that you can see within range. It must succeed on a Wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the target is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new Wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.\n\nAt Higher Levels. When you cast this spell using a 6th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 7th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 8 hours." } },
  { id: 'geas',                   level: 5, school: 'enchantment',  classes: ['bard','cleric','druid','paladin','wizard'], castingTime: '1 min', range: '60 ft', components: 'V', duration: '30 days', desc: { pt: "Você impõe um comando mágico a uma criatura que possa ver dentro do alcance, forçando-a a realizar algum serviço ou abster-se de alguma ação ou curso de atividade conforme você decidir. Se a criatura puder compreendê-lo, ela deve ser bem-sucedida em um teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração. Enquanto a criatura estiver enfeitiçada por você, ela sofre 5d10 de dano psíquico cada vez que agir de maneira diretamente contrária às suas instruções, mas não mais de uma vez a cada dia. Uma criatura que não possa compreendê-lo não é afetada pela magia.\n\nVocê pode emitir qualquer comando que escolher, exceto uma atividade que resulte em morte certa. Se você emitir um comando suicida, a magia termina.\n\nVocê pode encerrar a magia prematuramente usando uma ação para dispensá-la. Uma magia remover maldição, restauração maior ou desejo também a encerra.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 7º ou 8º círculo, a duração é de 1 ano. Quando você conjura esta magia usando um espaço de magia de 9º círculo, a magia dura até ser encerrada por uma das magias mencionadas acima.", en: "You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a Wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can't understand you is unaffected by the spell.\n\nYou can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends.\n\nYou can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th or 8th level, the duration is 1 year. When you cast this spell using a spell slot of 9th level, the spell lasts until it is ended by one of the spells mentioned above." } },
  { id: 'insectPlague',           level: 5, school: 'conjuration',  classes: ['cleric','druid','sorcerer'], castingTime: '1 action', range: '300 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Gafanhotos mordedores em enxame preenchem uma esfera com raio de 6 metros centrada em um ponto que você escolher dentro do alcance. A esfera se propaga contornando cantos e curvas. A esfera permanece pela duração e sua área fica sob penumbra leve (levemente obscurecida). A área da esfera é terreno difícil.\n\nQuando a área surge, cada criatura dentro dela deve realizar um teste de resistência de Constituição. Uma criatura sofre 4d10 de dano perfurante em uma falha na salvaguarda, ou metade desse dano em um sucesso. Uma criatura também deve realizar este teste de resistência quando entra na área da magia pela primeira vez em um turno ou termina seu turno nela.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 5º.", en: "Swarming, biting locusts fill a 20-foot radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere's area is difficult terrain.\n\nWhen the area appears, each creature in it must make a Constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th." } },
  { id: 'mislead',                level: 5, school: 'illusion',     classes: ['bard','wizard'], castingTime: '1 action', range: 'Self', components: 'S', duration: 'Conc. 1 hour', desc: { pt: "Você fica invisível no mesmo instante em que um duplo ilusório de você aparece onde você está de pé. O duplo dura pela duração, mas a invisibilidade termina se você atacar ou conjurar uma magia.\n\nVocê pode usar sua ação para mover seu duplo ilusório por até o dobro do seu deslocamento e fazê-lo gesticular, falar e se comportar da maneira que você escolher.\n\nVocê pode ver através dos olhos dele e ouvir através dos ouvidos dele como se estivesse localizado onde ele está. Em cada um dos seus turnos, como uma ação bônus, você pode alternar entre usar os sentidos dele ou usar os seus próprios, ou voltar novamente. Enquanto estiver usando os sentidos dele, você fica cego e surdo em relação ao seu próprio ambiente ao redor.", en: "You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell.\n\nYou can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose.\n\nYou can see through its eyes and hear through its ears as if you were located where it is. On each of your turns as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings." } },
  { id: 'modifyMemory',           level: 5, school: 'enchantment',  classes: ['bard','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você tenta remodelar as memórias de outra criatura. Uma criatura que você possa ver deve realizar um teste de resistência de Sabedoria. Se você estiver lutando contra a criatura, ela terá vantagem no teste de resistência. Em caso de falha no teste, o alvo fica enfeitiçado por você pela duração. O alvo enfeitiçado fica incapacitado e alheio ao que está ao seu redor, embora ainda possa ouvir você. Se sofrer qualquer dano ou for alvo de outra magia, esta magia termina e nenhuma das memórias do alvo é modificada.\n\nEnquanto esse encanto durar, você pode afetar a memória do alvo referente a um evento que ele tenha vivenciado nas últimas 24 horas e que não tenha durado mais de 10 minutos. Você pode eliminar permanentemente qualquer lembrança do evento, permitir que o alvo recorde o evento com perfeita clareza e riqueza de detalhes, alterar sua lembrança dos detalhes do evento ou criar uma lembrança de outro evento qualquer.\n\nVocê deve falar com o alvo para descrever como as memórias dele são afetadas, e ele deve ser capaz de compreender o seu idioma para que as memórias modificadas se fixem. A mente dele preenche quaisquer lacunas nos detalhes da sua descrição. Se a magia terminar antes de você concluir a descrição das memórias modificadas, a memória da criatura não é alterada. Do contrário, as memórias modificadas se consolidam quando a magia termina.\n\nUma memória modificada não afeta necessariamente a forma como uma criatura se comporta, principalmente se a memória contradizer as inclinações naturais, alinhamento ou crenças da criatura. Uma memória modificada ilógica, como implantar uma lembrança de como a criatura gostou de se banhar em ácido, é descartada, talvez como um pesadelo. O Mestre pode considerar uma memória modificada sem sentido demais para afetar uma criatura de maneira significativa.\n\nA magia remover maldição ou restauração maior conjurada no alvo restaura a verdadeira memória da criatura.\n\nEm Níveis Superiores. Se você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, você poderá alterar as memórias do alvo de um evento ocorrido há até 7 dias (6º círculo), 30 dias (7º círculo), 1 ano (8º círculo) ou em qualquer momento do passado da criatura (9º círculo).", en: "You attempt to reshape another creature's memories. One creature that you can see must make a Wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target's memories are modified.\n\nWhile this charm lasts, you can affect the target's memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity and exacting detail, change its memory of the details of the event, or create a memory of some other event.\n\nYou must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you have finished describing the modified memories, the creature's memory isn't altered. Otherwise, the modified memories take hold when the spell ends.\n\nA modified memory doesn't necessarily affect how a creature behaves, particularly if the memory contradicts the creature's natural inclinations, alignment, or beliefs. An illogical modified memory, such as implanting a memory of how much the creature enjoyed dousing itself in acid, is dismissed, perhaps as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature in a significant manner.\n\nA remove curse or greater restoration spell cast on the target restores the creature's true memory.\n\nAt Higher Levels. If you cast this spell using a spell slot of 6th level or higher, you can alter the target's memories of an event that took place up to 7 days ago (6th level), 30 days ago (7th level), 1 year ago (8th level), or any time in the creature's past (9th level)." } },
  { id: 'planarBinding',          level: 5, school: 'abjuration',   classes: ['bard','cleric','druid','wizard'], castingTime: '1 hour', range: '60 ft', components: 'V, S, M', duration: '24 hours', desc: { pt: "Com esta magia, você tenta vincular um celestial, um elemental, uma fada ou um corruptor ao seu serviço. A criatura deve estar dentro do alcance durante todo o tempo de conjuração da magia. (Normalmente, a criatura é primeiro invocada no centro de um círculo mágico invertido para mantê-la presa enquanto esta magia é conjurada.) Ao término da conjuração, o alvo deve realizar um teste de resistência de Carisma. Em caso de falha na salvaguarda, ele é vinculado a servir você pela duração. Se a criatura foi invocada ou criada por outra magia, a duração dessa outra magia é estendida para corresponder à duração desta magia.\n\nUma criatura vinculada deve seguir suas instruções o melhor que puder. Você pode ordenar à criatura que acompanhe você em uma aventura, que guarde um local ou que entregue uma mensagem. A criatura obedece à risca as suas instruções, mas se a criatura for hostil a você, ela se esforçará para distorcer suas palavras para atingir seus próprios objetivos. Se a criatura cumprir totalmente as suas instruções antes de a magia terminar, ela viajará até você para relatar esse fato se vocês estiverem no mesmo plano de existência. Se você estiver em um plano de existência diferente, ela retornará ao local onde você a vinculou e lá permanecerá até a magia terminar.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de círculo superior, a duração aumenta para 10 dias com um espaço de 6º círculo, para 30 dias com um espaço de 7º círculo, para 180 dias com um espaço de 8º círculo e para um ano e um dia com um espaço de magia de 9º círculo.", en: "With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a Charisma saving throw. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell's duration is extended to match the duration of this spell.\n\nA bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of a higher level, the duration increases to 10 days with a 6th-level slot, to 30 days with a 7th-level slot, to 180 days with an 8th-level slot, and to a year and a day with a 9th-level spell slot." } },
  { id: 'reincarnate',            level: 5, school: 'transmutation', classes: ['druid'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você toca um humanoide morto ou um pedaço de um humanoide morto. Desde que a criatura não esteja morta há mais de 10 dias, a magia forma um novo corpo adulto para ela e então chama a alma para entrar nesse corpo.\n\nSe a alma do alvo não estiver livre ou disposta a fazê-lo, a magia falha.\n\nA magia molda um novo corpo para a criatura habitar, o que provavelmente faz com que a raça da criatura mude. O Mestre rola um d100 e consulta a tabela a seguir para determinar qual forma a criatura assume ao retornar à vida, ou o Mestre escolhe uma forma.\n\nTabela - Raça de Reencarnação\n\n| d100 | Raça |\n|-------|---------------------|\n| 01-04 | Draconato |\n| 05-13 | Anão da colina |\n| 14-21 | Anão da montanha |\n| 22-25 | Elfo negro |\n| 26-34 | Alto elfo |\n| 35-42 | Elfo da floresta |\n| 43-46 | Gnomo da floresta |\n| 47-52 | Gnomo das rochas |\n| 53-56 | Meio-elfo |\n| 57-60 | Meio-orc |\n| 61-68 | Halfling pé-leve |\n| 69-76 | Halfling robusto |\n| 77-96 | Humano |\n| 97-00 | Tiefling |\n| | |\n\nA criatura reencarnada recorda sua vida e experiências passadas. Ela mantém as capacidades que possuía em sua forma original, exceto pelo fato de trocar sua raça original pela nova, alterando seus traços raciais de acordo.", en: "You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body.\n\nIf the target's soul isn't free or willing to do so, the spell fails.\n\nThe magic fashions a new body for the creature to inhabit, which likely causes the creature's race to change. The GM rolls a d100 and consults the following table to determine what form the creature takes when restored to life, or the GM chooses a form.\n\nTable- Reincarnate Race\n\n| d100 | Race        |\n|-------|---------------------|\n| 01-04 | Dragonborn     |\n| 05-13 | Dwarf, hill     |\n| 14-21 | Dwarf, mountain   |\n| 22-25 | Elf, dark      |\n| 26-34 | Elf, high      |\n| 35-42 | Elf, wood      |\n| 43-46 | Gnome, forest    |\n| 47-52 | Gnome, rock     |\n| 53-56 | Half-elf      |\n| 57-60 | Half-orc      |\n| 61-68 | Halfling, lightfoot |\n| 69-76 | Halfling, stout   |\n| 77-96 | Human        |\n| 97-00 | Tiefling      |\n|    |           |\n\nThe reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original race for the new one and changes its racial traits accordingly." } },
  { id: 'scrying',                level: 5, school: 'divination',   classes: ['bard','cleric','druid','warlock','wizard'], castingTime: '10 min', range: 'Self', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você pode ver e ouvir uma criatura específica de sua escolha que esteja no mesmo plano de existência que você. O alvo deve realizar um teste de resistência de Sabedoria, que é modificado por quão bem você conhece o alvo e pelo tipo de conexão física que você possui com ele. Se um alvo souber que você está conjurando esta magia, ele pode falhar voluntariamente no teste de resistência se desejar ser observado.\n\nTabela - Modificador de Salvaguarda de Adivinhação\n\n| Conhecimento | Modificador no Teste |\n|---|---|\n| Por terceiros (você ouviu falar do alvo) | +5 |\n| Em primeira mão (você já conheceu o alvo) | +0 |\n| Familiar (você conhece bem o alvo) | -5 |\n| Conexão | Modificador no Teste |\n| Semelhança ou retrato | -2 |\n| Pertence ou vestimenta | -4 |\n| Parte do corpo, mecha de cabelo, pedaço de unha ou semelhante | -10 |\n| | |\n\nEm caso de sucesso no teste, o alvo não é afetado, e você não pode usar esta magia contra ele novamente por 24 horas.\n\nEm caso de falha no teste, a magia cria um sensor invisível a até 3 metros do alvo. Você pode ver e ouvir através do sensor como se estivesse lá. O sensor se move com o alvo, permanecendo a até 3 metros dele pela duração. Uma criatura capaz de ver objetos invisíveis enxerga o sensor como uma esfera luminosa aproximadamente do tamanho do seu punho.\n\nEm vez de mirar em uma criatura, você pode escolher um local que já tenha visto antes como alvo desta magia. Quando faz isso, o sensor surge naquele local e não se move.", en: "You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a Wisdom saving throw, which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you're casting this spell, it can fail the saving throw voluntarily if it wants to be observed.\n\nTable- Scrying Save Modifier\n\n| Knowledge                     | Save Modifier |\n|---------------------------------------------------|---------------|\n| Secondhand (you have heard of the target)     | +5      |\n| Firsthand (you have met the target)        | +0      |\n| Familiar (you know the target well)        | -5      |\n| Connection                    | Save Modifier |\n| Likeness or picture                | -2      |\n| Possession or garment               | -4      |\n| Body part, lock of hair, bit of nail, or the like | -10      |\n|                          |        |\n\nOn a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours.\n\nOn a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist.\n\nInstead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn't move." } },
  { id: 'seeming',                level: 5, school: 'illusion',     classes: ['bard','sorcerer','wizard'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: '8 hours', desc: { pt: "Esta magia permite que você altere a aparência de qualquer número de criaturas que possa ver dentro do alcance. Você concede a cada alvo escolhido uma nova aparência ilusória. Um alvo relutante pode realizar um teste de resistência de Carisma e, se obtiver sucesso, não será afetado por esta magia.\n\nA magia disfarça a aparência física, bem como roupas, armaduras, armas e equipamentos. Você pode fazer com que cada criatura pareça 30 centímetros mais baixa ou mais alta e aparente ser magra, gorda ou com porte intermediário. Você não pode alterar o tipo de corpo de um alvo, de modo que deve escolher uma forma que possua a mesma disposição básica de membros. Fora isso, a extensão da ilusão depende de você. A magia dura pela duração, a menos que você use sua ação para dispensá-la antes.\n\nAs alterações provocadas por esta magia não resistem a uma inspeção física. Por exemplo, se você usar esta magia para adicionar um chapéu ao traje de uma criatura, objetos atravessarão o chapéu, e qualquer um que o tocar não sentirá nada ou sentirá a cabeça e os cabelos da criatura. Se usar esta magia para parecer mais magro do que é, a mão de alguém que estenda o braço para tocar você colidirá com você enquanto ainda estiver aparentemente no meio do ar.\n\nUma criatura pode usar sua ação para inspecionar um alvo e realizar um teste de Inteligência (Investigação) contra a CD de resistência da sua magia. Se obtiver sucesso, ela percebe que o alvo está disfarçado.", en: "This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a Charisma saving throw, and if it succeeds, it is unaffected by this spell.\n\nThe spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between. You can't change a target's body type, so you must choose a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The spell lasts for the duration, unless you use your action to dismiss it sooner.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature's outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel the creature's head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nA creature can use its action to inspect a target and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised." } },
  { id: 'treeStride',             level: 5, school: 'conjuration',  classes: ['druid','ranger'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Você ganha a capacidade de entrar em uma árvore e se mover de dentro dela para dentro de outra árvore da mesma espécie a até 150 metros. Ambas as árvores devem estar vivas e ter pelo menos o mesmo tamanho que você. Você deve usar 1,5 metro de movimento para entrar em uma árvore. Você sabe instantaneamente a localização de todas as outras árvores da mesma espécie a até 150 metros e, como parte do movimento usado para entrar na árvore, pode passar para uma dessas árvores ou sair da árvore em que está. Você aparece em um ponto à sua escolha a até 1,5 metro da árvore de destino, usando mais 1,5 metro de movimento. Se não lhe restar movimento, você aparece a até 1,5 metro da árvore em que entrou.\nVocê pode usar essa capacidade de transporte apenas uma vez em cada um dos seus turnos. Você deve terminar cada turno fora de uma árvore.", en: "You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered.\n\nYou can use this transportation ability once per round for the duration. You must end each turn outside a tree." } },
  { id: 'wallOfForce',            level: 5, school: 'evocation',    classes: ['wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Uma parede de energia Invisível surge em um ponto à sua escolha dentro do alcance. A parede aparece em qualquer orientação que você escolher, como uma barreira horizontal ou vertical ou em ângulo. Ela pode flutuar livremente ou repousar sobre uma superfície sólida. Você pode moldá-la em uma cúpula hemisférica ou em um globo com raio de até 3 metros, ou pode moldar uma superfície plana composta de dez painéis de 3 por 3 metros. Cada painel deve ser contíguo a outro painel. Em qualquer forma, a parede tem 0,6 centímetro de espessura e dura pela duração. Se a parede atravessar o espaço de uma criatura quando aparecer, a criatura é empurrada para um dos lados da parede (você escolhe qual).\nNada pode atravessar fisicamente a parede. Ela é imune a todo dano e não pode ser dissipada por Dissipar Magia. Uma magia Desintegrar, no entanto, destrói a parede instantaneamente. A parede também se estende ao Plano Etéreo e bloqueia viagens etéreas através dela.", en: "An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick. It lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice which side).\n\nNothing can physically pass through the wall. It is immune to all damage and can't be dispelled by dispel magic. A disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane, blocking ethereal travel through the wall." } },

  // === LEVEL 6 ADICIONAIS ===
  { id: 'bladeBarrier',           level: 6, school: 'evocation',    classes: ['cleric'], castingTime: '1 action', range: '90 ft', components: 'V, S', duration: 'Conc. 10 min', desc: { pt: "Você cria uma parede vertical de lâminas giratórias e afiadas como navalha feitas de energia mágica. A parede surge dentro do alcance e dura pela duração. Você pode criar uma parede reta de até 30 metros de comprimento, 6 metros de altura e 1,5 metro de espessura, ou uma parede circular de até 18 metros de diâmetro, 6 metros de altura e 1,5 metro de espessura. A parede concede três quartos de cobertura para criaturas atrás dela, e seu espaço é terreno difícil.\n\nQuando uma criatura entrar na área da parede pela primeira vez em um turno ou começar seu turno nela, a criatura deve fazer uma salvaguarda de Destreza. Se falhar na salvaguarda, a criatura sofre 6d10 de dano cortante. Se obtiver sucesso na salvaguarda, a criatura sofre metade desse dano.", en: "You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it, and its space is difficult terrain.\n\nWhen a creature enters the wall's area for the first time on a turn or starts its turn there, the creature must make a Dexterity saving throw. On a failed save, the creature takes 6d10 slashing damage. On a successful save, the creature takes half as much damage." } },
  { id: 'conjureFey',             level: 6, school: 'conjuration',  classes: ['bard','druid'], castingTime: '1 min', range: '90 ft', components: 'V, S', duration: 'Conc. 1 hour', desc: { pt: "Você conjura uma criatura feérica de nível de desafio 6 ou inferior, ou um espírito feérico que assume a forma de uma besta de nível de desafio 6 ou inferior. Ela surge em um espaço desocupado que você possa ver dentro do alcance. A criatura feérica desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nA criatura feérica é amigável a você e aos seus companheiros pela duração. Role iniciativa para a criatura, que possui seus próprios turnos. Ela obedece a quaisquer comandos verbais que você emitir para ela (nenhuma ação exigida de você), desde que não violem seu alinhamento. Se você não emitir nenhum comando para a criatura feérica, ela se defende de criaturas hostis, mas de outro modo não realiza ações.\n\nSe a sua concentração for quebrada, a criatura feérica não desaparece. Em vez disso, você perde o controle da criatura feérica, ela se torna hostil em relação a você e aos seus companheiros e pode atacar. Uma criatura feérica descontrolada não pode ser dispensada por você e desaparece 1 hora após ter sido conjurada.\n\nO Mestre tem as estatísticas da criatura feérica.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o nível de desafio aumenta em 1 para cada círculo do espaço acima do 6º.", en: "You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe fey creature is friendly to you and your companions for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the fey creature, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the fey creature doesn't disappear. Instead, you lose control of the fey creature, it becomes hostile toward you and your companions, and it might attack. An uncontrolled fey creature can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the fey creature's statistics.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the challenge rating increases by 1 for each slot level above 6th." } },
  { id: 'disintegrate',           level: 6, school: 'transmutation', classes: ['sorcerer','wizard'], castingTime: '1 action', range: '60 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Um fino raio verde brota do seu dedo apontado para um alvo que você possa ver dentro do alcance. O alvo pode ser uma criatura, um objeto ou uma criação de energia mágica, como a parede criada por parede de energia.\n\nUma criatura alvo desta magia deve fazer uma salvaguarda de Destreza. Em uma salvaguarda fracassada, o alvo sofre 10d6 + 40 de dano de energia. O alvo é desintegrado se este dano o deixar com 0 Pontos de Vida.\n\nUma criatura desintegrada e tudo o que ela estiver vestindo e carregando, exceto itens mágicos, são reduzidos a uma pilha de pó cinzento fino. A criatura só pode ser restaurada à vida por meio das magias ressurreição verdadeira ou desejo.\n\nEsta magia desintegra automaticamente um objeto não mágico Grande ou menor ou uma criação de energia mágica. Se o alvo for um objeto ou criação de energia Enorme ou maior, esta magia desintegra uma porção dele correspondente a um cubo de 3 metros. Um item mágico não é afetado por esta magia.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o dano aumenta em 3d6 para cada círculo do espaço acima do 6º.", en: "A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by wall of force.\n\nA creature targeted by this spell must make a Dexterity saving throw. On a failed save, the target takes 10d6 + 40 force damage. The target is disintegrated if this damage leaves it with 0 hit points.\n\nA disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust. The creature can be restored to life only by means of a true resurrection or a wish spell.\n\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If the target is a Huge or larger object or creation of force, this spell disintegrates a 10-foot cube portion of it. A magic item is unaffected by this spell.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 3d6 for each slot level above 6th." } },
  { id: 'findThePath',            level: 6, school: 'divination',   classes: ['bard','cleric','druid'], castingTime: '1 min', range: 'Self', components: 'V, S, M', duration: 'Conc. 1 day', desc: { pt: "Esta magia permite encontrar a rota física mais curta e direta para um local fixo específico com o qual você esteja familiarizado no mesmo plano de existência. Se você nomear um destino em outro plano de existência, um destino que se mova (como uma fortaleza móvel) ou um destino que não seja específico (como \"o covil de um dragão verde\"), a magia falha.\n\nPela duração, desde que você esteja no mesmo plano de existência do destino, você sabe a que distância ele fica e em qual direção se encontra. Enquanto estiver viajando para lá, sempre que se deparar com uma escolha de caminhos ao longo do trajeto, você determina automaticamente qual caminho é a rota mais curta e direta (embora não necessariamente a mais segura) para o destino.", en: "This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn't specific (such as \"a green dragon's lair\"), the spell fails.\n\nFor the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination." } },
  { id: 'globeOfInvulnerability', level: 6, school: 'abjuration',   classes: ['sorcerer','wizard'], castingTime: '1 action', range: 'Self (10-ft radius)', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Uma barreira imóvel e levemente cintilante surge em um raio de 3 metros ao seu redor e permanece pela duração.\n\nQualquer magia de 5º círculo ou inferior conjurada do lado de fora da barreira não pode afetar criaturas ou objetos dentro dela, mesmo se a magia for conjurada usando um espaço de magia de círculo superior. Tal magia pode ter como alvo criaturas e objetos dentro da barreira, mas a magia não surte efeito sobre eles. De forma semelhante, a área dentro da barreira é excluída das áreas afetadas por tais magias.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 7º círculo ou superior, a barreira bloqueia magias de um círculo superior para cada círculo do espaço acima do 6º.", en: "An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration.\n\nAny spell of 5th level or lower cast from outside the barrier can't affect creatures or objects within it, even if the spell is cast using a higher level spell slot. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from the areas affected by such spells.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the barrier blocks spells of one level higher for each slot level above 6th." } },
  { id: 'heroesFeast',            level: 6, school: 'conjuration',  classes: ['cleric','druid'], castingTime: '10 min', range: '30 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você manifesta um grande banquete, incluindo comidas e bebidas magníficas. O banquete leva 1 hora para ser consumido e desaparece ao fim desse tempo, e os efeitos benéficos não se manifestam até que essa hora termine. Até doze criaturas podem participar do banquete.\n\nUma criatura que participa do banquete recebe vários benefícios. A criatura é curada de todas as doenças e venenos, torna-se imune a veneno e à condição amedrontado, e realiza todos os testes de resistência de Sabedoria com vantagem. Seu máximo de pontos de vida também aumenta em 2d10 e ela ganha a mesma quantidade em pontos de vida. Esses benefícios duram por 24 horas.", en: "You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve creatures can partake of the feast.\n\nA creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all Wisdom saving throws with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours." } },
  { id: 'moveEarth',              level: 6, school: 'transmutation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 2 hours', desc: { pt: "Escolha uma área de terreno de até 12 metros de lado dentro do alcance. Você pode remodelar terra, areia ou argila na área da maneira que escolher pela duração. Você pode elevar ou rebaixar a elevação da área, criar ou preencher uma vala, erguer ou aplanar um muro ou formar um pilar. A extensão de tais mudanças não pode exceder metade da maior dimensão da área. Portanto, se você afetar um quadrado de 12 metros de lado, poderá criar um pilar de até 6 metros de altura, elevar ou rebaixar a elevação do quadrado em até 6 metros, cavar uma trincheira de até 6 metros de profundidade e assim por diante. Leva 10 minutos para que essas alterações sejam concluídas.\n\nAo final de cada 10 minutos em que passar se concentrando na magia, você pode escolher uma nova área de terreno para afetar.\n\nComo a transformação do terreno ocorre lentamente, as criaturas na área geralmente não podem ser presas ou feridas pelo movimento da terra.\n\nEsta magia não pode manipular pedra natural ou construções de pedra. Rochas e estruturas se deslocam para se acomodar ao novo terreno. Se a maneira como você moldar o terreno tornar uma estrutura instável, ela poderá desabar.\n\nDa mesma forma, esta magia não afeta diretamente o crescimento das plantas. A terra movida carrega quaisquer plantas junto com ela.", en: "Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. So, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete.\n\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect.\n\nBecause the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement.\n\nThis spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\n\nSimilarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it." } },
  { id: 'sunbeam',                level: 6, school: 'evocation',    classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: 'Self (60-ft line)', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Um feixe de luz brilhante dispara da sua mão em uma linha de 1,5 metro de largura por 18 metros de comprimento. Cada criatura na linha deve realizar um teste de resistência de Constituição. Em caso de falha no teste, uma criatura sofre 6d8 de dano radiante e fica cega até o seu próximo turno. Em caso de sucesso na salvaguarda, ela sofre metade desse dano e não fica cega por esta magia. Mortos-vivos e limos têm desvantagem nesse teste de resistência.\n\nVocê pode criar uma nova linha de resplendor como sua ação em qualquer turno até a magia terminar.\n\nPela duração, um ponto de luz brilhante reluz na sua mão. Ele emite luz plena em um raio de 9 metros e penumbra por mais 9 metros adicionais. Esta luz é luz solar.", en: "A beam of brilliant light flashes out from your hand in a 5-foot wide, 60-foot long line. Each creature in the line must make a Constitution saving throw. On a failed save, a creature takes 6d8 radiant damage and is blinded until your next turn. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nYou can create a new line of radiance as your action on any turn until the spell ends.\n\nFor the duration, a mote of brilliant radiance shines in your hand. It sheds bright light in a 30-foot radius and dim light for an additional 30 feet. This light is sunlight." } },
  { id: 'transportViaPlants',     level: 6, school: 'conjuration',  classes: ['druid'], castingTime: '1 action', range: '10 ft', components: 'V, S', duration: '1 round', desc: { pt: "Esta magia cria uma ligação mágica entre uma planta inanimada Grande ou maior dentro do alcance e outra planta, a qualquer distância, no mesmo plano de existência. Você deve ter visto ou tocado a planta de destino pelo menos uma vez antes. Pela duração, qualquer criatura pode entrar na planta-alvo e sair pela planta de destino usando 1,5 metro de movimento.", en: "This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement." } },
  { id: 'trueSeeing',             level: 6, school: 'divination',   classes: ['bard','cleric','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', desc: { pt: "Esta magia concede à criatura voluntária que você tocar a habilidade de enxergar as coisas como elas realmente são. Pela duração, a criatura possui percepção verdadeira, percebe portas secretas ocultas por magia e pode enxergar no Plano Etéreo, tudo isso até um alcance de 36 metros.", en: "This spell gives the willing creature you touch the ability to see things as they actually are. For the duration, the creature has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to a range of 120 feet." } },
  { id: 'wallOfThorns',           level: 6, school: 'conjuration',  classes: ['druid'], castingTime: '1 action', range: '120 ft', components: 'V, S, M', duration: 'Conc. 10 min', desc: { pt: "Você cria uma muralha de espinheiros densos, flexíveis e entrelaçados, eriçados com espinhos pontiagudos como agulhas. A muralha surge dentro do alcance sobre uma superfície sólida e dura pela duração. Você pode fazer a muralha ter até 18 metros de comprimento, 3 metros de altura e 1,5 metro de espessura, ou um círculo com 6 metros de diâmetro, até 6 metros de altura e 1,5 metro de espessura. A muralha bloqueia a linha de visão.\n\nQuando a muralha surge, cada criatura dentro da área dela deve realizar um teste de resistência de Destreza. Se falhar na salvaguarda, a criatura sofre 7d8 de dano perfurante, ou metade desse dano em caso de sucesso.\n\nUma criatura pode se mover através da muralha, embora lenta e dolorosamente. Para cada 1 metro que a criatura se mover através da muralha, ela deve gastar 4 metros de movimento. Além disso, na primeira vez que uma criatura entra na muralha em um turno ou encerra o turno lá, a criatura deve realizar um teste de resistência de Destreza. Ela sofre 7d8 de dano cortante em caso de falha no teste, ou metade desse dano em caso de sucesso.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 7º círculo ou superior, ambos os tipos de dano aumentam em 1d8 para cada círculo do espaço acima do 6º.", en: "You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight.\n\nWhen the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 7d8 piercing damage, or half as much damage on a successful save.\n\nA creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters the wall on a turn or ends its turn there, the creature must make a Dexterity saving throw. It takes 7d8 slashing damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, both types of damage increase by 1d8 for each slot level above 6th." } },
  { id: 'windWalk',               level: 6, school: 'transmutation', classes: ['druid'], castingTime: '1 min', range: '30 ft', components: 'V, S, M', duration: '8 hours', desc: { pt: "Você e até dez criaturas voluntárias que possa ver dentro do alcance assumem uma forma gasosa pela duração, aparentando farrapos de nuvens. Enquanto estiver nessa forma de nuvem, uma criatura tem um deslocamento de voo de 90 metros e tem resistência a dano de armas não mágicas. As únicas ações que uma criatura pode realizar nessa forma são a ação de Disparada ou reverter à sua forma normal. Reverter leva 1 minuto, durante o qual a criatura fica incapacitada e não pode se mover. Até a magia terminar, uma criatura pode reverter à forma de nuvem, o que também exige a transformação de 1 minuto.\n\nSe uma criatura estiver na forma de nuvem e voando quando o efeito terminar, a criatura desce 18 metros por rodada durante 1 minuto até pousar em segurança. Se não puder pousar após 1 minuto, a criatura cai a distância restante.", en: "You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form. Reverting takes 1 minute, during which time a creature is incapacitated and can't move. Until the spell ends, a creature can revert to cloud form, which also requires the 1-minute transformation.\n\nIf a creature is in cloud form and flying when the effect ends, the creature descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, the creature falls the remaining distance." } },

  // === LEVEL 7 ADICIONAIS ===
  { id: 'mirageArcane',           level: 7, school: 'illusion',     classes: ['bard','druid','wizard'], castingTime: '10 min', range: 'Sight', components: 'V, S', duration: '10 days', desc: { pt: "Você faz o terreno em uma área de até 1,5 quilômetro quadrado parecer, soar, cheirar e até mesmo dar a sensação de ser outro tipo de terreno. Campos abertos ou uma estrada podem ser feitos para parecer um pântano, uma colina, uma fenda ou algum outro terreno acidentado ou intransponível. Um lago pode ser feito para parecer um prado gramado, um precipício para parecer uma encosta suave, ou uma ravina cheia de pedras para parecer uma estrada larga e lisa.\nDa mesma forma, você pode alterar a aparência de estruturas ou acrescentá-las onde não existem. A magia não disfarça, oculta nem acrescenta criaturas.\nA ilusão inclui elementos auditivos, visuais, táteis e olfativos, de modo que pode transformar terreno livre em Terreno Difícil (ou vice-versa) ou de outra forma dificultar o movimento pela área. Qualquer parte do terreno ilusório (como uma pedra ou um galho) que seja removida da área da magia desaparece imediatamente.\nCriaturas com Visão Verdadeira conseguem enxergar através da ilusão a verdadeira forma do terreno; no entanto, todos os outros elementos da ilusão permanecem, de modo que, embora a criatura esteja ciente da presença da ilusão, ela ainda pode interagir fisicamente com a ilusão.", en: "You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain's general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.\n\nSimilarly, you can alter the appearance of structures, or add them where none are present. The spell doesn't disguise, conceal, or add creatures.\n\nThe illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately.\n\nCreatures with truesight can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion." } },
  { id: 'planeShift',             level: 7, school: 'conjuration',  classes: ['cleric','druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você e até oito criaturas voluntárias que unirem as mãos em um círculo são transportados para um plano de existência diferente. Você pode especificar um destino geral, como a Cidade de Latão no Plano Elemental do Fogo ou o palácio de Dispater no segundo nível dos Nove Infernos, e vocês aparecem nesse destino ou próximo a ele. Se estiver tentando chegar à Cidade de Latão, por exemplo, você pode chegar à Rua de Aço, diante do Portão das Cinzas ou avistando a cidade do outro lado do Mar de Fogo, a critério do Mestre.\n\nAlternativamente, se conhecer a sequência de sigilos de um círculo de teletransporte em outro plano de existência, esta magia pode levar vocês até esse círculo. Se o círculo de teletransporte for pequeno demais para conter todas as criaturas que você transportou, elas aparecem nos espaços desocupados mais próximos adjacentes ao círculo.\n\nVocê pode usar esta magia para banir uma criatura relutante para outro plano. Escolha uma criatura ao seu alcance e faça um ataque corpo a corpo com magia contra ela. Em caso de acerto, a criatura deve realizar um teste de resistência de Carisma. Se falhar nesse teste, ela é transportada para um local aleatório no plano de existência que você especificar. Uma criatura transportada dessa forma deve encontrar seu próprio caminho de volta ao seu plano de existência atual.", en: "You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination. If you are trying to reach the City of Brass, for example, you might arrive in its Street of Steel, before its Gate of Ashes, or looking at the city from across the Sea of Fire, at the GM's discretion.\n\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.\n\nYou can use this spell to banish an unwilling creature to another plane. Choose a creature within your reach and make a melee spell attack against it. On a hit, the creature must make a Charisma saving throw. If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence." } },
  { id: 'regenerate',             level: 7, school: 'transmutation', classes: ['bard','cleric','druid'], castingTime: '1 min', range: 'Touch', components: 'V, S, M', duration: '1 hour', desc: { pt: "Você toca uma criatura e estimula sua capacidade natural de cura. O alvo recupera 4d8 + 15 Pontos de Vida. Pela duração da magia, o alvo recupera 1 Ponto de Vida no início de cada um dos seus turnos (10 Pontos de Vida por minuto).\n\nMembros decepados do alvo (dedos, pernas, caudas e assim por diante), se houver, são restaurados após 2 minutos. Se você tiver a parte decepada e a mantiver encostada ao coto, a magia faz instantaneamente com que o membro se refaça e se una ao coto.", en: "You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 hit point at the start of each of its turns (10 hit points each minute).\n\nThe target's severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump." } },
  { id: 'reverseGravity',         level: 7, school: 'transmutation', classes: ['druid','sorcerer','wizard'], castingTime: '1 action', range: '100 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Esta magia inverte a gravidade em um cilindro de 15 metros de raio e 30 metros de altura centrado em um ponto dentro do alcance. Todas as criaturas e objetos que não estejam de alguma forma ancorados ao solo na área caem para cima e atingem o topo da área quando você conjura esta magia. Uma criatura pode realizar um teste de resistência de Destreza para se agarrar a um objeto fixo que possa alcançar, evitando assim a queda.\n\nSe algum objeto sólido (como um teto) for encontrado nessa queda, objetos e criaturas que estejam caindo colidem contra ele exatamente como fariam durante uma queda normal para baixo. Se um objeto ou criatura atingir o topo da área sem colidir com nada, ele permanecerá ali, oscilando suavemente, pela duração.\n\nAo final da duração, objetos e criaturas afetados caem de volta para baixo.", en: "This spell reverses gravity in a 50-foot radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren't somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a Dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall.\n\nIf some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration.\n\nAt the end of the duration, affected objects and creatures fall back down." } },
  { id: 'symbolSpell',            level: 7, school: 'abjuration',   classes: ['bard','cleric','wizard'], castingTime: '1 min', range: 'Touch', components: 'V, S, M', duration: 'Until triggered', desc: { pt: "Quando você conjura esta magia, você inscreve um glifo prejudicial em uma superfície (como uma seção do chão, uma parede ou uma mesa) ou dentro de um objeto que possa ser fechado para ocultar o glifo (como um livro, um pergaminho ou um baú de tesouro). Se escolher uma superfície, o glifo pode cobrir uma área da superfície de no máximo 3 metros de diâmetro. Se escolher um objeto, esse objeto deve permanecer no lugar dele; se o objeto for movido mais de 3 metros de onde você conjurou esta magia, o glifo é rompido e a magia termina sem ser ativada.\n\nO glifo é quase invisível, exigindo um teste de Inteligência (Investigação) contra a CD de salvaguarda da sua magia para encontrá-lo.\n\nVocê decide o que ativa o glifo quando conjura a magia. Para glifos inscritos em uma superfície, os gatilhos mais comuns incluem tocar ou pisar no glifo, remover outro objeto que o cubra, aproximar-se a uma certa distância dele ou manipular o objeto que o contém. Para glifos inscritos dentro de um objeto, os gatilhos mais comuns são abrir o objeto, aproximar-se a uma certa distância dele ou ver ou ler o glifo.\n\nVocê pode refinar ainda mais o gatilho para que a magia seja ativada apenas sob certas circunstâncias ou de acordo com as características físicas de uma criatura (como altura ou peso) ou tipo físico (por exemplo, a proteção pode ser definida para afetar bruxas ou metamorfos). Você também pode especificar criaturas que não ativam o glifo, como aquelas que dizem uma certa senha.\n\nQuando inscrever o glifo, escolha uma das opções abaixo para o efeito dele. Uma vez ativado, o glifo brilha, preenchendo uma esfera com raio de 18 metros com luz penumbrosa por 10 minutos, após o que a magia termina. Cada criatura na esfera quando o glifo é ativado se torna alvo do seu efeito, assim como uma criatura que entrar na esfera pela primeira vez em um turno ou terminar o turno dela lá.\n\nMorte. Cada alvo deve fazer uma salvaguarda de Constituição, sofrendo 10d10 de dano necrótico se falhar na salvaguarda, ou metade desse dano em um sucesso.\n\nDiscórdia. Cada alvo deve fazer uma salvaguarda de Constituição. Se falhar na salvaguarda, o alvo briga e discute com outras criaturas por 1 minuto. Durante esse tempo, ele é incapaz de se comunicar de forma significativa e tem desvantagem em jogadas de ataque e testes de atributo.\n\nMedo. Cada alvo deve fazer uma salvaguarda de Sabedoria e fica amedrontado por 1 minuto se falhar na salvaguarda. Enquanto estiver amedrontado, o alvo larga o que estiver segurando e deve se mover pelo menos 9 metros para longe do glifo em cada um dos turnos dele, se puder.\n\nDesespero. Cada alvo deve fazer uma salvaguarda de Carisma. Se falhar na salvaguarda, o alvo é dominado pelo desespero por 1 minuto. Durante esse tempo, ele não pode atacar ou escolher qualquer criatura como alvo com habilidades prejudiciais, magias ou outros efeitos mágicos.\n\nInsanidade. Cada alvo deve fazer uma salvaguarda de Inteligência. Se falhar na salvaguarda, o alvo enlouquece por 1 minuto. Uma criatura insana não pode realizar ações, não consegue entender o que as outras criaturas dizem, não consegue ler e fala apenas jargões sem sentido. O Mestre controla seu movimento, que é errático.\n\nDor. Cada alvo deve fazer uma salvaguarda de Constituição e fica incapacitado com uma dor insuportável por 1 minuto se falhar na salvaguarda.\n\nSono. Cada alvo deve fazer uma salvaguarda de Sabedoria e cai inconsciente por 10 minutos se falhar na salvaguarda. A criatura acorda se sofrer dano ou se alguém usar uma ação para sacudi-la ou estapeá-la para acordar.\n\nAtordoamento. Cada alvo deve fazer uma salvaguarda de Sabedoria e fica atordoado por 1 minuto se falhar na salvaguarda.", en: "When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible, requiring an Intelligence (Investigation) check against your spell save DC to find it.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph.\n\nYou can further refine the trigger so the spell is activated only under certain circumstances or according to a creature’s physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don’t trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose one of the options below for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activate is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there.\n\nDeath. Each target must make a Constitution saving throw, taking 10d10 necrotic damage on a failed save, or half as much damage on a successful save.\n\nDiscord. Each target must make a Constitution saving throw. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks.\n\nFear. Each target must make a Wisdom saving throw and becomes frightened for 1 minute on a failed save. While frightened, the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able.\n\nHopelessness. Each target must make a Charisma saving throw. On a failed save, the target is overwhelmed with despair for 1 minute. During this time, it can’t attack or target any creature with harmful abilities, spells, or other magical effects.\n\nInsanity. Each target must make an Intelligence saving throw. On a failed save, the target is driven insane for 1 minute. An insane creature can’t take actions, can’t understand what other creatures say, can’t read, and speaks only in gibberish. The DM controls its movement, which is erratic.\n\nPain. Each target must make a Constitution saving throw and becomes incapacitated with excruciating pain for 1 minute on a failed save.\n\nSleep. Each target must make a Wisdom saving throw and falls unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake.\n\nStunning. Each target must make a Wisdom saving throw and becomes stunned for 1 minute on a failed save." } },

  // === LEVEL 8 ADICIONAIS ===
  { id: 'animalShapes',           level: 8, school: 'transmutation', classes: ['druid'], castingTime: '1 action', range: '30 ft', components: 'V, S', duration: 'Conc. 24 hours', desc: { pt: "Sua magia transforma outros em bestas. Escolha qualquer número de criaturas voluntárias que você possa ver dentro do alcance. Você transforma cada alvo na forma de uma besta Grande ou menor com um nível de desafio de 4 ou inferior. Em turnos subsequentes, você pode usar sua ação para transformar criaturas afetadas em novas formas.\n\nA transformação dura pela duração para cada alvo, ou até que o alvo caia a 0 Pontos de Vida ou morra. Você pode escolher uma forma diferente para cada alvo. As estatísticas de jogo do alvo são substituídas pelas estatísticas da besta escolhida, embora o alvo mantenha seu alinhamento e seus valores de Inteligência, Sabedoria e Carisma. O alvo assume os Pontos de Vida de sua nova forma e, quando reverte à sua forma normal, retorna à quantidade de Pontos de Vida que tinha antes de se transformar. Se ele reverter em decorrência de cair a 0 Pontos de Vida, qualquer dano excedente passa para a sua forma normal. Desde que o dano excedente não reduza a forma normal da criatura a 0 Pontos de Vida, ela não fica inconsciente. A criatura fica limitada nas ações que pode realizar pela natureza da sua nova forma, e não pode falar nem conjurar magias.\n\nO equipamento do alvo se funde à nova forma. O alvo não pode ativar, empunhar ou de outra forma se beneficiar de nenhum dos seus equipamentos.", en: "Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms.\n\nThe transformation lasts for the duration for each target, or until the target drops to 0 hit points or dies. You can choose a different form for each target. A target's game statistics are replaced by the statistics of the chosen beast, though the target retains its alignment and Intelligence, Wisdom, and Charisma scores. The target assumes the hit points of its new form, and when it reverts to its normal form, it returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious. The creature is limited in the actions it can perform by the nature of its new form, and it can't speak or cast spells.\n\nThe target's gear melds into the new form. The target can't activate, wield, or otherwise benefit from any of its equipment." } },
  { id: 'antipathySympathy',      level: 8, school: 'enchantment',  classes: ['druid','wizard'], castingTime: '1 hour', range: '60 ft', components: 'V, S, M', duration: '10 days', desc: { pt: "Esta magia atrai ou repele criaturas à sua escolha. Você tem como alvo algo dentro do alcance: um objeto ou criatura Enorme ou menor, ou uma área que não seja maior que um cubo de 60 metros. Em seguida, especifique um tipo de criatura inteligente, como dragões vermelhos, goblins ou vampiros. Você investe o alvo com uma aura que atrai ou repele as criaturas especificadas pela duração. Escolha antipatia ou simpatia como o efeito da aura.\n\nAntipatia. O encantamento faz com que as criaturas do tipo que você designou sintam um impulso intenso de deixar a área e evitar o alvo. Quando tal criatura puder ver o alvo ou chegar a até 18 metros dele, ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou ficará amedrontada. A criatura permanece amedrontada enquanto puder ver o alvo ou estiver a até 18 metros dele. Enquanto estiver amedrontada pelo alvo, a criatura deve usar seu movimento para se mover até o local seguro mais próximo de onde não possa ver o alvo. Se a criatura se mover para mais de 18 metros de distância do alvo e não puder vê-lo, ela deixa de estar amedrontada, mas fica amedrontada novamente se recuperar a visão do alvo ou se mover para dentro de 18 metros dele.\n\nSimpatia. O encantamento faz com que as criaturas especificadas sintam um impulso intenso de se aproximar do alvo enquanto estiverem a até 18 metros dele ou puderem vê-lo. Quando tal criatura puder ver o alvo ou chegar a até 18 metros dele, ela deve ser bem-sucedida em uma salvaguarda de Sabedoria ou usará seu movimento em cada um dos seus turnos para entrar na área ou se mover até o alcance do alvo. Quando a criatura tiver feito isso, ela não poderá se afastar voluntariamente do alvo.\n\nSe o alvo causar dano ou prejudicar de alguma forma uma criatura afetada, a criatura afetada pode fazer uma salvaguarda de Sabedoria para encerrar o efeito, conforme descrito abaixo.\n\nEncerrando o Efeito. Se uma criatura afetada terminar seu turno sem estar a até 18 metros do alvo nem puder vê-lo, ela faz uma salvaguarda de Sabedoria. Em uma salvaguarda bem-sucedida, a criatura não é mais afetada pelo alvo e reconhece o sentimento de repugnância ou atração como mágico. Além disso, uma criatura afetada pela magia tem direito a outra salvaguarda de Sabedoria a cada 24 horas enquanto a magia persistir.\n\nUma criatura bem-sucedida na salvaguarda contra este efeito fica imune a ele por 1 minuto, após o qual pode ser afetada novamente.", en: "This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200-foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura's effect.\n\nAntipathy. The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a Wisdom saving throw or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can't see the target. If the creature moves more than 60 feet from the target and can't see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it.\n\nSympathy. The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a Wisdom saving throw or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can't willingly move away from the target.\n\nIf the target damages or otherwise harms an affected creature, the affected creature can make a Wisdom saving throw to end the effect, as described below.\n\nEnding the Effect. If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a Wisdom saving throw. On a successful save, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another Wisdom saving throw every 24 hours while the spell persists.\n\nA creature that successfully saves against this effect is immune to it for 1 minute, after which time it can be affected again." } },
  { id: 'controlWeather',         level: 8, school: 'transmutation', classes: ['cleric','druid','wizard'], castingTime: '10 min', range: 'Self (5-mile radius)', components: 'V, S, M', duration: 'Conc. 8 hours', desc: { pt: "Você assume o controle do clima a até 7,5 quilômetros de você pela duração. Você deve estar ao ar livre para conjurar esta magia. Mover-se para um local onde não haja um caminho desobstruído para o céu encerra a magia prematuramente.\n\nQuando você conjura a magia, você muda as condições climáticas atuais, que são determinadas pelo Mestre com base no clima e na estação. Você pode alterar a precipitação, a temperatura e o vento. Leva 1d4 × 10 minutos para que as novas condições entrem em vigor. Uma vez que entrem em vigor, você pode mudar as condições novamente. Quando a magia termina, o clima retorna gradualmente ao normal.\n\nQuando você altera as condições climáticas, encontre uma condição atual nas tabelas a seguir e mude seu estágio em um nível, para cima ou para baixo. Ao mudar o vento, você pode mudar a direção dele.\n\nTabela: Controlar o Clima (Precipitação)\n\n| Estágio | Condição |\n|---|---|\n| 1 | Limpo |\n| 2 | Nuvens leves |\n| 3 | Encoberto ou névoa rasteira |\n| 4 | Chuva, granizo ou neve |\n| 5 | Chuva torrencial, granizo violento ou nevasca |\n| | |\n\nTabela: Controlar o Clima (Temperatura)\n\n| Estágio | Condição |\n|---|---|\n| 1 | Calor insuportável |\n| 2 | Muito quente |\n| 3 | Ameno |\n| 4 | Fresco |\n| 5 | Frio |\n| 6 | Frio ártico |\n| | |\n\nTabela: Controlar o Clima (Vento)\n\n| Estágio | Condição |\n|---|---|\n| 1 | Calmaria |\n| 2 | Vento moderado |\n| 3 | Vento forte |\n| 4 | Vendaval |\n| 5 | Tempestade |\n| | |", en: "You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don't have a clear path to the sky ends the spell early.\n\nWhen you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.\n\nWhen you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\n\nTable- Control Weather (Precipitation)\n\n| Stage | Condition                 |\n|-------|--------------------------------------------|\n| 1   | Clear                   |\n| 2   | Light clouds                |\n| 3   | Overcast or ground fog           |\n| 4   | Rain, hail, or snow            |\n| 5   | Torrential rain, driving hail, or blizzard |\n|    |                      |\n\nTable- Control Weather (Temperature)\n\n| Stage | Condition    |\n|-------|-----------------|\n| 1   | Unbearable heat |\n| 2   | Hot       |\n| 3   | Warm      |\n| 4   | Cool      |\n| 5   | Cold      |\n| 6   | Arctic cold   |\n|    |         |\n\nTable- Control Weather (Wind)\n\n| Stage | Condition   |\n|-------|---------------|\n| 1   | Calm     |\n| 2   | Moderate wind |\n| 3   | Strong wind  |\n| 4   | Gale     |\n| 5   | Storm     |\n|    |        |" } },
  { id: 'earthquake',             level: 8, school: 'evocation',    classes: ['cleric','druid','sorcerer'], castingTime: '1 action', range: '500 ft', components: 'V, S, M', duration: 'Conc. 1 min', desc: { pt: "Você cria uma perturbação sísmica em um ponto no chão que você possa ver dentro do alcance. Pela duração, um tremor intenso rasga o chão em um círculo com raio de 30 metros centrado naquele ponto e abala criaturas e estruturas em contato com o chão naquela área.\n\nO chão na área torna-se terreno difícil.\n\nCada criatura no chão que estiver se concentrando deve realizar um teste de resistência de Constituição. Em uma falha na salvaguarda, a concentração da criatura é interrompida.\n\nQuando você conjura esta magia e ao final de cada turno que você passar se concentrando nela, cada criatura no chão na área deve realizar um teste de resistência de Destreza. Em uma falha na salvaguarda, a criatura é derrubada no chão (caída).\n\nEsta magia pode ter efeitos adicionais dependendo do terreno na área, conforme determinado pelo Mestre.\n\nFissuras. Fissuras se abrem por toda a área da magia no início do seu próximo turno após você conjurar a magia. Um total de 1d6 fissuras se abrem em locais escolhidos pelo Mestre. Cada uma tem 1d10 × 3 metros de profundidade, 3 metros de largura e se estende de uma borda da área da magia até o lado oposto. Uma criatura que estiver no local onde uma fissura se abre deve ser bem-sucedida em um teste de resistência de Destreza ou cairá dentro dela. Uma criatura bem-sucedida na salvaguarda se move com a borda da fissura à medida que ela se abre.\n\nUma fissura que se abre sob uma estrutura faz com que ela desmorone automaticamente (veja abaixo).\n\nEstruturas. O tremor causa 50 de dano contundente a qualquer estrutura em contato com o chão na área quando você conjura a magia e no início de cada um dos seus turnos até a magia terminar. Se uma estrutura for reduzida a 0 pontos de vida, ela desmorona e potencialmente causa dano a criaturas próximas. Uma criatura a uma distância menor que a metade da altura da estrutura deve realizar um teste de resistência de Destreza. Em uma falha na salvaguarda, a criatura sofre 5d6 de dano contundente, é derrubada no chão e fica soterrada nos escombros, exigindo um teste de Força (Atletismo) CD 20 como uma ação para escapar. O Mestre pode ajustar a CD para mais ou para menos, dependendo da natureza dos escombros. Em uma salvaguarda bem-sucedida, a criatura sofre metade desse dano e não cai no chão nem fica soterrada.", en: "You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot radius circle centered on that point and shakes creatures and structures in contact with the ground in that area.\n\nThe ground in the area becomes difficult terrain.\n\nEach creature on the ground that is concentrating must make a Constitution saving throw. On a failed save, the creature's concentration is broken.\n\nWhen you cast this spell and at the end of each turn you spend concentrating on it, each creature on the ground in the area must make a Dexterity saving throw. On a failed save, the creature is knocked prone.\n\nThis spell can have additional effects depending on the terrain in the area, as determined by the GM.\n\nFissures. Fissures open throughout the spell's area at the start of your next turn after you cast the spell. A total of 1d6 such fissures open in locations chosen by the GM. Each is 1d10 × 10 feet deep, 10 feet wide, and extends from one edge of the spell's area to the opposite side. A creature standing on a spot where a fissure opens must succeed on a Dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens.\n\nA fissure that opens beneath a structure causes it to automatically collapse (see below).\n\nStructures. The tremor deals 50 bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the start of each of your turns until the spell ends. If a structure drops to 0 hit points, it collapses and potentially damages nearby creatures. A creature within half the distance of a structure's height must make a Dexterity saving throw. On a failed save, the creature takes 5d6 bludgeoning damage, is knocked prone, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. The GM can adjust the DC higher or lower, depending on the nature of the rubble. On a successful save, the creature takes half as much damage and doesn't fall prone or become buried." } },
  { id: 'feeblemind',             level: 8, school: 'enchantment',  classes: ['bard','druid','sorcerer','warlock','wizard'], castingTime: '1 action', range: '150 ft', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você explode a mente de uma criatura que você possa ver dentro do alcance, tentando despedaçar seu intelecto e sua personalidade. O alvo sofre 4d6 de dano psíquico e deve realizar um teste de resistência de Inteligência.\n\nEm uma falha na salvaguarda, os valores de Inteligência e Carisma da criatura tornam-se 1. A criatura não pode conjurar magias, ativar itens mágicos, compreender idiomas ou se comunicar de qualquer forma inteligível. A criatura pode, no entanto, identificar seus amigos, segui-los e até protegê-los.\n\nAo final de cada período de 30 dias, a criatura pode repetir seu teste de resistência contra esta magia. Se for bem-sucedida em sua salvaguarda, a magia termina.\n\nA magia também pode ser encerrada por restauração maior, cura completa ou desejo.", en: "You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an Intelligence saving throw.\n\nOn a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them.\n\nAt the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends.\n\nThe spell can also be ended by greater restoration, heal, or wish." } },

  // === LEVEL 9 ADICIONAIS ===
  { id: 'foresight',              level: 9, school: 'divination',   classes: ['bard','druid','warlock','wizard'], castingTime: '1 min', range: 'Touch', components: 'V, S, M', duration: '8 hours', desc: { pt: "Você toca uma criatura voluntária e concede a ela uma capacidade limitada de enxergar o futuro imediato. Pela duração, o alvo não pode ser surpreendido e tem vantagem em jogadas de ataque, testes de atributo e testes de resistência. Além disso, outras criaturas têm desvantagem em jogadas de ataque contra o alvo pela duração.\n\nEsta magia termina imediatamente se você a conjurar novamente antes que sua duração termine.", en: "You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration.\n\nThis spell immediately ends if you cast it again before its duration ends." } },
  { id: 'shapechange',            level: 9, school: 'transmutation', classes: ['druid','wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Conc. 1 hour', desc: { pt: "Você assume a forma de uma criatura diferente pela duração. A nova forma pode ser de qualquer criatura com nível de desafio igual ou inferior ao seu nível. A criatura não pode ser um constructo nem um morto-vivo, e você precisa ter visto esse tipo de criatura pelo menos uma vez. Você se transforma em um exemplar médio dessa criatura, sem quaisquer níveis de classe ou o traço Conjuração.\n\nSuas estatísticas de jogo são substituídas pelas estatísticas da criatura escolhida, embora você preserve seu alinhamento e seus valores de Inteligência, Sabedoria e Carisma. Você também preserva todas as suas proficiências em perícias e testes de resistência, além de adquirir as da criatura. Se a criatura tiver a mesma proficiência que você e o bônus listado nas estatísticas dela for maior que o seu, use o bônus da criatura no lugar do seu. Você não pode usar nenhuma ação lendária ou ação de covil da nova forma.\n\nVocê assume os Pontos de Vida e Dados de Vida da nova forma. Quando reverte à sua forma normal, você retorna à quantidade de Pontos de Vida que possuía antes de se transformar. Se reverter como resultado de cair a 0 Pontos de Vida, qualquer dano excedente é transferido para a sua forma normal. Desde que o dano excedente não reduza a sua forma normal a 0 Pontos de Vida, você não fica inconsciente.\n\nVocê preserva os benefícios de quaisquer características da sua classe, raça ou outra fonte e pode usá-las, contanto que a sua nova forma seja fisicamente capaz de fazê-lo. Você não pode usar quaisquer sentidos especiais que possua (por exemplo, visão no escuro), a menos que sua nova forma também tenha esse sentido. Você só pode falar se a criatura normalmente for capaz de falar.\n\nQuando se transforma, você escolhe se o seu equipamento cai no chão, funde-se à nova forma ou é vestido por ela. O equipamento vestido funciona normalmente. O Mestre determina se é viável para a nova forma vestir uma peça de equipamento, com base na forma e tamanho da criatura. Seu equipamento não muda de forma ou tamanho para se ajustar à nova forma, e qualquer equipamento que a nova forma não possa usar deve cair no chão ou fundir-se à sua nova forma. O equipamento fundido não tem efeito nesse estado.\n\nDurante a duração desta magia, você pode usar sua ação para assumir uma forma diferente seguindo as mesmas restrições e regras da forma original, com uma exceção: se a sua nova forma tiver mais Pontos de Vida que a atual, seus Pontos de Vida permanecem no valor atual.", en: "You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can't be a construct or an undead, and you must have seen the sort of creature at least once. You transform into an average example of that creature, one without any class levels or the Spellcasting trait.\n\nYour game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores. You also retain all of your skill and saving throw proficiencies, in addition to gaining those of the creature. If the creature has the same proficiency as you and the bonus listed in its statistics is higher than yours, use the creature's bonus in place of yours. You can't use any legendary actions or lair actions of the new form.\n\nYou assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn't reduce your normal form to 0 hit points, you aren't knocked unconscious.\n\nYou retain the benefit of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can't use any special senses you have (for example, darkvision) unless your new form also has that sense. You can only speak if the creature can normally speak.\n\nWhen you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions as normal. The GM determines whether it is practical for the new form to wear a piece of equipment, based on the creature's shape and size. Your equipment doesn't change shape or size to match the new form, and any equipment that the new form can't wear must either fall to the ground or merge into your new form. Equipment that merges has no effect in that state.\n\nDuring this spell's duration, you can use your action to assume a different form following the same restrictions and rules for the original form, with one exception: if your new form has more hit points than your current one, your hit points remain at their current value." } },
  { id: 'stormOfVengeance',       level: 9, school: 'conjuration',  classes: ['druid'], castingTime: '1 action', range: 'Sight', components: 'V, S', duration: 'Conc. 1 min', desc: { pt: "Uma nuvem de tempestade revolta se forma, centrada em um ponto que você possa ver e se espalhando em um raio de 108 metros. Relâmpagos lampejam na área, trovões rugem e ventos fortes bramem. Cada criatura sob a nuvem (a não mais de 1.500 metros abaixo dela) quando ela surgir deve realizar um teste de resistência de Constituição. Se falhar, a criatura sofre 2d6 de dano trovejante e fica surda por 5 minutos.\n\nA cada rodada em que mantiver concentração nesta magia, a tempestade produz efeitos diferentes no seu turno.\n\nRodada 2. Chuva ácida cai da nuvem. Cada criatura e objeto sob a nuvem sofre 1d6 de dano de ácido.\n\nRodada 3. Você invoca seis relâmpagos da nuvem para atingir seis criaturas ou objetos de sua escolha sob a nuvem. Uma mesma criatura ou objeto não pode ser atingido por mais de um relâmpago. Uma criatura atingida deve realizar um teste de resistência de Destreza. A criatura sofre 10d6 de dano elétrico em caso de falha no teste, ou metade desse dano em caso de sucesso.\n\nRodada 4. Pedras de granizo caem da nuvem. Cada criatura sob a nuvem sofre 2d6 de dano contundente.\n\nRodadas 5-10. Rajadas de vento e chuva congelante assolam a área sob a nuvem. A área se torna terreno difícil e fica fortemente obscurecida. Cada criatura ali sofre 1d6 de dano de frio. Ataques com armas à distância na área tornam-se impossíveis. O vento e a chuva contam como uma distração severa para fins de manter concentração em magias. Finalmente, rajadas de vento forte (variando de 30 a 75 quilômetros por hora) dispersam automaticamente nevoeiros, névoas e fenômenos similares na área, sejam mundanos ou mágicos.", en: "A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a Constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes.\n\nEach round you maintain concentration on this spell, the storm produces different effects on your turn.\n\nRound 2. Acidic rain falls from the cloud. Each creature and object under the cloud takes 1d6 acid damage.\n\nRound 3. You call six bolts of lightning from the cloud to strike six creatures or objects of your choice beneath the cloud. A given creature or object can't be struck by more than one bolt. A struck creature must make a Dexterity saving throw. The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\n\nRound 4. Hailstones rain down from the cloud. Each creature under the cloud takes 2d6 bludgeoning damage.\n\nRound 5-10. Gusts and freezing rain assail the area under the cloud. The area becomes difficult terrain and is heavily obscured. Each creature there takes 1d6 cold damage. Ranged weapon attacks in the area are impossible. The wind and rain count as a severe distraction for the purposes of maintaining concentration on spells. Finally, gusts of strong wind (ranging from 20 to 50 miles per hour) automatically disperse fog, mists, and similar phenomena in the area, whether mundane or magical." } },
  { id: 'trueResurrection',       level: 9, school: 'necromancy',   classes: ['cleric','druid'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instant', desc: { pt: "Você toca uma criatura que esteja morta há não mais de 200 anos e que tenha morrido por qualquer motivo exceto velhice. A criatura é revivida com todos os seus Pontos de Vida.\nEsta magia fecha todos os ferimentos, neutraliza qualquer veneno, cura todos os contágios mágicos e remove quaisquer maldições que afetavam a criatura quando ela morreu. A magia substitui órgãos e membros danificados ou ausentes. Se a criatura era um Morto-Vivo, ela é restaurada à sua forma não morta-viva.\nA magia pode fornecer um novo corpo se o original não existir mais, caso em que você deve falar o nome da criatura. A criatura então aparece em um espaço desocupado à sua escolha a até 3 metros de você.", en: "You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature's soul is free and willing, the creature is restored to life with all its hit points.\n\nThis spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs. If the creature was undead, it is restored to its non-undead form.\n\nThe spell can even provide a new body if the original no longer exists, in which case you must speak the creature's name. The creature then appears in an unoccupied space you choose within 10 feet of you." } },
];

// === WILD SHAPE BEASTS ===
